// ── Preset overlay keybindings ────────────────────────────────────────

fn handle_preset_overlay_key(app: &mut AppState, key: KeyEvent) {
    // If in naming mode, handle text input
    if let Some(input) = &mut app.preset.naming_input {
        match key.code {
            KeyCode::Enter => {
                let name = input.text.trim().to_string();
                if name.is_empty() {
                    app.preset.naming_input = None;
                    return;
                }
                let preset = super::presets::TuiPreset::from_pill_state(
                    &name,
                    &app.convert.format,
                    &app.convert.output_options,
                    &app.convert.metadata,
                );
                match super::presets::save_preset_with_db(&preset, &app.db) {
                    Ok(_) => {
                        app.preset
                            .set_active_preset_path(name.clone(), super::presets::preset_file_path(&name));
                        app.preset.modified = false;
                        app.preset.naming_input = None;
                        app.preset.overlay_open = false;
                        app.set_status(format!("Saved preset: {}", name));
                    }
                    Err(e) => {
                        app.preset.naming_input = None;
                        app.set_status(format!("Save failed: {}", e));
                    }
                }
            }
            KeyCode::Esc => {
                app.preset.naming_input = None;
            }
            _ => {
                super::text_input::handle_text_input_key(input, &key);
            }
        }
        return;
    }

    // Normal overlay navigation
    match key.code {
        KeyCode::Esc => {
            app.preset.overlay_open = false;
        }
        KeyCode::Up | KeyCode::Char('k') => {
            if app.preset.overlay_selected > 0 {
                app.preset.overlay_selected -= 1;
            }
        }
        KeyCode::Down | KeyCode::Char('j') => {
            if app.preset.overlay_selected + 1 < app.preset.overlay_list.len() {
                app.preset.overlay_selected += 1;
            }
        }
        KeyCode::Enter => {
            // Load selected preset
            if let Some(name) = app
                .preset
                .overlay_list
                .get(app.preset.overlay_selected)
                .cloned()
            {
                match super::presets::load_preset(&name) {
                    Ok(preset) => {
                        let report = preset.apply_to_pills(
                            &mut app.convert.format,
                            &mut app.convert.output_options,
                            &mut app.convert.metadata,
                        );
                        app.preset
                            .set_active_preset_path(name.clone(), super::presets::preset_file_path(&name));
                        app.preset.modified = false;
                        app.preset.overlay_open = false;
                        app.set_status(format!(
                            "Loaded preset: {}{}",
                            name,
                            report.status_suffix()
                        ));
                    }
                    Err(e) => {
                        app.set_status(format!("Load failed: {}", e));
                    }
                }
            }
        }
        KeyCode::Char('n') => {
            // Save as new preset
            app.preset.naming_input = Some(super::text_input::TextInputState::empty());
        }
        KeyCode::Char('d') => {
            // Duplicate selected preset
            if let Some(name) = app
                .preset
                .overlay_list
                .get(app.preset.overlay_selected)
                .cloned()
            {
                match super::presets::load_preset(&name) {
                    Ok(mut preset) => {
                        let base = format!("{}-copy", name);
                        let new_name = super::presets::find_unique_preset_name(
                            &base,
                            &app.preset.overlay_list,
                        );
                        preset.name = new_name;
                        match super::presets::save_preset_with_db(&preset, &app.db) {
                            Ok(_) => {
                                let saved_name = preset.name.clone();
                                app.preset.overlay_list = super::presets::list_presets();
                                app.set_status(format!("Duplicated: {} → {}", name, saved_name));
                            }
                            Err(e) => app.set_status(format!("Duplicate failed: {}", e)),
                        }
                    }
                    Err(e) => app.set_status(format!("Load failed: {}", e)),
                }
            }
        }
        KeyCode::Char('x') => {
            // Delete selected preset
            if let Some(name) = app
                .preset
                .overlay_list
                .get(app.preset.overlay_selected)
                .cloned()
            {
                match super::presets::delete_preset_with_db(&name, &app.db) {
                    Ok(_) => {
                        // If we deleted the active preset, clear it
                        if app.preset.active_preset.as_deref() == Some(&name) {
                            app.preset.clear_active_preset();
                        }
                        app.preset.overlay_list = super::presets::list_presets();
                        // Clamp selection
                        if app.preset.overlay_selected >= app.preset.overlay_list.len()
                            && !app.preset.overlay_list.is_empty()
                        {
                            app.preset.overlay_selected = app.preset.overlay_list.len() - 1;
                        }
                        app.set_status(format!("Deleted preset: {}", name));
                    }
                    Err(e) => app.set_status(format!("Delete failed: {}", e)),
                }
            }
        }
        _ => {}
    }
}


fn cycle_archive_listing_mode(app: &mut AppState, forward: bool) {
    let current = super::archive_listing::ArchiveListingMode::from_config(
        &app.config.performance.browsing.archive_listing,
    );
    let next = if forward { current.next() } else { current.previous() };
    app.config.performance.browsing.archive_listing = next.config_value().to_string();
    match app.config.save() {
        Ok(()) => app.set_status(format!("archive listing: {}", next.display_label())),
        Err(err) => app.set_status(format!("archive listing updated but config save failed: {}", err)),
    }
}

fn adjust_archive_listing_timeout(app: &mut AppState, delta: i64) {
    let current = app.config.performance.browsing.archive_listing_timeout as i64;
    let next = (current + delta).clamp(0, 600) as u64;
    app.config.performance.browsing.archive_listing_timeout = next;
    let label = if next == 0 {
        "disabled".to_string()
    } else {
        format!("{}s", next)
    };
    match app.config.save() {
        Ok(()) => app.set_status(format!("archive listing timeout: {}", label)),
        Err(err) => app.set_status(format!("archive listing timeout updated but config save failed: {}", err)),
    }
}

// ── Browse screen keybindings ────────────────────────────────────────

fn handle_browse_key(app: &mut AppState, key: KeyEvent, tx: &mpsc::Sender<AppMessage>) {
    use crate::convert::classify::EntryKind;

    // Track whether selection may have changed; if so, probe the new selection.
    let mut selection_may_have_changed = false;

    match (key.code, key.modifiers) {
        // Keyboard access for Browse info-pane metadata rows. The file list
        // remains the default focus; Tab explicitly enters/cycles metadata
        // focus, and Enter or any printable key begins inline editing there.
        (KeyCode::Tab, KeyModifiers::NONE) => {
            cycle_browse_metadata_focus(app, true);
        }
        (KeyCode::BackTab, _) => {
            cycle_browse_metadata_focus(app, false);
        }
        (KeyCode::Up, KeyModifiers::NONE) if browse_metadata_focus_field(app).is_some() => {
            cycle_browse_metadata_focus(app, false);
        }
        (KeyCode::Down, KeyModifiers::NONE) if browse_metadata_focus_field(app).is_some() => {
            cycle_browse_metadata_focus(app, true);
        }
        (KeyCode::Left, KeyModifiers::NONE) if browse_metadata_focus_field(app).is_some() => {
            clear_browse_info_focus(app);
            app.set_status("Browse file-list focus");
        }
        (KeyCode::Enter, KeyModifiers::NONE) if browse_metadata_focus_field(app).is_some() => {
            if let Some(field) = browse_metadata_focus_field(app) {
                begin_browse_metadata_inline_edit(app, field, None);
            }
        }
        (KeyCode::Char(_), mods)
            if browse_metadata_focus_field(app).is_some()
                && (mods.is_empty() || mods == KeyModifiers::SHIFT) =>
        {
            if let Some(field) = browse_metadata_focus_field(app) {
                begin_browse_metadata_inline_edit(app, field, Some(key));
            }
        }

        // Shift+movement: enter/continue modal range selection and preview.
        (KeyCode::Up, KeyModifiers::SHIFT) => {
            app.browse.begin_range_selection();
            app.browse.move_up();
            app.browse.update_range_preview();
            selection_may_have_changed = true;
        }
        (KeyCode::Down, KeyModifiers::SHIFT) => {
            app.browse.begin_range_selection();
            app.browse.move_down();
            app.browse.update_range_preview();
            selection_may_have_changed = true;
        }
        (KeyCode::Home, KeyModifiers::SHIFT) => {
            app.browse.begin_range_selection();
            app.browse.move_top();
            app.browse.update_range_preview();
            selection_may_have_changed = true;
        }
        (KeyCode::End, KeyModifiers::SHIFT) => {
            app.browse.begin_range_selection();
            app.browse.move_bottom();
            app.browse.update_range_preview();
            selection_may_have_changed = true;
        }
        (KeyCode::PageUp, KeyModifiers::SHIFT) => {
            app.browse.begin_range_selection();
            app.browse.page_up();
            app.browse.update_range_preview();
            selection_may_have_changed = true;
        }
        (KeyCode::PageDown, KeyModifiers::SHIFT) => {
            app.browse.begin_range_selection();
            app.browse.page_down();
            app.browse.update_range_preview();
            selection_may_have_changed = true;
        }

        // Plain navigation commits a live range before moving.
        (KeyCode::Up, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            app.browse.move_up();
            selection_may_have_changed = true;
        }
        (KeyCode::Down, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            app.browse.move_down();
            selection_may_have_changed = true;
        }
        (KeyCode::Home, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            app.browse.move_top();
            selection_may_have_changed = true;
        }
        (KeyCode::End, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            app.browse.move_bottom();
            selection_may_have_changed = true;
        }
        (KeyCode::PageUp, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            app.browse.page_up();
            selection_may_have_changed = true;
        }
        (KeyCode::PageDown, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            app.browse.page_down();
            selection_may_have_changed = true;
        }

        // Go up (parent directory / archive level). Non-Shift navigation commits any
        // live range before moving away from the preview.
        (KeyCode::Left, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            if app.browse.is_in_archive() {
                if !app.browse.go_up_in_archive() {
                    exit_browse_archive(app, tx);
                }
            } else {
                app.browse.go_parent();
            }
            selection_may_have_changed = true;
        }

        // Backspace: delete last char from type-ahead buffer when active,
        // otherwise go to parent directory.
        (KeyCode::Backspace, _) => {
            if app.browse.type_ahead_active() {
                app.browse.type_ahead_pop();
                selection_may_have_changed = true;
            } else {
                app.browse.commit_range_selection();
                if app.browse.is_in_archive() {
                    if !app.browse.go_up_in_archive() {
                        exit_browse_archive(app, tx);
                    }
                } else {
                    app.browse.go_parent();
                }
                selection_may_have_changed = true;
            }
        }

        // Delete: filesystem entries are permanently deleted after confirmation;
        // archive entries are removed from deferred-save staging and repackaged
        // later when the user leaves the archive/screen/quits.
        (KeyCode::Delete, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            if app.browse.is_in_archive() {
                start_browse_archive_entry_delete(app, tx);
            } else {
                super::command::execute_command(app, super::command::Command::Delete, tx);
            }
        }

        // Force archive listing even when Performance > Browsing would normally skip it.
        (KeyCode::Char('l'), KeyModifiers::NONE) => {
            if let Some(entry) = app.browse.selected_entry() {
                if matches!(entry.kind, EntryKind::Archive) && !app.browse.is_in_archive() {
                    start_browse_archive_listing(app, entry.path.clone(), tx, true);
                } else {
                    app.browse.type_ahead_push('l');
                    selection_may_have_changed = true;
                }
            }
        }

        // Rename stays available through the context menu and `:rename`.
        // Do not bind F-keys here: they are reserved by terminal multiplexers
        // such as byobu and are forbidden by the Browse selection brief.

        // Enter directory/archive or select file
        (KeyCode::Right, KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            if let Some(entry) = app.browse.selected_entry() {
                if entry.is_navigable_dir() {
                    if app.browse.is_in_archive() {
                        // Navigate into subdirectory inside archive.
                        let item_name = entry
                            .path
                            .file_name()
                            .map(|n| n.to_string_lossy().to_string())
                            .unwrap_or_default();
                        let inner = if let Some(ref arc) = app.browse.archive {
                            if arc.inner_path.is_empty() {
                                item_name
                            } else {
                                format!("{}/{}", arc.inner_path, item_name)
                            }
                        } else {
                            item_name
                        };
                        app.browse.enter_archive_dir(&inner);
                    } else {
                        app.browse.enter_selected();
                    }
                    selection_may_have_changed = true;
                }
            }
        }
        (KeyCode::Enter, KeyModifiers::NONE) if app.browse.is_range_mode() => {
            app.browse.commit_range_selection();
            app.set_status("Range selected");
            selection_may_have_changed = true;
        }
        (KeyCode::Enter, KeyModifiers::NONE) => {
            if let Some(entry) = app.browse.selected_entry() {
                match &entry.kind {
                    _ if entry.is_navigable_dir() && app.browse.is_in_archive() => {
                        if matches!(entry.kind, EntryKind::ParentDir) {
                            if !app.browse.go_up_in_archive() {
                                exit_browse_archive(app, tx);
                            }
                        } else {
                            let item_name = entry
                                .path
                                .file_name()
                                .map(|n| n.to_string_lossy().to_string())
                                .unwrap_or_default();
                            let inner = if let Some(ref arc) = app.browse.archive {
                                if arc.inner_path.is_empty() {
                                    item_name
                                } else {
                                    format!("{}/{}", arc.inner_path, item_name)
                                }
                            } else {
                                item_name
                            };
                            app.browse.enter_archive_dir(&inner);
                        }
                        selection_may_have_changed = true;
                    }
                    _ if entry.is_navigable_dir() => {
                        app.browse.enter_selected();
                        selection_may_have_changed = true;
                    }
                    EntryKind::Archive if !app.browse.is_in_archive() => {
                        start_browse_archive_listing(app, entry.path.clone(), tx, false);
                    }
                    EntryKind::AudioFile(_) if app.browse.is_in_archive() => {
                        // Archive entries are represented by synthetic paths. Do not launch
                        // unmanaged temp extraction from Enter: the previous helper extracted
                        // into a deterministic directory, returned only a status message, and
                        // left no ownership/cleanup model for the extracted file. Keep Enter as
                        // selection-only; archive mutations must use explicit archive-aware flows
                        // such as Rename or Edit Tags.
                        app.browse.toggle_selection();
                        app.set_status(
                            "archive entry selected; use Edit Tags or Rename for archive-aware changes",
                        );
                    }
                    _ => {
                        // Toggle selection — converting is via context menu or :queue.
                        app.browse.toggle_selection();
                    }
                }
            }
        }

        // Space: literal space in type-ahead; in range mode it commits;
        // otherwise it toggles the current row, anchors there, and advances.
        (KeyCode::Char(' '), KeyModifiers::NONE) => {
            if app.browse.type_ahead_active() {
                app.browse.type_ahead_push(' ');
                selection_may_have_changed = true;
            } else if app.browse.is_range_mode() {
                app.browse.commit_range_selection();
                app.set_status("Range selected");
                selection_may_have_changed = true;
            } else {
                app.browse.toggle_selection();
                app.browse.move_down();
                selection_may_have_changed = true;
            }
        }

        // Enhanced-key binding when Shift+Space is distinguishable. In legacy
        // terminals this degrades to ordinary Space before it reaches us.
        (KeyCode::Char(' '), KeyModifiers::SHIFT) => {
            app.browse.extend_selection_from_anchor_to_index(app.browse.selected_index);
            app.set_status("Selection extended from anchor");
            selection_may_have_changed = true;
        }

        // Baseline modal range selection. Movement previews; Enter/Space
        // commits; Esc restores the pre-range mark set.
        (KeyCode::Char('r'), KeyModifiers::ALT) => {
            app.browse.begin_range_selection();
            app.set_status("Range select: move, Enter/Space commits, Esc cancels");
            selection_may_have_changed = true;
        }

        // Bulk mark operations over the visible set. Alt is the terminal Meta
        // baseline on Linux/Windows and works on macOS when Option-as-Meta is
        // enabled. `*` remains an unconditional invert fallback.
        (KeyCode::Char('a'), KeyModifiers::ALT) => {
            app.browse.commit_range_selection();
            app.browse.toggle_all_visible_selection();
            selection_may_have_changed = true;
        }
        (KeyCode::Char('i'), KeyModifiers::ALT) | (KeyCode::Char('*'), KeyModifiers::NONE) => {
            app.browse.commit_range_selection();
            app.browse.invert_visible_selection();
            selection_may_have_changed = true;
        }

        // Toggle hidden files
        (KeyCode::Char('.'), KeyModifiers::NONE) => {
            app.browse.toggle_hidden_with_search(Some(tx));
            persist_browse_config(app);
            selection_may_have_changed = true;
        }

        // Open the search panel or refocus the input.
        (KeyCode::Char('/'), KeyModifiers::NONE) | (KeyCode::Char('/'), KeyModifiers::SHIFT) => {
            if app.browse.search.active {
                // Refocus on input (e.g., from Results focus).
                app.browse.search.focus = super::browse::SearchFocus::Input;
            } else {
                app.browse.open_search();
            }
        }

        // Esc escalation: options menu → type-ahead → search → visual mode → multi-selection → text filter → archive
        (KeyCode::Esc, _) => {
            if app.browse.options_menu.is_open() {
                app.browse.back_or_close_options_menu();
            } else if app.cancel_archive_listing() {
                app.set_status("archive listing cancelled");
            } else if app.browse.type_ahead_active() {
                app.browse.clear_type_ahead();
            } else if app.browse.search.active {
                app.browse.close_search();
            } else if app.browse.cancel_range_selection() {
                app.set_status("Range selection cancelled");
                selection_may_have_changed = true;
            } else if app.browse_info_focus.is_some() {
                clear_browse_info_focus(app);
                app.set_status("Browse file-list focus");
            } else if !app.browse.multi_selected.is_empty() {
                app.browse.clear_multi_selection();
            } else if !app.browse.filter_text.is_empty() {
                app.browse.clear_filter();
                selection_may_have_changed = true;
            } else if app.browse.is_in_archive() {
                // Esc in archive: go up one level or exit.
                if !app.browse.go_up_in_archive() {
                    exit_browse_archive(app, tx);
                }
                selection_may_have_changed = true;
            }
            // Browse is home — Esc with nothing to clear is a no-op.
        }

        // Ctrl+E / Alt+P = open metadata editor for selected audio file(s).
        // If the selection has no audio content, stub status for future
        // properties dialog.
        (KeyCode::Char('e'), KeyModifiers::CONTROL)
        | (KeyCode::Char('p'), KeyModifiers::ALT) => {
            clear_browse_info_focus(app);
            let guard_paths = super::command::collect_selection_for_file_ops(app);
            if super::command::maybe_confirm_bulk_operation(
                app,
                BulkOperationKind::EditMetadata,
                BulkGuardCommand::OpenMetadataEditor,
                &guard_paths,
            ) {
                return;
            }
            open_metadata_editor_with_tx(app, tx);
        }

        // Type-ahead navigation: bare letter/number keys jump to the
        // first entry whose name starts with the accumulated prefix.
        (KeyCode::Char(c), mods) if mods.is_empty() || mods == KeyModifiers::SHIFT => {
            app.browse.commit_range_selection();
            app.browse.type_ahead_push(c);
            selection_may_have_changed = true;
        }

        _ => {}
    }

    if selection_may_have_changed {
        if app.cancel_archive_listing() {
            app.set_status("archive listing cancelled: browse navigation changed");
        }
        app.cancel_browse_convert_expansion_for_browse_change("browse selection changed");
        app.browse.probe_current_with_db(tx, Some(&app.db));
            super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
    }
}

/// Hybrid dispatcher used while the live text filter input is open.
/// Arrow keys / page keys navigate the filtered list; everything else is
/// fed into the text input. Enter commits, Esc cancels (restores prior filter).
/// Handle keys when the search panel is active.
fn handle_browse_search_key(app: &mut AppState, key: KeyEvent, tx: &mpsc::Sender<AppMessage>) {
    use super::browse::SearchFocus;

    match app.browse.search.focus {
        SearchFocus::Input => {
            match key.code {
                KeyCode::Esc => {
                    app.browse.close_search();
                }
                KeyCode::Enter => {
                    app.browse.execute_search(Some(tx));
                }
                KeyCode::Tab => {
                    app.browse.search.focus = SearchFocus::Recursive;
                }
                KeyCode::Down => {
                    // Move focus to results list.
                    app.browse.execute_search(Some(tx));
                    app.browse.search.focus = super::browse::SearchFocus::Results;
                }
                _ => {
                    super::text_input::handle_text_input_key(&mut app.browse.search.input, &key);
                    app.browse.search.last_keystroke = Some(std::time::Instant::now());
                }
            }
        }
        SearchFocus::Recursive => match key.code {
            KeyCode::Esc => {
                app.browse.close_search();
            }
            KeyCode::Tab => {
                app.browse.search.focus = SearchFocus::Mode;
            }
            KeyCode::BackTab => {
                app.browse.search.focus = SearchFocus::Input;
            }
            KeyCode::Enter | KeyCode::Char(' ') => {
                app.browse.search.recursive = !app.browse.search.recursive;
                app.browse.search.last_keystroke = Some(std::time::Instant::now());
            }
            _ => {}
        },
        SearchFocus::Mode => {
            match key.code {
                KeyCode::Esc => {
                    app.browse.close_search();
                }
                KeyCode::Tab => {
                    app.browse.search.focus = SearchFocus::Sort;
                }
                KeyCode::BackTab => {
                    app.browse.search.focus = SearchFocus::Recursive;
                }
                KeyCode::Enter | KeyCode::Char(' ') => {
                    app.browse.search.mode = app.browse.search.mode.cycle();
                    // If switching away from tags and a tag sort is active, reset to Score.
                    if app.browse.search.mode == super::browse::SearchMode::Filename
                        && app.browse.search.sort.is_tag_sort()
                    {
                        app.browse.search.sort = super::browse::SearchSort::Score;
                        app.browse.search.sort_dir = super::browse::SortDir::Desc;
                    }
                    app.browse.search.last_keystroke = Some(std::time::Instant::now());
                }
                _ => {}
            }
        }
        SearchFocus::Sort => {
            match key.code {
                KeyCode::Esc => {
                    app.browse.close_search();
                }
                KeyCode::Tab => {
                    app.browse.search.focus = SearchFocus::AudioOnly;
                }
                KeyCode::BackTab => {
                    app.browse.search.focus = SearchFocus::Mode;
                }
                KeyCode::Enter | KeyCode::Char(' ') => {
                    let tag_mode = matches!(
                        app.browse.search.mode,
                        super::browse::SearchMode::Tags | super::browse::SearchMode::Both
                    );
                    app.browse.search.sort = app.browse.search.sort.cycle_with_mode(tag_mode);
                    app.browse.search.sort_dir = match app.browse.search.sort {
                        super::browse::SearchSort::Score => super::browse::SortDir::Desc,
                        _ => super::browse::SortDir::Asc,
                    };
                    app.browse.search.last_keystroke = Some(std::time::Instant::now());
                }
                // Shift+Enter or 'r' to reverse direction.
                KeyCode::Char('r') => {
                    app.browse.search.sort_dir = app.browse.search.sort_dir.toggle();
                    app.browse.search.last_keystroke = Some(std::time::Instant::now());
                }
                _ => {}
            }
        }
        SearchFocus::AudioOnly => match key.code {
            KeyCode::Esc => {
                app.browse.close_search();
            }
            KeyCode::Tab => {
                app.browse.search.focus = SearchFocus::Input;
            }
            KeyCode::BackTab => {
                app.browse.search.focus = SearchFocus::Sort;
            }
            KeyCode::Enter | KeyCode::Char(' ') => {
                app.browse.search.audio_only = !app.browse.search.audio_only;
                app.browse.search.last_keystroke = Some(std::time::Instant::now());
            }
            _ => {}
        },
        SearchFocus::Results => {
            // Unreachable — Results focus skips this handler entirely.
        }
    }
}

fn handle_browse_filter_key(app: &mut AppState, key: KeyEvent, tx: &mpsc::Sender<AppMessage>) {
    use super::text_input::handle_text_input_key;

    match (key.code, key.modifiers) {
        (KeyCode::Enter, _) => {
            app.browse.close_filter_input(true);
            app.cancel_browse_convert_expansion_for_browse_change("browse filter changed");
            app.browse.probe_current_with_db(tx, Some(&app.db));
            super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
        }
        (KeyCode::Esc, _) => {
            app.browse.close_filter_input(false);
            app.cancel_browse_convert_expansion_for_browse_change("browse filter changed");
            app.browse.probe_current_with_db(tx, Some(&app.db));
            super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
        }
        // List navigation while filter input is open
        (KeyCode::Up, _) => {
            app.browse.move_up();
            app.cancel_browse_convert_expansion_for_browse_change("browse filter changed");
            app.browse.probe_current_with_db(tx, Some(&app.db));
            super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
        }
        (KeyCode::Down, _) => {
            app.browse.move_down();
            app.cancel_browse_convert_expansion_for_browse_change("browse filter changed");
            app.browse.probe_current_with_db(tx, Some(&app.db));
            super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
        }
        (KeyCode::PageUp, _) => {
            app.browse.page_up();
            app.cancel_browse_convert_expansion_for_browse_change("browse filter changed");
            app.browse.probe_current_with_db(tx, Some(&app.db));
            super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
        }
        (KeyCode::PageDown, _) => {
            app.browse.page_down();
            app.cancel_browse_convert_expansion_for_browse_change("browse filter changed");
            app.browse.probe_current_with_db(tx, Some(&app.db));
            super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
        }
        // Everything else: feed to the text input, then re-apply view
        _ => {
            if let Some(input) = &mut app.browse.filter_input {
                if handle_text_input_key(input, &key) {
                    app.browse.update_filter_from_input();
                    app.cancel_browse_convert_expansion_for_browse_change("browse filter changed");
                    app.browse.probe_current_with_db(tx, Some(&app.db));
                    super::disc_browser_actions::probe_selected_disc_after_cursor_move(app, tx);
                }
            }
        }
    }
}

fn handle_browse_path_input_key(app: &mut AppState, key: KeyEvent) {
    use super::text_input::{apply_path_completion, handle_text_input_key};

    match (key.code, key.modifiers) {
        (KeyCode::Enter, _) => {
            app.browse.close_path_input(true);
        }
        (KeyCode::Esc, _) => {
            app.browse.close_path_input(false);
        }
        (KeyCode::Tab, _) => {
            if let Some(input) = &mut app.browse.path_input {
                // Complete relative paths, including prefixed paths such as
                // `Music/Al`, against the active Browse directory. Absolute
                // and tilde-prefixed edits are handled as absolute inputs by
                // the completion helper.
                apply_path_completion(input, Some(app.browse.current_dir.as_path()), true);
            }
        }
        _ => {
            if let Some(input) = &mut app.browse.path_input {
                handle_text_input_key(input, &key);
            }
        }
    }
}

/// Load the selected browse entry based on the return target
/// Load the selected browse entry into the Convert source pane based on
/// `target`. Public because it's called by `context_menu::execute_context_action`
/// for the `OpenEntry` action as well.
pub fn load_browse_selection_pub(
    app: &mut AppState,
    path: std::path::PathBuf,
    target: super::browse::BrowseReturnTarget,
) {
    load_browse_selection(app, path, target);
}


fn archive_listing_password_for_path(
    app: &mut AppState,
    path: &std::path::Path,
) -> Result<Option<String>, String> {
    super::app::archive_password_for_path(app, path)
}

fn archive_listing_timeout_from_config(app: &AppState) -> Option<std::time::Duration> {
    match app.config.performance.browsing.archive_listing_timeout {
        0 => None,
        seconds => Some(std::time::Duration::from_secs(seconds)),
    }
}

pub(super) fn start_browse_archive_listing(
    app: &mut AppState,
    path: std::path::PathBuf,
    tx: &mpsc::Sender<AppMessage>,
    force: bool,
) {
    let mode = super::archive_listing::ArchiveListingMode::from_config(
        &app.config.performance.browsing.archive_listing,
    );

    if !force && matches!(mode, super::archive_listing::ArchiveListingMode::Never) {
        app.set_status("archive listing is disabled; press l to list this archive");
        return;
    }

    if !force
        && matches!(mode, super::archive_listing::ArchiveListingMode::Auto)
        && super::archive_listing::is_remote_filesystem(&path)
    {
        app.set_status("archive is on a network mount; press l to list contents");
        return;
    }

    let cache_key = match super::archive_listing::ArchiveListingCacheKey::for_path(&path) {
        Ok(key) => key,
        Err(err) => {
            app.set_status(format!("Archive error: cannot stat archive: {}", err));
            return;
        }
    };

    if let Some(listing) = app.cached_archive_listing(&cache_key) {
        let count = listing.entries.len();
        let password = match archive_listing_password_for_path(app, &path) {
            Ok(password) => password,
            Err(error) => {
                app.set_status(error);
                return;
            }
        };
        app.browse.enter_archive(listing, password);
        app.force_redraw = true;
        app.set_status(format!("Opened from cache ({} entries)", count));
        return;
    }

    let password = match archive_listing_password_for_path(app, &path) {
        Ok(password) => password,
        Err(error) => {
            app.set_status(error);
            return;
        }
    };
    let timeout = archive_listing_timeout_from_config(app);
    let (id, cancel) = app.begin_archive_listing(path.clone());
    let tx = tx.clone();
    let path_for_worker = path.clone();
    let cache_key_for_result = Some(cache_key.clone());

    app.set_status(match timeout {
        Some(timeout) => format!(
            "Loading archive... Esc cancels; timeout {}s",
            timeout.as_secs()
        ),
        None => "Loading archive... Esc cancels; no timeout".to_string(),
    });

    tokio::spawn(async move {
        let _ = tx
            .send(AppMessage::ArchiveListingProgress {
                id,
                archive_path: path_for_worker.clone(),
                message: "Listing archive contents... Esc cancels".to_string(),
            })
            .await;

        let result = super::archive_listing::list_archive_with_options(
            &path_for_worker,
            password.as_deref(),
            super::archive_listing::ArchiveListingOptions { timeout },
            cancel,
        )
        .await;

        let _ = tx
            .send(AppMessage::ArchiveListingComplete {
                id,
                archive_path: path_for_worker,
                cache_key: cache_key_for_result,
                result: Box::new(result),
                password,
            })
            .await;
    });
}

fn install_convert_source_with_async_probe(app: &mut AppState, path: std::path::PathBuf) {
    if super::command::browse_selection_contains_regular_audio_folder_for_convert(
        app,
        std::slice::from_ref(&path),
    ) {
        if let Some(tx) = app.tui_tx.clone() {
            super::command::start_browse_convert_folder_expansion(
                app,
                &tx,
                super::command::BrowseConvertExpansionTarget::ConvertSource,
                vec![path],
                0,
            );
        } else {
            app.set_status("Cannot expand folder: TUI worker channel is unavailable");
        }
        return;
    }

    app.cancel_browse_convert_expansion();

    if is_nonprobeable_source_for_probe(&path) {
        if let Some(tx) = app.tui_tx.clone() {
            install_archive_preview_convert_source(app, path, tx);
            return;
        }
    }

    app.probe_generation = app.probe_generation.saturating_add(1);
    let generation = app.probe_generation;
    let probe_notice = source_probe_initial_notice(&path);

    clear_source_metadata_in_convert(&mut app.convert);

    // Single-file source replacements abandon pending batch metadata from any
    // previous browse/queue handoff. Install only a cheap placeholder here;
    // SACD/DVD/Blu-ray/CUE/Lofty discovery runs on the blocking probe worker.
    let mut mode = SourceMode::from_single_pending_probe(path.clone(), probe_notice.clone());
    match &mut mode {
        SourceMode::Single { probe_notice: notice_slot, .. }
        | SourceMode::MultiTrack { probe_notice: notice_slot, .. } => {
            if notice_slot.is_none() {
                *notice_slot = probe_notice.clone();
            }
        }
        SourceMode::Batch {
            probe_notice: batch_probe_notice,
            cursor_probe_notice,
            ..
        } => {
            *batch_probe_notice = probe_notice.clone();
            *cursor_probe_notice = None;
        }
        SourceMode::Empty => {}
    }

    app.convert.set_source_mode(mode);
    app.convert.source.cue_artifact_audio.clear();
    app.convert.apply_source_defaults();
    let probe_baseline = ConvertProbeBaseline::capture(&app.convert);
    app.current_screen = AppScreen::Convert;
    app.recent.record_use_with_db(&path, &app.db);

    if probe_notice.is_some() {
        if let Some(tx) = app.tui_tx.clone() {
            spawn_convert_source_probe(generation, path.clone(), probe_baseline, tx);
        }
        app.set_status(format!(
            "Probing: {}",
            path.file_name().unwrap_or_default().to_string_lossy()
        ));
    } else {
        app.set_status(format!(
            "Loaded: {}",
            path.file_name().unwrap_or_default().to_string_lossy()
        ));
    }
}

fn load_browse_selection(
    app: &mut AppState,
    path: std::path::PathBuf,
    target: super::browse::BrowseReturnTarget,
) {
    use super::browse::BrowseReturnTarget;

    match target {
        BrowseReturnTarget::ConvertSource | BrowseReturnTarget::None => {
            install_convert_source_with_async_probe(app, path);
            // Clear the return target so subsequent browse visits don't
            // auto-load into the source pane.
            app.browse.return_target = BrowseReturnTarget::None;
        }
        BrowseReturnTarget::ConvertQueue => {
            // Add all multi-selected files (or just this one) to the queue.
            // Repair stale raw marks at this selection boundary so queue-return
            // flows preserve the same directory-scoped invariant as :queue.
            let dropped_stale_count = app
                .browse
                .prune_stale_multi_selection_for_current_directory();
            let mut paths_to_add = app.browse.multi_selected_in_current_directory();
            if paths_to_add.is_empty() && app.browse.multi_selected.is_empty() {
                paths_to_add.push(path);
            }
            if super::command::browse_selection_contains_regular_audio_folder_for_convert(
                app,
                &paths_to_add,
            ) {
                if let Some(tx) = app.tui_tx.clone() {
                    super::command::start_browse_convert_folder_expansion(
                        app,
                        &tx,
                        super::command::BrowseConvertExpansionTarget::ConvertQueueItems,
                        paths_to_add,
                        dropped_stale_count,
                    );
                } else {
                    app.set_status("Cannot expand folder: TUI worker channel is unavailable");
                }
                return;
            }
            let mut count = 0;
            let mut password_reference_warning: Option<String> = None;
            let options = conversion_options_from_current_convert_output(app);
            for p in paths_to_add {
                // Resolve archive password:
                // session override → configured reference → keychain MRU → None.
                let archive_pw = if crate::is_encrypted_archive_ext(&p) {
                    match super::app::archive_password_for_path(app, &p) {
                        Ok(password) => password,
                        Err(error) => {
                            password_reference_warning.get_or_insert_with(|| error.clone());
                            log::error!("{error}");
                            continue;
                        }
                    }
                } else {
                    None
                };
                let archive_reference = archive_pw
                    .as_deref()
                    .map(super::keychain::reference_for_password);
                match app.manager.add_file_ready_for_processing(
                    p.clone(),
                    options.clone(),
                    archive_pw.clone(),
                ) {
                    Ok(item_id) => {
                        count += 1;
                        if let (Some(password), Some(reference_result)) =
                            (archive_pw.as_deref(), archive_reference)
                        {
                            match reference_result {
                                Ok(reference) => {
                                    if let Err(error) = app.manager.attach_archive_password_reference(
                                        &item_id,
                                        password,
                                        reference,
                                    ) {
                                        password_reference_warning.get_or_insert_with(|| format!(
                                            "archive-password reference could not be attached for {}: {}",
                                            p.display(),
                                            error
                                        ));
                                    }
                                }
                                Err(error) => {
                                    password_reference_warning.get_or_insert_with(|| format!(
                                        "archive password is process-only because the OS secret store is unavailable: {}",
                                        error
                                    ));
                                }
                            }
                        }
                    }
                    Err(error) => log::warn!("queue add failed for {}: {}", p.display(), error),
                }
            }
            app.browse.clear_multi_selection();
            let mut status = super::command::status_with_stale_selection_notice(
                dropped_stale_count,
                format!("Queued {} files", count),
            );
            if let Some(warning) = password_reference_warning {
                status.push_str("; ");
                status.push_str(&warning);
            }
            app.set_status(status);
            app.current_screen = AppScreen::Queue;
            app.browse.return_target = BrowseReturnTarget::None;
        }
    }
}

// ── Queue screen keybindings ─────────────────────────────────────────

fn handle_queue_key(app: &mut AppState, key: KeyEvent, tx: &mpsc::Sender<AppMessage>) {
    match (key.code, key.modifiers) {
        // Navigation
        (KeyCode::Up | KeyCode::Char('k'), KeyModifiers::NONE) => {
            if app.selected_index > 0 {
                app.selected_index -= 1;
                app.ensure_visible();
            }
        }
        (KeyCode::Down | KeyCode::Char('j'), KeyModifiers::NONE) => {
            if app.selected_index + 1 < app.items_snapshot.len() {
                app.selected_index += 1;
                app.ensure_visible();
            }
        }
        (KeyCode::Home, _) | (KeyCode::Char('g'), KeyModifiers::NONE) => {
            app.selected_index = 0;
            app.scroll_offset = 0;
        }
        (KeyCode::End, _) | (KeyCode::Char('G'), KeyModifiers::SHIFT) => {
            if !app.items_snapshot.is_empty() {
                app.selected_index = app.items_snapshot.len() - 1;
                app.ensure_visible();
            }
        }
        (KeyCode::PageUp, _) => {
            let jump = app.visible_height.max(1);
            app.selected_index = app.selected_index.saturating_sub(jump);
            app.ensure_visible();
        }
        (KeyCode::PageDown, _) => {
            let jump = app.visible_height.max(1);
            app.selected_index =
                (app.selected_index + jump).min(app.items_snapshot.len().saturating_sub(1));
            app.ensure_visible();
        }

        // Selection
        (KeyCode::Char(' '), KeyModifiers::NONE) => {
            app.toggle_current_selection();
            if app.selected_index + 1 < app.items_snapshot.len() {
                app.selected_index += 1;
                app.ensure_visible();
            }
        }
        (KeyCode::Char('a'), KeyModifiers::ALT) => {
            app.manager.select_all();
            app.set_status("Selected all items");
        }

        // Toggle per-track sub-line collapse
        (KeyCode::Tab, KeyModifiers::NONE) => {
            if let Some(item) = app.items_snapshot.get(app.selected_index) {
                if !item.active_tracks.is_empty() {
                    app.manager.toggle_track_collapse(&item.id);
                }
            }
        }

        // Item info
        (KeyCode::Enter, KeyModifiers::NONE) => {
            if let Some(item) = app.items_snapshot.get(app.selected_index) {
                match &item.status {
                    ConversionStatus::Failed { error, .. } => {
                        app.active_overlay = ActiveOverlay::ErrorDetail {
                            item_id: item.id.clone(),
                            error: error.clone(),
                        };
                    }
                    _ => {
                        app.active_overlay = ActiveOverlay::ItemInfo { item: item.clone() };
                    }
                }
            }
        }

        // Add files
        (KeyCode::Char('a'), KeyModifiers::NONE) | (KeyCode::Char('f'), KeyModifiers::NONE) => {
            app.active_overlay = ActiveOverlay::FileInput {
                input: super::text_input::TextInputState::empty(),
            };
        }

        // Configure (open wizard)
        (KeyCode::Char('c'), KeyModifiers::NONE) => {
            let has_selected = app.items_snapshot.iter().any(|i| i.selected);
            app.wizard_target = if has_selected {
                WizardTarget::ConfigureSelected
            } else {
                WizardTarget::ConfigureAll
            };
            app.wizard = Some(tonepoet_wizard::SimpleWizard::new());
            app.current_screen = AppScreen::Wizard;
        }

        // Start conversion
        (KeyCode::Char('s'), KeyModifiers::NONE) => {
            if !app.processing_active {
                let tx_clone = tx.clone();
                start_conversion(app, tx_clone);
            } else {
                app.set_status("Conversion already running");
            }
        }

        // Pause/Resume
        (KeyCode::Char('p'), KeyModifiers::NONE) => {
            if app.processing_active {
                if app.manager.is_paused() {
                    app.manager.resume_conversions();
                    app.set_status("Resumed conversions");
                } else {
                    app.manager.pause_conversions();
                    app.set_status("Paused conversions");
                }
            }
        }

        // Stop
        (KeyCode::Char('x'), KeyModifiers::NONE) => {
            if app.processing_active {
                app.active_overlay = ActiveOverlay::Confirmation {
                    message: "Stop all active conversions?".to_string(),
                    action: ConfirmAction::StopAll,
                };
            }
        }

        // Delete/Remove selected
        (KeyCode::Delete, _) | (KeyCode::Char('d'), KeyModifiers::NONE) => {
            let selected_count = app.items_snapshot.iter().filter(|i| i.selected).count();
            if selected_count > 0 {
                app.active_overlay = ActiveOverlay::Confirmation {
                    message: format!("Remove {} selected item(s)?", selected_count),
                    action: ConfirmAction::RemoveSelected,
                };
            }
        }

        // Clear completed
        (KeyCode::Char('l'), KeyModifiers::CONTROL) => {
            let finished_count = app
                .items_snapshot
                .iter()
                .filter(|i| {
                    matches!(
                        i.status,
                        ConversionStatus::Completed { .. }
                            | ConversionStatus::CompletedWithActionErrors { .. }
                            | ConversionStatus::Partial { .. }
                            | ConversionStatus::Failed { .. }
                            | ConversionStatus::Cancelled
                    )
                })
                .count();
            if finished_count > 0 {
                app.manager.clear_finished();
                app.save_queue();
                app.set_status(format!("Cleared {} finished items", finished_count));
            }
        }

        // Retry failed
        (KeyCode::Char('r'), KeyModifiers::CONTROL) => {
            retry_failed(app);
        }

        // Tab between file list and action bar
        (KeyCode::Tab, _) => {
            app.queue_focus = match app.queue_focus {
                QueueFocus::FileList => QueueFocus::ActionBar,
                QueueFocus::ActionBar => QueueFocus::FileList,
            };
        }

        _ => {}
    }
}

// ── Wizard keybindings ───────────────────────────────────────────────

fn handle_wizard_key(app: &mut AppState, key: KeyEvent) {
    if let Some(wizard) = &mut app.wizard {
        wizard.handle_key(key);

        if wizard.should_start_conversion {
            let (format, options) = crate::convert::extract_wizard_settings(wizard);
            app.wizard = None;
            app.wizard_mouse_areas = None;
            app.current_screen = AppScreen::Queue;

            app.manager.invalidate_deferred_stop_requests();
            let queue = app.manager.queue.clone();
            let has_selected = if let Ok(q) = queue.try_read() {
                q.all_items().iter().any(|i| i.selected)
            } else {
                false
            };

            if let Ok(mut q) = queue.try_write() {
                for item in q.all_items_mut() {
                    if has_selected && !item.selected {
                        continue;
                    }
                    match item.status {
                        ConversionStatus::NotConfigured
                        | ConversionStatus::Queued
                        | ConversionStatus::Paused => {
                            item.output_format = options.output_format;
                            item.options = options.clone();
                            item.status = ConversionStatus::Queued;
                        }
                        _ => {}
                    }
                }
            }
            app.set_status(format!("Configured items for {} conversion", format.name()));
            return;
        }

        if wizard.should_exit {
            app.wizard = None;
            app.wizard_mouse_areas = None;
            app.current_screen = AppScreen::Convert;
        }
    }
}

// ── Overlay keybindings ──────────────────────────────────────────────

/// Commit a GNUDB review's in-flight inline edit (if any) to the row the
/// edit was OPENED on. Every caller that moves the cursor or seeds a new
/// edit must commit to the PRE-move row first — routing the buffer through
/// whatever the cursor points at when Enter fires writes the text to the
/// wrong track (the wrong-row corruption class).
fn commit_gnudb_review_edit_to_row(state: &mut super::app::GnudbReviewState, row: usize) {
    use super::app::GnudbRowKind;
    let Some(input) = state.edit_input.take() else {
        return;
    };
    let new_val = input.text;
    let page = &mut state.pages[state.active_page];
    let Some(kind) = page.rows.get(row).cloned() else {
        return;
    };
    match kind {
        GnudbRowKind::AlbumField(field) => match field {
            "Album" => page.album = new_val,
            "Year" => page.year = new_val,
            "Genre" => page.genre = new_val,
            _ => {}
        },
        GnudbRowKind::TrackField { track_idx, field } => {
            let track = &mut page.tracks[track_idx];
            match field {
                "Title" => track.title = new_val,
                "Artist" => track.artist = new_val,
                _ => {}
            }
        }
        _ => {}
    }
}

fn handle_overlay_key(app: &mut AppState, key: KeyEvent, tx: &mpsc::Sender<AppMessage>) {
    let overlay = app.active_overlay.clone();
    match overlay {
        ActiveOverlay::DiscBrowser(_) => {
            super::disc_browser_actions::handle_disc_browser_key(app, key);
        }
        ActiveOverlay::FilePicker(mut session) => {
            let session_id = session.session_id;
            let purpose = session.purpose.clone();
            let action = session.picker.handle_key(key);
            if let Err(err) = send_file_picker_completion(tx, session_id, purpose, action) {
                app.set_status(format!("file picker: failed to queue completion: {err}"));
            }
            app.active_overlay = ActiveOverlay::FilePicker(session);
        }
        ActiveOverlay::FileTaskProgress(mut session) => {
            let action = session.progress.handle_key(key);
            handle_file_task_user_action(app, &mut session, action);
            if !matches!(app.active_overlay, ActiveOverlay::None) {
                app.active_overlay = ActiveOverlay::FileTaskProgress(session);
            }
        }
        ActiveOverlay::ThemeBuilder(mut state) => {
            let action = super::theme_builder::handle_theme_builder_key(&mut *state, key);
            complete_theme_builder_action(app, state, action);
        }
        ActiveOverlay::MetadataAutoNumber(mut state) => {
            handle_metadata_autonumber_key(app, &mut state, key);
        }
        ActiveOverlay::ConversionActionsWizard(state) => {
            let preview_rect = app.button_map.find_button_rect(&TuiButton::ActionsConfigPreview);
            let result = super::conversion_actions_ui::handle_wizard_key_with_preview_rect(*state, key, preview_rect);
            apply_conversion_actions_wizard_result(app, result);
        }
        ActiveOverlay::ActionsRun(mut state) => {
            use super::conversion_actions_ui::ActionsRunStatus;
            match key.code {
                KeyCode::Esc if state.status == ActionsRunStatus::Preparing => {
                    super::conversion_actions_ui::cancel_actions_run(&mut state);
                    app.active_overlay = ActiveOverlay::None;
                    app.set_status("Action preview preparation cancelled; nothing was executed");
                }
                KeyCode::Enter
                    if matches!(
                        state.status,
                        ActionsRunStatus::Preview | ActionsRunStatus::RecoveryPreview
                    ) =>
                {
                    super::conversion_actions_ui::start_actions_run(&mut state, tx);
                    app.active_overlay = ActiveOverlay::ActionsRun(state);
                }
                KeyCode::Esc
                    if matches!(state.status, ActionsRunStatus::Running | ActionsRunStatus::Cancelling) =>
                {
                    super::conversion_actions_ui::cancel_actions_run(&mut state);
                    app.active_overlay = ActiveOverlay::ActionsRun(state);
                }
                KeyCode::Enter | KeyCode::Esc
                    if matches!(
                        state.status,
                        ActionsRunStatus::Complete | ActionsRunStatus::Failed
                    ) =>
                {
                    app.active_overlay = ActiveOverlay::None;
                }
                KeyCode::Enter | KeyCode::Esc if state.status == ActionsRunStatus::Stale => {
                    match super::conversion_actions_ui::discard_actions_run_preview(&state) {
                        Ok(()) => app.set_status(
                            "Stale action preview retired; refresh before executing",
                        ),
                        Err(error) => app.set_status(format!(
                            "Could not retire stale action preview safely: {error}"
                        )),
                    }
                    app.active_overlay = ActiveOverlay::None;
                }
                KeyCode::Esc
                    if matches!(
                        state.status,
                        ActionsRunStatus::Preview | ActionsRunStatus::RecoveryPreview
                    ) =>
                {
                    match super::conversion_actions_ui::discard_actions_run_preview(&state) {
                        Ok(()) => app.set_status(if state.status == ActionsRunStatus::RecoveryPreview {
                            "Recovery remains pending; no operation was resumed"
                        } else {
                            "Prepared action preview discarded; nothing was executed"
                        }),
                        Err(error) => app.set_status(format!(
                            "Could not retire prepared action preview safely: {error}"
                        )),
                    }
                    app.active_overlay = ActiveOverlay::None;
                }
                _ => {
                    app.active_overlay = ActiveOverlay::ActionsRun(state);
                }
            }
        }
        ActiveOverlay::Confirmation { action, .. } => {
            match key.code {
                KeyCode::Enter | KeyCode::Char('y') | KeyCode::Char('Y') => {
                    app.active_overlay = ActiveOverlay::None;
                    execute_confirm_action(app, &action, tx);
                }
                KeyCode::Char('n') | KeyCode::Char('N')
                    if matches!(action, ConfirmAction::ArchiveStartupRecovery { .. }) =>
                {
                    let _ = open_archive_staging_discard_confirmation(app, &action);
                }
                KeyCode::Char('d') | KeyCode::Char('D')
                    if matches!(action, ConfirmAction::ArchiveStartupRecovery { .. }) =>
                {
                    let _ = open_archive_staging_discard_confirmation(app, &action);
                }
                KeyCode::Char('d') | KeyCode::Char('D')
                    if matches!(
                        action,
                        ConfirmAction::ArchiveExternalConflict { .. }
                            | ConfirmAction::ArchiveRepackageFailure { .. }
                    ) =>
                {
                    execute_archive_staging_discard_action(app, &action);
                }
                KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
                    cancel_confirm_action(app, Some(&action));
                }
                _ => {}
            }
        }
        ActiveOverlay::ErrorDetail { .. } | ActiveOverlay::ItemInfo { .. } => {
            if matches!(key.code, KeyCode::Esc | KeyCode::Enter) {
                app.active_overlay = ActiveOverlay::None;
            }
        }
        ActiveOverlay::FileInput { mut input } => {
            match key.code {
                KeyCode::Enter => {
                    let path = std::path::PathBuf::from(input.text.trim());
                    app.active_overlay = ActiveOverlay::None;
                    if !input.text.trim().is_empty() {
                        handle_file_input(app, &path);
                    }
                    return;
                }
                KeyCode::Esc => {
                    app.active_overlay = ActiveOverlay::None;
                    return;
                }
                _ => {
                    super::text_input::handle_text_input_key(&mut input, &key);
                }
            }
            app.active_overlay = ActiveOverlay::FileInput { input };
        }
        ActiveOverlay::CommandInput {
            mut input,
            mut completion,
        } => {
            match key.code {
                KeyCode::Enter => {
                    app.active_overlay = ActiveOverlay::None;
                    if !input.text.trim().is_empty() {
                        let cmd = super::command::parse_command(&input.text);
                        super::command::execute_command(app, cmd, tx);
                    }
                    // If a parked metadata editor wasn't consumed by the
                    // command, restore it now. Only `take()` when we
                    // intend to restore — otherwise a colon command
                    // that parks editor + opens a new overlay (e.g.
                    // :mb-back's Confirmation flow) would have its
                    // parked state drained-and-dropped here.
                    if matches!(app.active_overlay, ActiveOverlay::None) {
                        if let Some(parked) = app.pending_metadata_editor.take() {
                            app.active_overlay = ActiveOverlay::MetadataEditor(parked);
                        }
                    }
                    // Same for parked CUE preview.
                    if matches!(app.active_overlay, ActiveOverlay::None) {
                        if let Some(parked) = app.pending_cue_preview.take() {
                            app.active_overlay = ActiveOverlay::CuePreview(parked);
                        }
                    }
                    return;
                }
                KeyCode::Esc => {
                    app.active_overlay = ActiveOverlay::None;
                    // Restore parked metadata editor on cancel.
                    if let Some(parked) = app.pending_metadata_editor.take() {
                        app.active_overlay = ActiveOverlay::MetadataEditor(parked);
                    }
                    if let Some(parked) = app.pending_cue_preview.take() {
                        app.active_overlay = ActiveOverlay::CuePreview(parked);
                    }
                    return;
                }
                KeyCode::Tab => {
                    handle_command_tab(&mut input, &mut completion, 1);
                }
                KeyCode::BackTab => {
                    handle_command_tab(&mut input, &mut completion, -1);
                }
                _ => {
                    // Any other key clears completion state so the next
                    // Tab re-parses against the updated input.
                    completion = None;
                    super::text_input::handle_text_input_key(&mut input, &key);
                }
            }
            app.active_overlay = ActiveOverlay::CommandInput { input, completion };
        }
        ActiveOverlay::TextEdit {
            mut input,
            target,
            label,
        } => {
            let restore_parked_metadata_editor =
                matches!(&target, TextEditTarget::ArchivePassword(_));
            match key.code {
                KeyCode::Enter => {
                    let text = input.text.clone();
                    apply_text_edit(app, target, &text, tx);
                    // apply_text_edit may set its own overlay (e.g. BulkRenameLine
                    // restores BulkRename). Only clear if it did not.
                    if matches!(app.active_overlay, ActiveOverlay::TextEdit { .. }) {
                        app.active_overlay = ActiveOverlay::None;
                    }
                    if restore_parked_metadata_editor
                        && matches!(app.active_overlay, ActiveOverlay::None)
                    {
                        if let Some(editor) = app.pending_metadata_editor.take() {
                            app.active_overlay = ActiveOverlay::MetadataEditor(editor);
                        }
                    }
                }
                KeyCode::Esc => {
                    // If a BulkRename sub-edit was in progress, restore the overlay.
                    if matches!(
                        target,
                        TextEditTarget::BulkRenameLine(_) | TextEditTarget::SaveRenameTemplate(_)
                    ) {
                        if let Some(rename_state) = app.pending_bulk_rename.take() {
                            app.active_overlay = ActiveOverlay::BulkRename(rename_state);
                            return;
                        }
                    }
                    app.active_overlay = ActiveOverlay::None;
                    if restore_parked_metadata_editor {
                        if let Some(editor) = app.pending_metadata_editor.take() {
                            app.active_overlay = ActiveOverlay::MetadataEditor(editor);
                        }
                    }
                }
                _ => {
                    super::text_input::handle_text_input_key(&mut input, &key);
                    app.active_overlay = ActiveOverlay::TextEdit {
                        input,
                        target,
                        label,
                    };
                }
            }
        }
        ActiveOverlay::FormatSettings { mut kind, mut focus, help_scroll } => {
            if let Some(mut scroll) = help_scroll {
                // Help mode: scroll keys, Esc/Enter/? close help.
                let max_scroll = {
                    let total = super::draw_overlays::format_settings_help_line_count(&kind);
                    let (tw, th) = crossterm::terminal::size().unwrap_or((80, 30));
                    let popup = super::draw_overlays::format_settings_help_popup_rect(tw, th);
                    let visible = popup.height.saturating_sub(3) as usize; // borders(2) + footer(1)
                    total.saturating_sub(visible)
                };
                let page = 10usize;
                match key.code {
                    KeyCode::Esc | KeyCode::Enter | KeyCode::Char('?') => {
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: None };
                    }
                    KeyCode::Up | KeyCode::Char('k') => {
                        scroll = scroll.saturating_sub(1);
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: Some(scroll) };
                    }
                    KeyCode::Down | KeyCode::Char('j') => {
                        scroll = (scroll + 1).min(max_scroll);
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: Some(scroll) };
                    }
                    KeyCode::PageUp => {
                        scroll = scroll.saturating_sub(page);
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: Some(scroll) };
                    }
                    KeyCode::PageDown => {
                        scroll = (scroll + page).min(max_scroll);
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: Some(scroll) };
                    }
                    KeyCode::Home | KeyCode::Char('g') => {
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: Some(0) };
                    }
                    KeyCode::End | KeyCode::Char('G') => {
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: Some(max_scroll) };
                    }
                    _ => {} // ignore other keys in help mode
                }
            } else {
                // Controls mode.
                match key.code {
                    KeyCode::Enter => {
                        commit_format_settings(app, &kind);
                        app.active_overlay = ActiveOverlay::None;
                    }
                    KeyCode::Esc => {
                        app.active_overlay = ActiveOverlay::None;
                    }
                    KeyCode::Up => {
                        focus = format_settings_focus_prev(&kind, focus);
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: None };
                    }
                    KeyCode::Down | KeyCode::Tab => {
                        focus = format_settings_focus_next(&kind, focus);
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: None };
                    }
                    KeyCode::Char('?') => {
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: Some(0) };
                    }
                    _ => {
                        handle_format_settings_field_key(&mut kind, focus, &key);
                        app.active_overlay = ActiveOverlay::FormatSettings { kind, focus, help_scroll: None };
                    }
                }
            }
        }
        ActiveOverlay::BatchList { scroll } => {
            handle_batch_list_key(app, key, scroll, tx);
        }
        ActiveOverlay::ContextMenu { levels, origin } => {
            handle_context_menu_key(app, key, levels, origin, tx);
        }
        ActiveOverlay::BulkRename(state) => {
            handle_bulk_rename_key(app, key, *state, tx);
        }
        ActiveOverlay::Analysis { mut scroll } => {
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    app.active_overlay = ActiveOverlay::None;
                }
                // Command mode: allow :write-dr, :write-rg etc.
                KeyCode::Char(':') => {
                    app.active_overlay = ActiveOverlay::CommandInput {
                        input: super::text_input::TextInputState::empty(),
                        completion: None,
                    };
                }
                KeyCode::Up => {
                    scroll = scroll.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::Analysis { scroll };
                }
                KeyCode::Down => {
                    scroll += 1;
                    app.active_overlay = ActiveOverlay::Analysis { scroll };
                }
                _ => {}
            }
        }
        ActiveOverlay::CueImportReview {
            mut scroll,
            ref changes,
        } => {
            let changes = changes.clone(); // clone for use after overlay replace
            match key.code {
                KeyCode::Enter => {
                    // Accept: apply changes to parked metadata editor.
                    if let Some(mut parked) = app.pending_metadata_editor.take() {
                        super::command::apply_cue_changes(&mut parked, &changes);
                        app.active_overlay = ActiveOverlay::MetadataEditor(parked);
                        app.set_status(format!(
                            "Imported {} change{} from CUE",
                            changes.len(),
                            if changes.len() == 1 { "" } else { "s" },
                        ));
                    } else {
                        app.active_overlay = ActiveOverlay::None;
                    }
                }
                KeyCode::Esc | KeyCode::Char('q') => {
                    // Cancel: restore editor without changes.
                    if let Some(parked) = app.pending_metadata_editor.take() {
                        app.active_overlay = ActiveOverlay::MetadataEditor(parked);
                    } else {
                        app.active_overlay = ActiveOverlay::None;
                    }
                    app.set_status("CUE import cancelled");
                }
                KeyCode::Up => {
                    scroll = scroll.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::CueImportReview { changes, scroll };
                }
                KeyCode::Down => {
                    scroll += 1;
                    app.active_overlay = ActiveOverlay::CueImportReview { changes, scroll };
                }
                _ => {}
            }
        }
        ActiveOverlay::GnudbSelect {
            operation_id,
            ref matches,
            mut selected,
            scroll,
            ref paths,
        } => {
            let matches = matches.clone();
            let paths = paths.clone();
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    app.active_overlay = ActiveOverlay::None;
                    super::event_loop::cancel_gnudb_operation(app, operation_id);
                }
                KeyCode::Up => {
                    selected = selected.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::GnudbSelect {
                        operation_id,
                        matches,
                        selected,
                        scroll,
                        paths,
                    };
                }
                KeyCode::Down => {
                    if selected + 1 < matches.len() {
                        selected += 1;
                    }
                    app.active_overlay = ActiveOverlay::GnudbSelect {
                        operation_id,
                        matches,
                        selected,
                        scroll,
                        paths,
                    };
                }
                KeyCode::Enter => {
                    if let Some(m) = matches.get(selected).cloned() {
                        let Some(read_operation_id) =
                            super::event_loop::advance_gnudb_operation(app, operation_id)
                        else {
                            app.active_overlay = ActiveOverlay::GnudbSelect {
                                operation_id,
                                matches,
                                selected,
                                scroll,
                                paths,
                            };
                            return;
                        };
                        let category = m.category.clone();
                        let disc_id = m.disc_id.clone();
                        app.set_status(format!("Reading {}...", m.title));
                        app.active_overlay = ActiveOverlay::None;
                        let tx = tx.clone();
                        let origin = matches.clone();
                        super::event_loop::spawn_gnudb_worker(
                            tx,
                            read_operation_id,
                            async move {
                                let result =
                                    super::gnudb::read_gnudb(&category, &disc_id).await;
                                AppMessage::GnudbReadComplete {
                                    operation_id: read_operation_id,
                                    result,
                                    paths,
                                    origin_matches: Some(origin),
                                }
                            },
                        );
                    }
                }
                _ => {}
            }
        }
        ActiveOverlay::GnudbReview(mut state) => {
            use super::app::GnudbRowKind;

            let page_rows = &state.pages[state.active_page].rows;

            if state.edit_input.is_some() {
                // ── Inline edit mode ──
                match key.code {
                    KeyCode::Esc => {
                        state.edit_input = None;
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    KeyCode::Enter => {
                        let row = state.cursor;
                        commit_gnudb_review_edit_to_row(&mut state, row);
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    _ => {
                        if let Some(ref mut input) = state.edit_input {
                            super::text_input::handle_text_input_key(input, &key);
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                }
            } else {
                // ── Navigation mode ──
                match (key.code, key.modifiers) {
                    (KeyCode::Esc, _) | (KeyCode::Char('q'), _) => {
                        app.active_overlay = ActiveOverlay::None;
                        let restored = super::event_loop::restore_gnudb_review_editor_if_owned(
                            app,
                            state.editor_session,
                        );
                        if restored {
                            app.set_status("GNUDB review cancelled; metadata editor restored".to_string());
                        } else if state.editor_session.is_some()
                            && app.pending_metadata_editor.is_some()
                        {
                            app.set_status(
                                "GNUDB review cancelled; stale parked editor was not restored"
                                    .to_string(),
                            );
                        } else {
                            app.set_status("GNUDB review cancelled".to_string());
                        }
                    }
                    // Back to match list (if came from multi-match selection).
                    (KeyCode::Char('b'), _) => {
                        if let Some(matches) = state.origin_matches.take() {
                            match super::event_loop::begin_gnudb_operation(app) {
                                Ok(operation_id) => {
                                    app.active_overlay = ActiveOverlay::GnudbSelect {
                                        operation_id,
                                        matches,
                                        selected: 0,
                                        scroll: 0,
                                        paths: state.paths,
                                    };
                                    app.set_status("Back to match list");
                                }
                                Err(error) => {
                                    state.origin_matches = Some(matches);
                                    app.active_overlay = ActiveOverlay::GnudbReview(state);
                                    app.set_status(error);
                                }
                            }
                        } else {
                            app.active_overlay = ActiveOverlay::GnudbReview(state);
                        }
                    }
                    // Left / Right: switch disc page (only in navigation mode,
                    // not while editing — edit mode returns early above).
                    (KeyCode::Left, _) => {
                        if state.pages.len() > 1 && state.active_page > 0 {
                            state.active_page -= 1;
                            state.cursor = 0;
                            state.scroll = 0;
                            state.edit_input = None;
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    (KeyCode::Right, _) => {
                        if state.active_page + 1 < state.pages.len() {
                            state.active_page += 1;
                            state.cursor = 0;
                            state.scroll = 0;
                            state.edit_input = None;
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    (KeyCode::Up, _) => {
                        let mut nc = state.cursor;
                        loop {
                            if nc == 0 {
                                break;
                            }
                            nc -= 1;
                            if !matches!(page_rows.get(nc), Some(GnudbRowKind::TrackHeader { .. }))
                            {
                                break;
                            }
                        }
                        state.cursor = nc;
                        if state.cursor < state.scroll {
                            state.scroll = state.cursor;
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    (KeyCode::Down, _) => {
                        let mut nc = state.cursor;
                        loop {
                            if nc + 1 >= page_rows.len() {
                                break;
                            }
                            nc += 1;
                            if !matches!(page_rows.get(nc), Some(GnudbRowKind::TrackHeader { .. }))
                            {
                                break;
                            }
                        }
                        state.cursor = nc;
                        let visible_h = crossterm::terminal::size()
                            .map(|(_, h)| (h as usize * 85 / 100).max(14).saturating_sub(4))
                            .unwrap_or(20);
                        if state.cursor >= state.scroll + visible_h {
                            state.scroll = state.cursor.saturating_sub(visible_h) + 1;
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    (KeyCode::Enter, _) => {
                        let page = &state.pages[state.active_page];
                        let value = match &page.rows[state.cursor] {
                            GnudbRowKind::AlbumField(field) => match *field {
                                "Album" => Some(page.album.clone()),
                                "Year" => Some(page.year.clone()),
                                "Genre" => Some(page.genre.clone()),
                                _ => None,
                            },
                            GnudbRowKind::TrackField { track_idx, field } => {
                                let track = &page.tracks[*track_idx];
                                match *field {
                                    "Title" => Some(track.title.clone()),
                                    "Artist" => Some(track.artist.clone()),
                                    _ => None,
                                }
                            }
                            _ => None,
                        };
                        if let Some(val) = value {
                            state.edit_input = Some(super::text_input::TextInputState::new(val));
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    (KeyCode::PageUp, _) => {
                        let jump = crossterm::terminal::size()
                            .map(|(_, h)| (h as usize * 85 / 100).max(14).saturating_sub(4))
                            .unwrap_or(20);
                        for _ in 0..jump {
                            let mut nc = state.cursor;
                            if nc == 0 {
                                break;
                            }
                            nc -= 1;
                            while nc > 0
                                && matches!(
                                    page_rows.get(nc),
                                    Some(GnudbRowKind::TrackHeader { .. })
                                )
                            {
                                nc -= 1;
                            }
                            state.cursor = nc;
                        }
                        if state.cursor < state.scroll {
                            state.scroll = state.cursor;
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    (KeyCode::PageDown, _) => {
                        let jump = crossterm::terminal::size()
                            .map(|(_, h)| (h as usize * 85 / 100).max(14).saturating_sub(4))
                            .unwrap_or(20);
                        for _ in 0..jump {
                            let mut nc = state.cursor;
                            if nc + 1 >= page_rows.len() {
                                break;
                            }
                            nc += 1;
                            while nc + 1 < page_rows.len()
                                && matches!(
                                    page_rows.get(nc),
                                    Some(GnudbRowKind::TrackHeader { .. })
                                )
                            {
                                nc += 1;
                            }
                            state.cursor = nc;
                        }
                        let visible_h = crossterm::terminal::size()
                            .map(|(_, h)| (h as usize * 85 / 100).max(14).saturating_sub(4))
                            .unwrap_or(20);
                        if state.cursor >= state.scroll + visible_h {
                            state.scroll = state.cursor.saturating_sub(visible_h) + 1;
                        }
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    (KeyCode::Char('a'), _) => {
                        // Accept ALL pages. A `:gnudb-back` review may consume
                        // only the exact editor session it parked. Ordinary
                        // Browse-originated reviews have no guard and open the
                        // selected files through the normal route.
                        if state.editor_session.is_some() {
                            let Some(parked) =
                                super::event_loop::take_gnudb_review_editor_if_owned(
                                    app,
                                    state.editor_session,
                                )
                            else {
                                app.active_overlay = ActiveOverlay::GnudbReview(state);
                                app.set_status(
                                    "GNUDB review no longer owns the parked metadata editor; run :gnudb-back again"
                                        .to_string(),
                                );
                                return;
                            };
                            app.active_overlay = ActiveOverlay::MetadataEditor(parked);
                        } else {
                            super::keybindings::open_metadata_editor_with_tx(app, tx);
                        }
                        if let ActiveOverlay::MetadataEditor(ref mut editor_state) =
                            app.active_overlay
                        {
                            let mutation_report =
                                super::gnudb::populate_editor_from_review(editor_state, &state);
                            // Cache the review state for `:gnudb-back`
                            // — user can return to the per-track edit
                            // surface preserving their edits, no
                            // gnudb requery.
                            editor_state.gnudb_back = Some(state.clone());
                            let first_page = &state.pages[0];
                            let artist = first_page
                                .tracks
                                .first()
                                .map(|t| t.artist.as_str())
                                .unwrap_or("?");
                            let mut status = format!(
                                "Tags loaded — {} / {} ({} disc{})",
                                artist,
                                first_page.album,
                                state.pages.len(),
                                if state.pages.len() == 1 { "" } else { "s" },
                            );
                            mutation_report.append_provider_summary("GNUDB", &mut status);
                            app.set_status(status);
                        }
                    }
                    (KeyCode::Char('c'), _) => {
                        // Apply capitalization to current page.
                        use crate::convert::renaming::{capitalize_section, capitalize_title};
                        let page = &mut state.pages[state.active_page];
                        page.album = capitalize_section(&page.album);
                        page.genre = capitalize_section(&page.genre);
                        for track in &mut page.tracks {
                            track.title = capitalize_title(&track.title);
                            track.artist = capitalize_section(&track.artist);
                        }
                        app.set_status("Capitalization applied to current disc");
                        app.active_overlay = ActiveOverlay::GnudbReview(state);
                    }
                    _ => {}
                }
            }
        }
        ActiveOverlay::Verify { mut scroll } => match key.code {
            KeyCode::Esc | KeyCode::Char('q') => {
                app.active_overlay = ActiveOverlay::None;
            }
            KeyCode::Up | KeyCode::Char('k') => {
                scroll = scroll.saturating_sub(1);
                app.active_overlay = ActiveOverlay::Verify { scroll };
            }
            KeyCode::Down | KeyCode::Char('j') => {
                scroll += 1;
                app.active_overlay = ActiveOverlay::Verify { scroll };
            }
            _ => {}
        },
        ActiveOverlay::CueSelect(mut state) => {
            let candidate_count = state.candidates.len();
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    app.active_overlay = ActiveOverlay::None;
                    app.set_status("CUE selection cancelled; no changes were applied");
                }
                KeyCode::Enter => accept_cue_selection(app, tx, *state),
                KeyCode::Up | KeyCode::Char('k') => {
                    state.selected = state.selected.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::CueSelect(state);
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    state.selected = state
                        .selected
                        .saturating_add(1)
                        .min(candidate_count.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::CueSelect(state);
                }
                KeyCode::PageUp => {
                    state.selected = state.selected.saturating_sub(10);
                    app.active_overlay = ActiveOverlay::CueSelect(state);
                }
                KeyCode::PageDown => {
                    state.selected = state
                        .selected
                        .saturating_add(10)
                        .min(candidate_count.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::CueSelect(state);
                }
                KeyCode::Home => {
                    state.selected = 0;
                    app.active_overlay = ActiveOverlay::CueSelect(state);
                }
                KeyCode::End => {
                    state.selected = candidate_count.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::CueSelect(state);
                }
                _ => app.active_overlay = ActiveOverlay::CueSelect(state),
            }
        }
        ActiveOverlay::MbSelect(mut state) => {
            // Acceptance transitions the picker to a non-interactive Verifying
            // phase before any worker is spawned. Esc remains the only active
            // control during verification and authoritatively invalidates the
            // operation identity carried by its eventual completion.
            let n = state.releases.len();
            match key.code {
                KeyCode::Esc => {
                    let operation_id = state.operation_id;
                    app.active_overlay = ActiveOverlay::None;
                    if super::event_loop::cancel_mb_select_operation(app, operation_id) {
                        app.set_status("MusicBrainz picker cancelled".to_string());
                    } else {
                        app.active_overlay = ActiveOverlay::MbSelect(state);
                    }
                }
                KeyCode::Enter => {
                    super::event_loop::accept_mb_select_release(app, tx, state);
                }
                KeyCode::Up if state.is_selecting() => {
                    state.selected = state.selected.saturating_sub(1);
                    prefetch_current_mb_row(tx, &state, &app.db);
                    app.active_overlay = ActiveOverlay::MbSelect(state);
                }
                KeyCode::Down if state.is_selecting() => {
                    state.selected = (state.selected + 1).min(n.saturating_sub(1));
                    prefetch_current_mb_row(tx, &state, &app.db);
                    app.active_overlay = ActiveOverlay::MbSelect(state);
                }
                KeyCode::PageUp if state.is_selecting() => {
                    state.selected = state.selected.saturating_sub(10);
                    prefetch_current_mb_row(tx, &state, &app.db);
                    app.active_overlay = ActiveOverlay::MbSelect(state);
                }
                KeyCode::PageDown if state.is_selecting() => {
                    state.selected = (state.selected + 10).min(n.saturating_sub(1));
                    prefetch_current_mb_row(tx, &state, &app.db);
                    app.active_overlay = ActiveOverlay::MbSelect(state);
                }
                _ => {
                    app.active_overlay = ActiveOverlay::MbSelect(state);
                }
            }
        }
        ActiveOverlay::CuePreview(mut state) => {
            // Two modes:
            // - Read-only (default): `:` parks the overlay + opens command
            //   input; arrows / PageUp / PageDown scroll; Esc cancels.
            // - Editing (after `:e <N>`): keys flow through TextInputState;
            //   Enter commits the line splice; Esc cancels the edit
            //   without splicing.
            if state.is_editing() {
                match key.code {
                    KeyCode::Enter => {
                        state.commit_edit();
                        app.active_overlay = ActiveOverlay::CuePreview(state);
                    }
                    KeyCode::Esc => {
                        state.cancel_edit();
                        app.active_overlay = ActiveOverlay::CuePreview(state);
                    }
                    _ => {
                        if let Some(ref mut input) = state.edit {
                            super::text_input::handle_text_input_key(input, &key);
                        }
                        app.active_overlay = ActiveOverlay::CuePreview(state);
                    }
                }
                return;
            }

            let max_line = state.content.lines().count().saturating_sub(1);
            match key.code {
                KeyCode::Char(':') => {
                    if state.read_only {
                        // Block command-mode parking in read-only.
                        // Only Esc closes; nothing else applies to a
                        // view-only overlay.
                        app.active_overlay = ActiveOverlay::CuePreview(state);
                    } else {
                        app.pending_cue_preview = Some(state);
                        app.active_overlay = ActiveOverlay::CommandInput {
                            input: super::text_input::TextInputState::empty(),
                            completion: None,
                        };
                    }
                }
                KeyCode::Esc => {
                    close_cue_preview_restoring_parked(app);
                    app.set_status("CUE preview cancelled".to_string());
                }
                KeyCode::Up => {
                    state.scroll = state.scroll.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::CuePreview(state);
                }
                KeyCode::Down => {
                    state.scroll = state.scroll.saturating_add(1).min(max_line);
                    app.active_overlay = ActiveOverlay::CuePreview(state);
                }
                KeyCode::PageUp => {
                    state.scroll = state.scroll.saturating_sub(10);
                    app.active_overlay = ActiveOverlay::CuePreview(state);
                }
                KeyCode::PageDown => {
                    state.scroll = state.scroll.saturating_add(10).min(max_line);
                    app.active_overlay = ActiveOverlay::CuePreview(state);
                }
                _ => {
                    app.active_overlay = ActiveOverlay::CuePreview(state);
                }
            }
        }
        ActiveOverlay::BitCompare { mut scroll } => match key.code {
            KeyCode::Esc | KeyCode::Char('q') => {
                app.active_overlay = ActiveOverlay::None;
            }
            KeyCode::Up | KeyCode::Char('k') => {
                scroll = scroll.saturating_sub(1);
                app.active_overlay = ActiveOverlay::BitCompare { scroll };
            }
            KeyCode::Down | KeyCode::Char('j') => {
                scroll += 1;
                app.active_overlay = ActiveOverlay::BitCompare { scroll };
            }
            _ => {}
        },
        ActiveOverlay::Preemphasis { mut scroll } => match key.code {
            KeyCode::Esc | KeyCode::Char('q') => {
                app.active_overlay = ActiveOverlay::None;
            }
            KeyCode::Up | KeyCode::Char('k') => {
                scroll = scroll.saturating_sub(1);
                app.active_overlay = ActiveOverlay::Preemphasis { scroll };
            }
            KeyCode::Down | KeyCode::Char('j') => {
                scroll += 1;
                app.active_overlay = ActiveOverlay::Preemphasis { scroll };
            }
            _ => {}
        },
        ActiveOverlay::MetadataEditor(mut state) => {
            handle_metadata_editor_key(app, key, &mut state, tx);
            // If the handler didn't close or replace the overlay, put state back.
            if matches!(app.active_overlay, ActiveOverlay::MetadataEditor(_)) {
                app.active_overlay = ActiveOverlay::MetadataEditor(state);
            }
        }
        ActiveOverlay::Help { mut scroll, screen } => {
            // Compute content length for scroll clamping.
            let max_scroll = {
                let sections = super::help::help_content_for(screen);
                let total = super::help::line_count(&sections);
                // Estimate visible rows from terminal height (same math as renderer).
                let term_h = crossterm::terminal::size().map(|(_, h)| h).unwrap_or(30) as usize;
                let popup_h = (term_h * 85 / 100).max(15).min(term_h.saturating_sub(2));
                let visible = popup_h.saturating_sub(4); // borders(2) + footer(1) + margin(1)
                total.saturating_sub(visible)
            };
            match key.code {
                KeyCode::Esc | KeyCode::Char('?') | KeyCode::Char('q') => {
                    app.active_overlay = ActiveOverlay::None;
                }
                KeyCode::Up | KeyCode::Char('k') => {
                    scroll = scroll.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::Help { screen, scroll };
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    scroll = (scroll + 1).min(max_scroll);
                    app.active_overlay = ActiveOverlay::Help { screen, scroll };
                }
                KeyCode::Home | KeyCode::Char('g') => {
                    app.active_overlay = ActiveOverlay::Help { screen, scroll: 0 };
                }
                KeyCode::End | KeyCode::Char('G') => {
                    app.active_overlay = ActiveOverlay::Help {
                        screen,
                        scroll: max_scroll,
                    };
                }
                KeyCode::PageUp => {
                    scroll = scroll.saturating_sub(15);
                    app.active_overlay = ActiveOverlay::Help { screen, scroll };
                }
                KeyCode::PageDown => {
                    scroll = (scroll + 15).min(max_scroll);
                    app.active_overlay = ActiveOverlay::Help { screen, scroll };
                }
                _ => {}
            }
        }
        ActiveOverlay::CtdbVerify(mut state) => {
            let page = &state.pages[state.active_page];
            let disc_header = if state.pages.len() > 1 { 2 } else { 0 };
            let total_lines = disc_header + 2 + page.result.tracks.len() * 2;
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    app.active_overlay = ActiveOverlay::None;
                }
                KeyCode::Left => {
                    if state.pages.len() > 1 && state.active_page > 0 {
                        state.active_page -= 1;
                        state.scroll = 0;
                    }
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                KeyCode::Right => {
                    if state.active_page + 1 < state.pages.len() {
                        state.active_page += 1;
                        state.scroll = 0;
                    }
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                KeyCode::Up | KeyCode::Char('k') => {
                    state.scroll = state.scroll.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    state.scroll = (state.scroll + 1).min(total_lines.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                KeyCode::PageUp => {
                    state.scroll = state.scroll.saturating_sub(15);
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                KeyCode::PageDown => {
                    state.scroll = (state.scroll + 15).min(total_lines.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                KeyCode::Home | KeyCode::Char('g') => {
                    state.scroll = 0;
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                KeyCode::End | KeyCode::Char('G') => {
                    state.scroll = total_lines.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
                _ => {
                    app.active_overlay = ActiveOverlay::CtdbVerify(state);
                }
            }
        }
        ActiveOverlay::ArBatchReport { result, mut scroll } => {
            let total_lines = 3 + result.albums.len() * 2;
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    app.active_overlay = ActiveOverlay::None;
                }
                KeyCode::Up | KeyCode::Char('k') => {
                    scroll = scroll.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::ArBatchReport { result, scroll };
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    scroll = (scroll + 1).min(total_lines.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::ArBatchReport { result, scroll };
                }
                KeyCode::PageUp => {
                    scroll = scroll.saturating_sub(15);
                    app.active_overlay = ActiveOverlay::ArBatchReport { result, scroll };
                }
                KeyCode::PageDown => {
                    scroll = (scroll + 15).min(total_lines.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::ArBatchReport { result, scroll };
                }
                KeyCode::Home | KeyCode::Char('g') => {
                    scroll = 0;
                    app.active_overlay = ActiveOverlay::ArBatchReport { result, scroll };
                }
                KeyCode::End | KeyCode::Char('G') => {
                    scroll = total_lines.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::ArBatchReport { result, scroll };
                }
                _ => {
                    app.active_overlay = ActiveOverlay::ArBatchReport { result, scroll };
                }
            }
        }
        ActiveOverlay::AccurateRipVerify(mut state) => {
            let page = &state.pages[state.active_page];
            // Rendered lines: disc pills (2 if multi) + 3 (summary + ID + blank) + 2 per track.
            let disc_header = if state.pages.len() > 1 { 2 } else { 0 };
            let total_lines = disc_header + 3 + page.result.tracks.len() * 2;
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    app.active_overlay = ActiveOverlay::None;
                }
                KeyCode::Left => {
                    if state.pages.len() > 1 && state.active_page > 0 {
                        state.active_page -= 1;
                        state.scroll = 0;
                    }
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                KeyCode::Right => {
                    if state.active_page + 1 < state.pages.len() {
                        state.active_page += 1;
                        state.scroll = 0;
                    }
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                KeyCode::Up | KeyCode::Char('k') => {
                    state.scroll = state.scroll.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    state.scroll = (state.scroll + 1).min(total_lines.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                KeyCode::PageUp => {
                    state.scroll = state.scroll.saturating_sub(15);
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                KeyCode::PageDown => {
                    state.scroll = (state.scroll + 15).min(total_lines.saturating_sub(1));
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                KeyCode::Home | KeyCode::Char('g') => {
                    state.scroll = 0;
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                KeyCode::End | KeyCode::Char('G') => {
                    state.scroll = total_lines.saturating_sub(1);
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
                _ => {
                    app.active_overlay = ActiveOverlay::AccurateRipVerify(state);
                }
            }
        }
        ActiveOverlay::TemplateBuilder(mut state) => {
            match state.focus {
                TemplateBuilderFocus::TemplateInput => match key.code {
                    KeyCode::Esc => {
                        app.active_overlay = ActiveOverlay::None;
                    }
                    KeyCode::Tab => {
                        state.focus = TemplateBuilderFocus::SavedList;
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Enter => {
                        // Apply: write template to the target field
                        let text = state.template_input.text.clone();
                        match state.target {
                            TemplateTarget::Folder => {
                                app.convert.output_options.folder_template = text;
                            }
                            TemplateTarget::Filename => {
                                app.convert.output_options.filename_template = text;
                            }
                        }
                        app.preset.mark_modified();
                        app.active_overlay = ActiveOverlay::None;
                        app.set_status("Template applied");
                    }
                    _ => {
                        super::text_input::handle_text_input_key(&mut state.template_input, &key);
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                },
                TemplateBuilderFocus::SavedList => match key.code {
                    KeyCode::Esc => {
                        app.active_overlay = ActiveOverlay::None;
                    }
                    KeyCode::Tab => {
                        state.focus = TemplateBuilderFocus::TokenGrid;
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::BackTab => {
                        state.focus = TemplateBuilderFocus::TemplateInput;
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Up | KeyCode::Char('k') => {
                        if state.saved_selected > 0 {
                            state.saved_selected -= 1;
                        }
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Down | KeyCode::Char('j') => {
                        if state.saved_selected + 1 < state.saved_templates.len() {
                            state.saved_selected += 1;
                        }
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Enter => {
                        // Load selected template into the input line
                        if let Some(tmpl) = state.saved_templates.get(state.saved_selected).cloned()
                        {
                            state.template_input = super::text_input::TextInputState::new(tmpl);
                            state.template_input.cursor = state.template_input.text.len();
                            state.focus = TemplateBuilderFocus::TemplateInput;
                        }
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Char('x') | KeyCode::Delete => {
                        // Delete selected saved template
                        if let Some(tmpl) = state.saved_templates.get(state.saved_selected).cloned()
                        {
                            let _ = super::template_builder::delete_template(state.target, &tmpl);
                            state.saved_templates =
                                super::template_builder::list_templates(state.target);
                            if state.saved_selected >= state.saved_templates.len()
                                && state.saved_selected > 0
                            {
                                state.saved_selected -= 1;
                            }
                            app.set_status("Template deleted");
                        }
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    _ => {
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                },
                TemplateBuilderFocus::TokenGrid => match key.code {
                    KeyCode::Esc => {
                        app.active_overlay = ActiveOverlay::None;
                    }
                    KeyCode::Tab => {
                        state.focus = TemplateBuilderFocus::TemplateInput;
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::BackTab => {
                        state.focus = TemplateBuilderFocus::SavedList;
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Left => {
                        if state.grid_cursor > 0 {
                            state.grid_cursor -= 1;
                        }
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Right => {
                        let max = state.total_grid_items().saturating_sub(1);
                        if state.grid_cursor < max {
                            state.grid_cursor += 1;
                        }
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    KeyCode::Enter => {
                        state.insert_current_grid_item();
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                    _ => {
                        app.active_overlay = ActiveOverlay::TemplateBuilder(state);
                    }
                },
            }
        }
        ActiveOverlay::TemplatePicker {
            target,
            templates,
            mut selected,
            mut scroll,
            active_template,
            ..
        } => {
            let count = templates.len();
            match key.code {
                KeyCode::Esc => {
                    app.active_overlay = ActiveOverlay::None;
                }
                KeyCode::Up | KeyCode::Char('k') => {
                    if selected > 0 {
                        selected -= 1;
                        if selected < scroll {
                            scroll = selected;
                        }
                    }
                    let preview = if let Some(tmpl) = templates.get(selected) {
                        super::template_builder::render_template_preview(tmpl)
                    } else {
                        String::new()
                    };
                    app.active_overlay = ActiveOverlay::TemplatePicker {
                        target,
                        templates,
                        selected,
                        scroll,
                        preview,
                        active_template,
                    };
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    if count > 0 && selected + 1 < count {
                        selected += 1;
                        // Scroll follows selection: assume ~10 visible rows
                        let visible = 10_usize;
                        if selected >= scroll + visible {
                            scroll = selected.saturating_sub(visible - 1);
                        }
                    }
                    let preview = if let Some(tmpl) = templates.get(selected) {
                        super::template_builder::render_template_preview(tmpl)
                    } else {
                        String::new()
                    };
                    app.active_overlay = ActiveOverlay::TemplatePicker {
                        target,
                        templates,
                        selected,
                        scroll,
                        preview,
                        active_template,
                    };
                }
                KeyCode::Enter => {
                    if let Some(tmpl) = templates.get(selected).cloned() {
                        match target {
                            TemplateTarget::Folder => {
                                app.convert.output_options.folder_template = tmpl;
                            }
                            TemplateTarget::Filename => {
                                app.convert.output_options.filename_template = tmpl;
                            }
                        }
                        app.preset.mark_modified();
                        app.active_overlay = ActiveOverlay::None;
                        app.set_status("Template applied");
                    }
                }
                KeyCode::Delete => {
                    if let Some(tmpl) = templates.get(selected).cloned() {
                        let _ =
                            super::template_builder::delete_template(target, &tmpl);
                        let new_templates =
                            super::template_builder::list_templates(target);
                        if selected >= new_templates.len() && selected > 0 {
                            selected -= 1;
                        }
                        if scroll > 0 && scroll >= new_templates.len() {
                            scroll = new_templates.len().saturating_sub(1);
                        }
                        let preview = if let Some(tmpl) = new_templates.get(selected) {
                            super::template_builder::render_template_preview(tmpl)
                        } else {
                            String::new()
                        };
                        app.set_status("Template deleted");
                        app.active_overlay = ActiveOverlay::TemplatePicker {
                            target,
                            templates: new_templates,
                            selected,
                            scroll,
                            preview,
                            active_template,
                        };
                    }
                }
                _ => {
                    app.active_overlay = ActiveOverlay::TemplatePicker {
                        target,
                        templates,
                        selected,
                        scroll,
                        preview: String::new(),
                        active_template,
                    };
                }
            }
        }
        ActiveOverlay::None => {}
    }
}

fn cue_operation_selection_snapshot(mut paths: Vec<std::path::PathBuf>) -> Vec<std::path::PathBuf> {
    paths = paths
        .into_iter()
        .map(|path| std::fs::canonicalize(&path).unwrap_or(path))
        .collect();
    paths.sort_by(|left, right| {
        left.to_string_lossy()
            .to_ascii_lowercase()
            .cmp(&right.to_string_lossy().to_ascii_lowercase())
            .then_with(|| left.cmp(right))
    });
    paths.dedup();
    paths
}

fn accept_cue_selection(
    app: &mut AppState,
    tx: &mpsc::Sender<AppMessage>,
    state: CueSelectState,
) {
    let CueSelectState {
        parent,
        candidates,
        selected,
        operation,
        ..
    } = state;
    let Some(selected_cue) = candidates.get(selected).cloned() else {
        app.active_overlay = ActiveOverlay::None;
        app.set_status("CUE selection failed: no candidate is selected");
        return;
    };

    match operation {
        CueSelectOperation::Metadata {
            selection_snapshot,
            cue_policy,
            mut cue_selection_overrides,
        } => {
            let current = super::command::collect_selection_for_file_ops(app);
            if cue_operation_selection_snapshot(current)
                != cue_operation_selection_snapshot(selection_snapshot)
            {
                app.active_overlay = ActiveOverlay::None;
                app.set_status("CUE selection expired because the Browse selection changed");
                return;
            }
            cue_selection_overrides.insert(parent, selected_cue);
            app.active_overlay = ActiveOverlay::None;
            open_metadata_editor_impl(app, Some(tx), cue_policy, cue_selection_overrides);
        }
        CueSelectOperation::BrowseConvert { mut request } => {
            if !super::command::browse_convert_expansion_selection_still_current(app, &request) {
                app.active_overlay = ActiveOverlay::None;
                app.set_status("CUE selection expired because the Browse selection changed");
                return;
            }
            request
                .cue_selection_overrides
                .insert(parent, selected_cue);
            app.active_overlay = ActiveOverlay::None;
            super::command::start_browse_convert_folder_expansion_request(app, tx, request);
        }
    }
}

/// Bump the MbSelect picker's prefetch generation and spawn a detail
/// fetch for the currently-highlighted row — unless the cache already
/// has it, in which case nothing fires (no wasted MB token).
///
/// Called after every cursor move (keyboard Up/Down/PgUp/PgDn and
/// future mouse-row click). The spawn helper handles the 150 ms
/// debounce and the generation-mismatch bail-out; this caller just
/// supplies the new snapshot.
fn prefetch_current_mb_row(
    tx: &mpsc::Sender<AppMessage>,
    state: &crate::tui::app::MbSelectState,
    db: &crate::db::Database,
) {
    // Always bump generation on navigation so any in-flight prefetch
    // for a no-longer-current row sees the mismatch and exits. The
    // bump is cheap; the alternative (skip bump when destination is
    // already cached) has subtle interactions when rapidly traversing
    // a mix of cached and uncached rows.
    let snapshot = state.bump_generation();
    let Some(row) = state.releases.get(state.selected) else {
        return;
    };
    if row.release_id.is_empty() || state.prefetch.contains_key(&row.release_id) {
        return;
    }
    let cached_body =
        db.get_cached_mb_search(&super::musicbrainz::detail_cache_key(&row.release_id));
    super::event_loop::spawn_mb_detail_prefetch(
        tx.clone(),
        state.operation_id,
        row.release_id.clone(),
        state.paths.len(),
        std::sync::Arc::clone(&state.generation),
        snapshot,
        cached_body,
    );
}

/// Close the custom auto-number overlay and restore its owning editor.
fn close_metadata_autonumber_restoring_editor(app: &mut AppState) {
    app.active_overlay = ActiveOverlay::None;
    if let Some(editor) = app.pending_metadata_editor.take() {
        app.active_overlay = ActiveOverlay::MetadataEditor(editor);
    }
}

fn apply_metadata_autonumber_overlay(
    app: &mut AppState,
    overlay: &super::metadata_autonumber::AutoNumberOverlayState,
) {
    let Some(mut editor) = app.pending_metadata_editor.take() else {
        app.active_overlay = ActiveOverlay::None;
        app.set_status("Auto-number: owning metadata editor is no longer available");
        return;
    };
    match super::metadata_autonumber::apply_numbering_with_assignments(
        &mut editor,
        overlay.target,
        overlay.scheme,
        &overlay.assignments,
    ) {
        Ok(report) => {
            app.set_status(report.status("Auto-numbered"));
            app.active_overlay = ActiveOverlay::MetadataEditor(editor);
        }
        Err(error) => {
            app.pending_metadata_editor = Some(editor);
            app.active_overlay = ActiveOverlay::MetadataAutoNumber(Box::new(overlay.clone()));
            app.set_status(format!("Auto-number: {error}"));
        }
    }
}

fn handle_metadata_autonumber_key(
    app: &mut AppState,
    state: &mut Box<super::metadata_autonumber::AutoNumberOverlayState>,
    key: KeyEvent,
) {
    if state.prefix_input.is_some() {
        match key.code {
            KeyCode::Esc => {
                state.prefix_input = None;
            }
            KeyCode::Enter => match state.commit_prefix_edit() {
                Ok(count) => app.set_status(format!(
                    "Auto-number: prefix assigned to {} row{}",
                    count,
                    if count == 1 { "" } else { "s" },
                )),
                Err(error) => app.set_status(format!("Auto-number: {error}")),
            },
            _ => {
                if let Some(input) = state.prefix_input.as_mut() {
                    super::text_input::handle_text_input_key(input, &key);
                }
            }
        }
        app.active_overlay = ActiveOverlay::MetadataAutoNumber(state.clone());
        return;
    }

    match key.code {
        KeyCode::Esc => {
            close_metadata_autonumber_restoring_editor(app);
            return;
        }
        KeyCode::Enter => {
            apply_metadata_autonumber_overlay(app, state);
            return;
        }
        KeyCode::Up | KeyCode::Char('k') | KeyCode::Char('K') => {
            state.move_cursor(-1, key.modifiers.contains(KeyModifiers::SHIFT));
        }
        KeyCode::Down | KeyCode::Char('j') | KeyCode::Char('J') => {
            state.move_cursor(1, key.modifiers.contains(KeyModifiers::SHIFT));
        }
        KeyCode::Home => state.move_cursor(-(state.len() as isize), false),
        KeyCode::End => state.move_cursor(state.len() as isize, false),
        KeyCode::Char(' ') => state.toggle_current_selection(),
        KeyCode::Char('p') | KeyCode::Char('P') => state.begin_prefix_edit(),
        KeyCode::Tab | KeyCode::Right => state.scheme = state.scheme.next(),
        KeyCode::BackTab | KeyCode::Left => state.scheme = state.scheme.previous(),
        _ => {}
    }
    app.active_overlay = ActiveOverlay::MetadataAutoNumber(state.clone());
}

fn handle_metadata_autonumber_mouse(app: &mut AppState, mouse: MouseEvent) {
    use crossterm::event::{MouseButton, MouseEventKind};

    let button = app.button_map.find_button_at(mouse.column, mouse.row);
    let ActiveOverlay::MetadataAutoNumber(mut state) = std::mem::replace(
        &mut app.active_overlay,
        ActiveOverlay::None,
    ) else {
        return;
    };

    match mouse.kind {
        MouseEventKind::ScrollUp if state.prefix_input.is_none() => state.move_cursor(-1, false),
        MouseEventKind::ScrollDown if state.prefix_input.is_none() => state.move_cursor(1, false),
        MouseEventKind::Down(MouseButton::Right) => {
            app.active_overlay = ActiveOverlay::MetadataAutoNumber(state);
            return;
        }
        MouseEventKind::Down(MouseButton::Left) => {
            if matches!(button, Some(TuiButton::MetadataAutoNumberCancel)) {
                // A pointer click on the visible Cancel control cancels the
                // whole child overlay, including any uncommitted prefix edit.
                close_metadata_autonumber_restoring_editor(app);
                return;
            }
            let was_editing_prefix = state.prefix_input.is_some();
            // Changing focus commits the prefix edit first, matching the
            // metadata editor's commit-on-focus-change behavior. Invalid
            // input remains active and cannot be applied accidentally.
            if was_editing_prefix
                && !matches!(button, Some(TuiButton::MetadataAutoNumberPrefix))
            {
                if let Err(error) = state.commit_prefix_edit() {
                    app.set_status(format!("Auto-number: {error}"));
                    app.active_overlay = ActiveOverlay::MetadataAutoNumber(state);
                    return;
                }
            }
            match button {
                Some(TuiButton::MetadataAutoNumberScheme(idx)) => {
                    if let Some(scheme) =
                        super::metadata_autonumber::NumberingScheme::ALL.get(idx)
                    {
                        state.scheme = *scheme;
                    }
                }
                Some(TuiButton::MetadataAutoNumberPrefix) => {
                    if state.prefix_input.is_none() {
                        state.begin_prefix_edit();
                    }
                }
                Some(TuiButton::MetadataAutoNumberRow(slot)) if slot < state.len() => {
                    state.cursor = slot;
                    state.toggle_current_selection();
                }
                Some(TuiButton::MetadataAutoNumberApply) => {
                    // A valid in-flight prefix edit commits and applies in the
                    // same click. Requiring a second Apply click would make the
                    // mouse lifecycle differ from Enter and invite stale-preview
                    // mistakes.
                    apply_metadata_autonumber_overlay(app, &state);
                    return;
                }
                Some(TuiButton::MetadataAutoNumberCancel) => {
                    close_metadata_autonumber_restoring_editor(app);
                    return;
                }
                _ => {}
            }
        }
        _ => {}
    }
    app.active_overlay = ActiveOverlay::MetadataAutoNumber(state);
}

///
/// Called from every ContextMenu close path (Esc / Left / outside-click /
/// post-action) so right-click → context menu → Esc round-trips back to
/// the originating overlay. Mirrors the `pending_*.take()` pattern used
/// by the CommandInput Enter/Esc handlers.
fn close_context_menu_restoring_parked(app: &mut AppState) {
    // Restoration order is innermost-parked-first: when SACD
    // `:tags-mb` parks the editor and a subsequent right-click on
    // MbSelect parks the picker, both slots are `Some` at once.
    // The user's mental nesting is editor → MbSelect → ContextMenu,
    // so Esc on the context menu must return to MbSelect, not all
    // the way back to the editor. cue_preview slots between the
    // two for the same reason.
    app.active_overlay = ActiveOverlay::None;
    if let Some(parked) = app.pending_mb_select.take() {
        app.active_overlay = ActiveOverlay::MbSelect(parked);
        return;
    }
    if let Some(parked) = app.pending_cue_preview.take() {
        app.active_overlay = ActiveOverlay::CuePreview(parked);
        return;
    }
    if let Some(parked) = app.pending_metadata_editor.take() {
        app.active_overlay = ActiveOverlay::MetadataEditor(parked);
    }
}

/// Close the CuePreview overlay, restoring the metadata editor if it
/// was parked (the `[view]` pill from a synthetic-preview row sets
/// `pending_metadata_editor` before opening CuePreview in read-only
/// mode). No-op for the other CuePreview entry paths (`:cue-mb`,
/// `:cue-fill`) since they don't park anything.
fn close_cue_preview_restoring_parked(app: &mut AppState) {
    app.active_overlay = ActiveOverlay::None;
    if let Some(parked) = app.pending_metadata_editor.take() {
        app.active_overlay = ActiveOverlay::MetadataEditor(parked);
    }
}

/// Run a context-menu action, then restore any parked overlay if the
/// action didn't set its own overlay. Wraps the common pattern:
/// "close menu, run action, if action didn't take a parked state and
/// didn't open something else, put the parked state back."
fn run_context_action_restoring_parked(
    app: &mut AppState,
    action: super::context_menu::ContextAction,
    tx: &mpsc::Sender<AppMessage>,
    invert: bool,
) {
    app.active_overlay = ActiveOverlay::None;
    super::context_menu::execute_context_action(app, action, tx, invert);
    if matches!(app.active_overlay, ActiveOverlay::None) {
        // An editor-originated GNUDB operation owns the parked editor until
        // its guarded completion, explicit cancellation, or error retirement.
        // Restoring it here would let the eventual completion overwrite a live
        // dirty editor instead of transitioning from an owned parked session.
        if app
            .active_gnudb_operation
            .is_some_and(|active| active.editor_session.is_some())
            && app.pending_metadata_editor.is_some()
        {
            return;
        }
        // Same innermost-first restoration order as
        // `close_context_menu_restoring_parked`. See that function's
        // comment for why the SACD `:tags-mb` flow demands it.
        if let Some(parked) = app.pending_mb_select.take() {
            app.active_overlay = ActiveOverlay::MbSelect(parked);
            return;
        }
        if let Some(parked) = app.pending_cue_preview.take() {
            app.active_overlay = ActiveOverlay::CuePreview(parked);
            return;
        }
        if let Some(parked) = app.pending_metadata_editor.take() {
            app.active_overlay = ActiveOverlay::MetadataEditor(parked);
        }
    } else {
        // Action set its own overlay. A MusicBrainz accept now transitions to
        // a non-interactive verifying picker while the source editor remains
        // parked; dropping that editor here would make both cancellation and
        // the guarded completion lose their authoritative target.
        let preserve_mb_editor = matches!(
            &app.active_overlay,
            ActiveOverlay::MbSelect(_)
        ) || app.active_tags_mb_operation.is_some();
        let preserve_gnudb_editor = app
            .active_gnudb_operation
            .is_some_and(|active| active.editor_session.is_some());
        let preserve_autonumber_editor = matches!(
            app.active_overlay,
            ActiveOverlay::MetadataAutoNumber(_)
        );
        if !preserve_mb_editor && !preserve_gnudb_editor && !preserve_autonumber_editor {
            app.pending_metadata_editor = None;
        }
        app.pending_cue_preview = None;
        app.pending_mb_select = None;
    }
}

/// Keyboard handler for the context menu.
///
/// Model: `levels` is the explicitly navigated stack; `levels.last()` is
/// the focused panel. The renderer additionally previews children of
/// the focused panel's selected entry as a "phantom" deeper panel when
/// that entry is a Submenu — that phantom is *not* in `levels`.
///
/// - Up/Down: move selection in `levels.last()`
/// - Right / Enter on Submenu: push children as new focused level (cap MAX)
/// - Enter on Item: execute action, close menu
/// - Left: pop focused level; close menu at root
/// - Esc: close menu entirely
fn handle_context_menu_key(
    app: &mut AppState,
    key: KeyEvent,
    mut levels: Vec<super::context_menu::MenuLevel>,
    origin: (u16, u16),
    tx: &mpsc::Sender<AppMessage>,
) {
    use super::context_menu::{ContextMenuEntry, MenuLevel, MAX_CONTEXT_MENU_DEPTH};

    fn selectable_indices(entries: &[ContextMenuEntry]) -> Vec<usize> {
        entries
            .iter()
            .enumerate()
            .filter_map(|(i, e)| match e {
                ContextMenuEntry::Item(item) if item.enabled => Some(i),
                ContextMenuEntry::Submenu { .. } => Some(i),
                _ => None,
            })
            .collect()
    }

    if levels.is_empty() {
        close_context_menu_restoring_parked(app);
        return;
    }

    match key.code {
        KeyCode::Esc => {
            close_context_menu_restoring_parked(app);
            return;
        }
        KeyCode::Left => {
            if levels.len() > 1 {
                levels.pop();
            } else {
                close_context_menu_restoring_parked(app);
                return;
            }
        }
        KeyCode::Right => {
            let depth = levels.len();
            let cur = &levels[depth - 1];
            let sel = selectable_indices(&cur.entries);
            if let Some(&idx) = sel.get(cur.selected) {
                if let ContextMenuEntry::Submenu { children, .. } = &cur.entries[idx] {
                    if depth < MAX_CONTEXT_MENU_DEPTH {
                        levels.push(MenuLevel::new(children.clone()));
                    }
                }
            }
        }
        KeyCode::Enter | KeyCode::Char('q') => {
            let invert = key.code == KeyCode::Char('q');
            let depth = levels.len();
            let cur = &levels[depth - 1];
            let sel = selectable_indices(&cur.entries);
            if let Some(&idx) = sel.get(cur.selected) {
                match &cur.entries[idx] {
                    ContextMenuEntry::Item(item) => {
                        let action = item.action.clone();
                        run_context_action_restoring_parked(app, action, tx, invert);
                        return;
                    }
                    ContextMenuEntry::Submenu { children, .. } => {
                        if depth < MAX_CONTEXT_MENU_DEPTH {
                            levels.push(MenuLevel::new(children.clone()));
                        }
                    }
                    _ => {}
                }
            }
        }
        KeyCode::Up | KeyCode::Char('k') => {
            let cur = levels.last_mut().unwrap();
            if cur.selected > 0 {
                cur.selected -= 1;
            }
        }
        KeyCode::Down | KeyCode::Char('j') => {
            let cur = levels.last_mut().unwrap();
            let n = selectable_indices(&cur.entries).len();
            if cur.selected + 1 < n {
                cur.selected += 1;
            }
        }
        _ => {
            // Unhandled keys are inert. A context menu is modal; silently
            // dismissing it would also strand any parked owning overlay.
        }
    }

    app.active_overlay = ActiveOverlay::ContextMenu { levels, origin };
}

/// Build and open the context menu for the current screen. `x, y` is
/// the screen position where the menu should be anchored (right-click
/// position, or a computed position for keyboard `m`).
pub fn open_context_menu(app: &mut AppState, x: u16, y: u16) {
    use super::context_menu::*;

    let entries = match app.current_screen {
        AppScreen::Browse => {
            // Entry hit targets are registered after BrowseList and therefore
            // win reverse hit-testing. A click on the remaining list area is
            // true empty space even when another row remains selected.
            match app.button_map.find_button_at(x, y) {
                Some(TuiButton::BrowseEntry(_)) | Some(TuiButton::BrowseEntryGutter(_)) => {
                    build_browse_entry_menu(app)
                }
                Some(TuiButton::BrowseList) => build_browse_empty_menu(app),
                _ if app.browse.selected_entry().is_some() => build_browse_entry_menu(app),
                _ => build_browse_empty_menu(app),
            }
        }
        AppScreen::Convert => build_convert_menu(app),
        AppScreen::Queue => {
            if app.items_snapshot.is_empty() {
                build_queue_empty_menu(app)
            } else {
                build_queue_item_menu(app)
            }
        }
        _ => {
            // Library, Config, Wizard — no context menu yet.
            return;
        }
    };

    if entries.is_empty() {
        return;
    }

    let mut levels = vec![super::context_menu::MenuLevel::new(entries)];
    // If the root's first entry is a Submenu, auto-push it so users
    // see the cascade preview without first arrowing down.
    if let Some(crate::tui::context_menu::ContextMenuEntry::Submenu { children, .. }) =
        levels[0].entries.first()
    {
        if levels.len() < super::context_menu::MAX_CONTEXT_MENU_DEPTH {
            levels.push(super::context_menu::MenuLevel::new(children.clone()));
        }
    }

    app.active_overlay = ActiveOverlay::ContextMenu {
        levels,
        origin: (x, y),
    };
}

/// Handle key events inside the metadata editor overlay.
/// Open the "add new field" prompt (sets cursor to the add row,
/// initializes add_key_input, transitions to AddingKey phase).
pub(super) fn metadata_editor_open_add(state: &mut super::app::MetadataEditorState) -> Option<String> {
    let (writable, blocked) = metadata_editor_file_slot_counts(state);
    if writable == 0 && blocked > 0 {
        return Some("metadata editor: cannot add field — no writable files in this editor session".to_string());
    }
    state.cursor = state.active_surface().entries.len();
    state.add_key_input = Some(super::text_input::TextInputState::empty());
    state.phase = super::app::MetadataEditorPhase::AddingKey;
    ensure_cursor_visible(state);
    (blocked > 0).then(|| {
        format!(
            "metadata editor: new field will apply to {} writable file{}; {} blocked slot{} will remain unchanged",
            writable,
            if writable == 1 { "" } else { "s" },
            blocked,
            if blocked == 1 { "" } else { "s" }
        )
    })
}

fn unified_cue_album_per_track_key_is_persistable(display_key: &str) -> bool {
    matches!(
        display_key.to_ascii_uppercase().as_str(),
        "TITLE" | "ARTIST" | "ISRC"
    )
}

fn unified_cue_album_per_track_add_key_refusal(
    state: &super::app::MetadataEditorState,
    display_key: &str,
) -> Option<String> {
    let surface = state.active_surface();
    let sheet = surface.cue_album_synthetic_sheet.as_ref()?;
    let canonical = super::probe::canonical_metadata_display_key(display_key);
    if canonical == "TRACKNUMBER" {
        return Some(
            "metadata editor: cannot edit per-track TRACKNUMBER on a multi-image CUE album; CUE TRACK numbers are positional and continuous"
                .to_string(),
        );
    }
    if matches!(
        canonical.as_str(),
        "ISRC" | "MUSICBRAINZ_TRACKID" | "MUSICBRAINZ_RELEASETRACKID"
    ) {
        return Some(format!(
            "metadata editor: cannot persist per-track {} on a multi-image CUE album",
            canonical
        ));
    }
    let track_dim = sheet.track_sources.len();
    if surface.entries.iter().any(|entry| {
        super::probe::canonical_metadata_display_key(&entry.display_key) == canonical
            && entry.is_track_scoped(surface.paths.len())
            && entry.per_file_values.len() == track_dim
    }) {
        return Some(format!(
            "metadata editor: cannot add {}; it is already managed by the unified CUE album projection",
            canonical
        ));
    }
    None
}

const MULTI_FILE_EMBEDDED_CUESHEET_READ_ONLY_STATUS: &str =
    "metadata editor: this file carries a multi-FILE embedded CUESHEET naming other album members; CUESHEET-affecting fields are read-only here — open the containing folder to edit the complete album";

fn metadata_editor_multi_file_embedded_cuesheet_reason(
    state: &super::app::MetadataEditorState,
) -> Option<String> {
    let surface = state.active_surface();
    if surface.cue_album_synthetic_sheet.is_some()
        || surface.paths.len() != 1
        || !surface.embedded_cuesheet_present
    {
        return None;
    }
    let cue = surface.entries.iter().find(|entry| {
        entry.display_key.eq_ignore_ascii_case("CUESHEET")
    })?;
    let text = cue
        .per_file_originals
        .first()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| cue.per_file_values.first())?;
    let parsed = super::cue_parser::parse_cue(text);
    let referenced_files: std::collections::BTreeSet<String> = parsed
        .tracks
        .iter()
        .filter_map(|track| track.file.as_ref())
        .map(|file| file.replace('\\', "/").to_ascii_lowercase())
        .collect();
    (referenced_files.len() > 1).then(|| {
        MULTI_FILE_EMBEDDED_CUESHEET_READ_ONLY_STATUS.to_string()
    })
}

fn metadata_editor_key_affects_embedded_cuesheet(display_key: &str) -> bool {
    matches!(
        super::probe::canonical_metadata_display_key(display_key).as_str(),
        "CUESHEET"
            | "TITLE"
            | "ARTIST"
            | "ISRC"
            | "TRACKNUMBER"
            | "ALBUM"
            | "ALBUMARTIST"
            | "DATE"
            | "YEAR"
            | "GENRE"
            | "CATALOGNUMBER"
    )
}

fn metadata_editor_entry_affects_embedded_cuesheet(
    state: &super::app::MetadataEditorState,
    entry_idx: usize,
) -> bool {
    let surface = state.active_surface();
    let Some(entry) = surface.entries.get(entry_idx) else {
        return false;
    };
    entry.is_track_scoped(surface.paths.len())
        || metadata_editor_key_affects_embedded_cuesheet(&entry.display_key)
}

pub(super) fn metadata_editor_unpersistable_per_track_reason(
    state: &super::app::MetadataEditorState,
    entry_idx: usize,
) -> Option<String> {
    if metadata_editor_entry_affects_embedded_cuesheet(state, entry_idx) {
        if let Some(reason) = metadata_editor_multi_file_embedded_cuesheet_reason(state) {
            return Some(reason);
        }
    }
    let surface = state.active_surface();
    if surface.cue_album_synthetic_sheet.is_none() {
        return None;
    }
    let entry = surface.entries.get(entry_idx)?;
    let track_dim = surface
        .cue_album_synthetic_sheet
        .as_ref()
        .map(|sheet| sheet.track_sources.len())
        .unwrap_or(0);
    if entry.display_key.eq_ignore_ascii_case("TRACKNUMBER")
        && track_dim > 0
        && entry.per_file_values.len() == track_dim
    {
        return Some(
            "metadata editor: cannot edit per-track TRACKNUMBER on a multi-image CUE album; CUE TRACK numbers are positional and continuous"
                .to_string(),
        );
    }
    if !entry.is_track_scoped(surface.paths.len()) {
        return None;
    }
    if unified_cue_album_per_track_key_is_persistable(&entry.display_key) {
        return None;
    }
    if entry.display_key.eq_ignore_ascii_case("TRACKNUMBER") {
        return Some(
            "metadata editor: cannot edit per-track TRACKNUMBER on a multi-image CUE album; CUE TRACK numbers are positional and continuous"
                .to_string(),
        );
    }
    Some(format!(
        "metadata editor: cannot persist per-track {} on a multi-image CUE album",
        entry.display_key
    ))
}

/// Begin editing the cursor row through the same persistence-policy gate used
/// by keyboard, mouse, and context-menu entry points. Returning `Some(status)`
/// means the caller should leave the editor visible and show that status;
/// returning `None` means the edit/detail transition was either started or the
/// cursor was not editable.
pub(super) fn metadata_editor_begin_cursor_value_edit(
    state: &mut super::app::MetadataEditorState,
    select_existing_value: bool,
) -> Option<String> {
    let cursor = state.cursor;
    if cursor >= state.active_surface().entries.len() {
        return None;
    }
    if state.active_surface().deleted.contains(&cursor) {
        return Some("metadata editor: restore field before editing".to_string());
    }
    if state.read_only {
        return Some("read-only editor (SACD ISO)".to_string());
    }
    if let Some(reason) = metadata_editor_unpersistable_per_track_reason(state, cursor) {
        return Some(reason);
    }

    let Some(entry) = state.active_surface().entries.get(cursor) else {
        return None;
    };
    if entry.is_binary {
        return Some("metadata editor: cannot edit binary field".to_string());
    }

    let is_mixed = entry.is_mixed;
    let value_count = entry.per_file_values.len();
    let value = entry.value.clone();
    if is_mixed && value_count > 1 {
        return metadata_editor_begin_detail_edit_for_entry(state, cursor, false);
    }

    let (writable, blocked) = metadata_editor_entry_slot_counts(state, cursor);
    if writable == 0 && blocked > 0 {
        let reason = metadata_editor_entry_edit_block_reason(state, cursor)
            .unwrap_or_else(|| "no writable file slots".to_string());
        return Some(format!("metadata editor: cannot edit blocked field — {reason}"));
    }
    if blocked > 0 {
        if let Some(status) = metadata_editor_begin_detail_edit_for_entry(state, cursor, true) {
            return Some(status);
        }
        return Some(format!(
            "metadata editor: editing per-file values; {} writable file{} can change, {} blocked slot{} remain visible and locked",
            writable,
            if writable == 1 { "" } else { "s" },
            blocked,
            if blocked == 1 { "" } else { "s" }
        ));
    }

    state.edit_input = Some(if select_existing_value {
        super::text_input::TextInputState::new_selected(value)
    } else {
        super::text_input::TextInputState::new(value)
    });
    state.phase = super::app::MetadataEditorPhase::InlineEdit;
    None
}

/// Mark the cursor row for deletion (renders strikethrough until save).
pub(super) fn metadata_editor_delete_cursor_requires_embedded_cuesheet_confirmation(
    state: &super::app::MetadataEditorState,
) -> bool {
    let surface = state.active_surface();
    if state.cursor >= surface.entries.len() || surface.deleted.contains(&state.cursor) {
        return false;
    }
    if !surface.entries[state.cursor].display_key.eq_ignore_ascii_case("CUESHEET") {
        return false;
    }
    embedded_cuesheet_command_target(state, "cuesheet-delete").is_ok()
}

pub(super) fn metadata_editor_delete_cursor(state: &mut super::app::MetadataEditorState) -> Option<String> {
    if state.cursor >= state.active_surface().entries.len() || state.active_surface().deleted.contains(&state.cursor) {
        return None;
    }

    let entry_key = state.active_surface().entries[state.cursor].display_key.clone();
    if entry_key.eq_ignore_ascii_case("CUE MERGE NOTES") {
        let removed = state.cursor;
        state.active_surface_mut().entries.remove(removed);
        let remapped_deleted = state
            .active_surface()
            .deleted
            .iter()
            .filter_map(|&idx| {
                if idx == removed {
                    None
                } else {
                    Some(if idx > removed { idx - 1 } else { idx })
                }
            })
            .collect();
        state.active_surface_mut().deleted = remapped_deleted;
        let len = state.active_surface().entries.len();
        state.cursor = state.cursor.min(len.saturating_sub(1));
        recalc_dirty(state);
        return Some("metadata editor: removed informational CUE MERGE NOTES row".to_string());
    }

    if entry_key.eq_ignore_ascii_case("CUESHEET") {
        return match embedded_cuesheet_command_target(state, "cuesheet-delete") {
            Ok(_) => Some(
                "metadata editor: embedded CUESHEET deletion requires confirmation"
                    .to_string(),
            ),
            Err(reason) => Some(reason),
        };
    }

    if let Some(reason) = metadata_editor_unpersistable_per_track_reason(state, state.cursor) {
        return Some(reason);
    }

    let (writable, blocked) = metadata_editor_entry_slot_counts(state, state.cursor);
    if writable == 0 && blocked > 0 {
        return Some("metadata editor: cannot delete field — no writable file slots for this row".to_string());
    }

    let cursor = state.cursor;
    state.active_surface_mut().deleted.push(cursor);
    recalc_dirty(state);
    if blocked > 0 {
        Some(format!(
            "metadata editor: delete will apply to {} writable file{}; {} blocked slot{} will retain the field",
            writable,
            if writable == 1 { "" } else { "s" },
            blocked,
            if blocked == 1 { "" } else { "s" }
        ))
    } else {
        None
    }
}

/// Un-delete the cursor row (removes it from the deleted set).
pub(super) fn metadata_editor_undelete_cursor(state: &mut super::app::MetadataEditorState) {
    let cursor = state.cursor;
    state.active_surface_mut().deleted.retain(|&i| i != cursor);
    recalc_dirty(state);
}

/// Force-open the per-file detail overlay on the cursor entry. Gated
/// on per_file_values.len() > 1 (so per-track entries on single-image
/// rips qualify even when paths.len() == 1).
pub(super) fn metadata_editor_open_detail(state: &mut super::app::MetadataEditorState) -> Option<String> {
    if state.cursor >= state.active_surface().entries.len() {
        return None;
    }
    if state.active_surface().deleted.contains(&state.cursor) {
        return Some("metadata editor: restore field before opening detail editor".to_string());
    }
    metadata_editor_begin_detail_edit_for_entry(state, state.cursor, false)
}


fn cue_album_forced_cleanup_item_allowed(key: &lofty::tag::ItemKey) -> bool {
    !matches!(key, lofty::tag::ItemKey::MusicBrainzArtistId)
}

fn metadata_editor_forced_delete_items(
    state: &super::app::MetadataEditorState,
) -> Vec<(usize, lofty::tag::ItemKey)> {
    let mut forced = Vec::new();
    if state.active_surface().pending_embedded_cuesheet_delete {
        forced.extend(
            (0..state.active_surface().paths.len())
                .map(|idx| (idx, lofty::tag::ItemKey::Unknown("CUESHEET".to_string()))),
        );
    }
    if state.active_surface().cue_album_synthetic_sheet.is_some() {
        forced.extend(
            state
                .active_surface()
                .cue_album_forced_cleanup
                .iter()
                .filter(|(_, key)| cue_album_forced_cleanup_item_allowed(key))
                .cloned(),
        );
    }
    forced
}


fn metadata_editor_has_audio_save_work(
    state: &super::app::MetadataEditorState,
    forced_deletes: &[(usize, lofty::tag::ItemKey)],
) -> bool {
    state.any_presentation_dirty() || !forced_deletes.is_empty()
}

fn metadata_editor_entries_snapshot_for_save(
    state: &super::app::MetadataEditorState,
) -> Vec<(lofty::tag::ItemKey, crate::tui::probe::RowScope, Vec<String>, Vec<String>)> {
    let surface = state.active_surface();
    let suppress_sidecar_shadow_cuesheet =
        surface.sidecar_cuesheet_shadow_present && !surface.embedded_cuesheet_present;

    surface
        .entries
        .iter()
        .map(|entry| {
            let originals = entry.per_file_originals.clone();
            let values = if suppress_sidecar_shadow_cuesheet
                && entry.display_key.eq_ignore_ascii_case("CUESHEET")
            {
                // A sidecar shadow is the editable structural anchor for the
                // sidecar CUE, not an embedded-tag create/update request. Keep
                // the ordinary lofty diff blind to the regenerated shadow; the
                // dedicated sidecar write-back plan persists it instead.
                originals.clone()
            } else {
                entry.per_file_values.clone()
            };
            (
                entry.item_key.clone(),
                entry.effective_row_scope(surface.paths.len()),
                values,
                originals,
            )
        })
        .collect()
}

fn metadata_editor_audio_tag_changes_required_for_sidecar_writeback(
    state: &super::app::MetadataEditorState,
) -> bool {
    let surface = state.active_surface();
    let path_count = surface.paths.len();
    if path_count != 1 {
        return true;
    }
    if !metadata_editor_forced_delete_items(state).is_empty() {
        return true;
    }

    let deleted: std::collections::BTreeSet<usize> = surface.deleted.iter().copied().collect();
    metadata_editor_entries_snapshot_for_save(state)
        .into_iter()
        .enumerate()
        .any(|(entry_idx, (_key, row_scope, values, originals))| {
            if row_scope == crate::tui::probe::RowScope::Track {
                return false;
            }
            if values.len() != path_count || originals.len() != path_count {
                return false;
            }
            deleted.contains(&entry_idx) || values.iter().zip(originals.iter()).any(|(v, o)| v != o)
        })
}

fn metadata_save_byte_count(bytes: u64) -> String {
    const KIB: f64 = 1024.0;
    const MIB: f64 = 1024.0 * KIB;
    const GIB: f64 = 1024.0 * MIB;
    let bytes = bytes as f64;
    if bytes >= GIB {
        format!("{:.1} GiB", bytes / GIB)
    } else if bytes >= MIB {
        format!("{:.1} MiB", bytes / MIB)
    } else if bytes >= KIB {
        format!("{:.1} KiB", bytes / KIB)
    } else {
        format!("{} B", bytes as u64)
    }
}

fn metadata_save_progress_detail(
    file_index: usize,
    file_total: usize,
    path: &std::path::Path,
    update: crate::dsf_tags::DsfWriteProgress,
) -> String {
    let file_name = path
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string());
    let phase = match update.phase {
        crate::dsf_tags::DsfWriteProgressPhase::Preparing => "preparing",
        crate::dsf_tags::DsfWriteProgressPhase::Journaling => "journaling",
        crate::dsf_tags::DsfWriteProgressPhase::WritingTail => "writing tag",
        crate::dsf_tags::DsfWriteProgressPhase::CopyingPrefix => "rewriting",
        crate::dsf_tags::DsfWriteProgressPhase::Publishing => "publishing",
        crate::dsf_tags::DsfWriteProgressPhase::Recovering => "restoring",
    };
    if update.bytes_total == 0 {
        format!("Saving {file_index}/{file_total}: {file_name} - {phase}")
    } else {
        format!(
            "Saving {file_index}/{file_total}: {file_name} - {phase} {} / {}",
            metadata_save_byte_count(update.bytes_done),
            metadata_save_byte_count(update.bytes_total)
        )
    }
}

#[cfg(test)]
mod metadata_save_progress_tests {
    use super::*;

    #[test]
    fn dsf_byte_progress_footer_reports_file_phase_and_exact_byte_totals() {
        let detail = metadata_save_progress_detail(
            2,
            10,
            std::path::Path::new("/music/track-02.dsf"),
            crate::dsf_tags::DsfWriteProgress {
                phase: crate::dsf_tags::DsfWriteProgressPhase::CopyingPrefix,
                bytes_done: 512 * 1024 * 1024,
                bytes_total: 1024 * 1024 * 1024,
            },
        );
        assert_eq!(
            detail,
            "Saving 2/10: track-02.dsf - rewriting 512.0 MiB / 1.0 GiB"
        );
    }
}

/// Save tags to disk. Runs Phase 4's CUESHEET regen (β album re-derive
/// + per-track-edit overrides) before snapshotting; refuses save on a
/// dirty per-track entry without a CUESHEET anchor. Skips per-track
/// entries from lofty's per-file write loop (their truth is the
/// regenerated CUESHEET tag).
pub(super) fn metadata_editor_save(
    app: &mut AppState,
    state: &mut super::app::MetadataEditorState,
    tx: &mpsc::Sender<AppMessage>,
) {
    if state.read_only {
        if metadata_editor_is_bluray_source(state) {
            app.set_status("read-only editor — cannot save (Blu-ray sidecar)");
        } else if metadata_editor_is_dvdv_source(state) {
            app.set_status("read-only editor — cannot save (DVD-Video sidecar)");
        } else if state.sacd_sidecar_path.is_some() && state.active_surface().sacd_area_kind.is_none() {
            app.set_status("read-only editor — cannot save (DVD-Audio metabase)");
        } else {
            app.set_status("read-only editor — cannot save (SACD ISO)");
        }
        return;
    }
    let forced_deletes_for_save = metadata_editor_forced_delete_items(state);
    if !metadata_editor_has_audio_save_work(state, &forced_deletes_for_save) {
        app.set_status("No changes to save");
        return;
    }
    // Disc-image save: route sidecar-backed editors away from the lofty / per-file path.
    if metadata_editor_is_bluray_source(state) {
        let Some(source_path) = state.active_surface().paths.first().cloned() else {
            app.set_status("Blu-ray sidecar save failed: editor has no source");
            return;
        };
        match super::command::save_bluray_metadata_sidecar_dirty_presentations_from_state(
            &source_path,
            state,
        ) {
            Ok(outcome) => {
                state.mark_presentation_tabs_saved(&outcome.saved_tab_indices);
                let file_name = outcome
                    .path
                    .file_name()
                    .map(|s| s.to_string_lossy().into_owned())
                    .unwrap_or_else(|| outcome.path.display().to_string());
                let remaining = state.dirty_presentation_count();
                app.set_status(bluray_sidecar_save_status(&outcome, &file_name, remaining));
            }
            Err(reason) => {
                app.set_status(format!("Blu-ray sidecar save failed: {}", reason));
            }
        }
        return;
    }

    if metadata_editor_is_dvdv_source(state) {
        if !state.active_presentation_is_dirty() {
            app.set_status(
                "DVD-Video sidecar save skipped: active presentation has no changes; switch tabs to save other dirty presentations",
            );
            return;
        }
        let Some(source_path) = state.active_surface().paths.first().cloned() else {
            app.set_status("DVD-Video sidecar save failed: editor has no source");
            return;
        };
        match super::command::save_dvdv_metadata_sidecar(&source_path, state) {
            Ok(outcome) => {
                state.mark_active_presentation_saved();
                let remaining = state.dirty_presentation_count();
                let file_name = outcome
                    .path
                    .file_name()
                    .map(|s| s.to_string_lossy().into_owned())
                    .unwrap_or_else(|| outcome.path.display().to_string());
                let verb = match outcome.kind {
                    super::command::DvdVideoSidecarSaveKind::Created => "created",
                    super::command::DvdVideoSidecarSaveKind::AddedPresentation => "added presentation to",
                    super::command::DvdVideoSidecarSaveKind::UpdatedPresentation => "updated presentation in",
                };
                let presentation = outcome
                    .presentation_id
                    .as_deref()
                    .map(|id| format!(" ({id})"))
                    .unwrap_or_default();
                if remaining == 0 {
                    app.set_status(format!("DVD-Video sidecar {verb}: {file_name}{presentation}"));
                } else {
                    app.set_status(format!(
                        "DVD-Video sidecar {verb}: {file_name}{presentation}; {} unsaved presentation(s) remain",
                        remaining
                    ));
                }
            }
            Err(reason) => {
                app.set_status(format!("DVD-Video sidecar save failed: {}", reason));
            }
        }
        return;
    }

    if let Some(sidecar_path) = state.sacd_sidecar_path.clone() {
        if state.active_surface().sacd_area_kind.is_none() {
            match save_dvda_metabase(state, &sidecar_path) {
                Ok(kind) => {
                    state.mark_all_presentations_saved();
                    let verb = match kind {
                        SacdSaveKind::Created => "created",
                        SacdSaveKind::Updated => "updated",
                    };
                    let file_name = sidecar_path
                        .file_name()
                        .map(|s| s.to_string_lossy().into_owned())
                        .unwrap_or_else(|| sidecar_path.display().to_string());
                    app.set_status(format!("DVD-Audio metabase {}: {}", verb, file_name));
                }
                Err(reason) => {
                    app.set_status(format!("DVD-Audio metabase save failed: {}", reason));
                }
            }
            return;
        }

        match save_sacd_sidecar(state, &sidecar_path) {
            Ok(outcome) => {
                state.mark_all_presentations_saved();
                let verb = match outcome.kind {
                    SacdSaveKind::Created => "created",
                    SacdSaveKind::Updated => "updated",
                };
                let file_name = sidecar_path
                    .file_name()
                    .map(|s| s.to_string_lossy().into_owned())
                    .unwrap_or_else(|| sidecar_path.display().to_string());
                let area_note = if state.presentation_tabs.len() > 1 {
                    format!("{} areas", state.presentation_tabs.len())
                } else {
                    let mirror = outcome.mirror;
                    let surfaced = match state.active_surface().sacd_area_kind {
                        Some(super::sacd::AreaKind::Stereo) => "stereo",
                        Some(super::sacd::AreaKind::MultiChannel) => "MCH",
                        None => "?",
                    };
                    let sibling = match state.active_surface().sacd_area_kind {
                        Some(super::sacd::AreaKind::Stereo) => "MCH",
                        Some(super::sacd::AreaKind::MultiChannel) => "stereo",
                        None => "?",
                    };
                    if !mirror.sibling_present {
                        format!("{} area only", surfaced)
                    } else if mirror.mirrored_count == mirror.sibling_total {
                        format!("{} + {} areas", surfaced, sibling)
                    } else {
                        format!(
                            "{} + {}/{} {} tracks (count differs)",
                            surfaced, mirror.mirrored_count, mirror.sibling_total, sibling,
                        )
                    }
                };
                app.set_status(format!(
                    "SACD sidecar {} ({}): {}",
                    verb, area_note, file_name,
                ));
            }
            Err(reason) => {
                app.set_status(format!("SACD sidecar save failed: {}", reason));
            }
        }
        return;
    }
    let regenerated_cuesheet = match regenerate_cuesheet_for_save(state) {
        Ok(regenerated) => regenerated,
        Err(reason) => {
            app.set_status(reason);
            return;
        }
    };
    let cue_sidecar_writeback = if regenerated_cuesheet {
        cue_sidecar_writeback_plan_for_state(state)
    } else {
        None
    };
    state.phase = super::app::MetadataEditorPhase::Saving;
    let (session_id, save_generation, cancel) = state.begin_cancellable_write();
    let paths = state.active_surface().paths.clone();
    state.model.metadata_save_progress = Some(format!("Saving 0/{}", paths.len()));
    let deleted = state.active_surface().deleted.clone();
    let save_block_reasons: Vec<Option<String>> = state.active_surface()
        .technical_details
        .files
        .iter()
        .map(|file| {
            file.file_facts
                .write_eligibility
                .block_reason()
                .map(str::to_string)
        })
        .collect();
    let blocked_count = save_block_reasons.iter().filter(|reason| reason.is_some()).count();
    if blocked_count > 0 {
        app.set_status(format!(
            "Saving eligible files; {} file{} will be skipped due to read/write eligibility",
            blocked_count,
            if blocked_count == 1 { "" } else { "s" }
        ));
    }
    let entries_snap = metadata_editor_entries_snapshot_for_save(state);
    let forced_deletes = forced_deletes_for_save;
    let reread_after_embedded_cuesheet_delete =
        state.active_surface().pending_embedded_cuesheet_delete;

    let tx = tx.clone();
    tokio::spawn(async move {
        let progress_tx = tx.clone();
        let results = tokio::task::spawn_blocking(move || {
            let byte_progress_tx = progress_tx.clone();
            let byte_progress: crate::tui::probe::MetadataWriteByteProgressCallback =
                std::sync::Arc::new(move |file_index, file_total, path, update| {
                    let _ = byte_progress_tx.blocking_send(AppMessage::MetadataEditorWriteProgress {
                        session_id,
                        save_generation,
                        detail: metadata_save_progress_detail(
                            file_index,
                            file_total,
                            path,
                            update,
                        ),
                    });
                });
            let progress: crate::tui::probe::MetadataWriteProgressCallback = std::sync::Arc::new(
                move |done, total, path, result| {
                    let file_name = path
                        .file_name()
                        .map(|name| name.to_string_lossy().into_owned())
                        .unwrap_or_else(|| path.display().to_string());
                    let outcome = match &result.outcome {
                        crate::tui::app::MetadataEditorWriteOutcome::Saved => "saved",
                        crate::tui::app::MetadataEditorWriteOutcome::SavedWithWarnings { .. } => "saved with warning",
                        crate::tui::app::MetadataEditorWriteOutcome::Failed { .. } => "failed",
                        crate::tui::app::MetadataEditorWriteOutcome::Skipped { .. } => "skipped",
                        crate::tui::app::MetadataEditorWriteOutcome::SidecarCueSaved { .. } => "sidecar saved",
                        crate::tui::app::MetadataEditorWriteOutcome::SidecarCueFailed { .. } => "sidecar failed",
                    };
                    let _ = progress_tx.blocking_send(AppMessage::StatusMessage(format!(
                        "metadata save {done}/{total}: {file_name} {outcome}"
                    )));
                },
            );
            let mut results = crate::tui::probe::apply_audio_tag_changes_with_save_blocks_progress_and_forced_deletes(
                &paths,
                &entries_snap,
                &deleted,
                &save_block_reasons,
                Some(progress),
                Some(byte_progress),
                Some(cancel.clone()),
                &forced_deletes,
            );
            if let Some(plan) = cue_sidecar_writeback {
                if let Some(sidecar_result) =
                    cue_sidecar_writeback_result_after_successful_image_save(plan, &results)
                {
                    results.push(sidecar_result);
                }
            }
            let all_carriers_saved = paths.iter().all(|path| {
                results.iter().any(|result| {
                    result.path == *path
                        && matches!(
                            &result.outcome,
                            crate::tui::app::MetadataEditorWriteOutcome::Saved
                                | crate::tui::app::MetadataEditorWriteOutcome::SavedWithWarnings { .. }
                        )
                })
            });
            let refreshed_entries = if reread_after_embedded_cuesheet_delete && all_carriers_saved {
                Some(crate::tui::probe::read_all_tags_merged(&paths))
            } else {
                None
            };
            (results, refreshed_entries)
        })
        .await
        .unwrap_or_else(|e| {
            // Whole-batch task panic is unusual (write_all_tags errors
            // are returned, not panicked). If it does happen, surface
            // a single batch-level error rather than losing the
            // request silently.
            (
                vec![crate::tui::app::MetadataEditorWriteResult::failed(
                    std::path::PathBuf::new(),
                    format!("save task panic: {}", e),
                )],
                None,
            )
        });
        let _ = tx
            .send(AppMessage::MetadataEditorWriteComplete {
                session_id,
                save_generation,
                results: results.0,
                refreshed_entries: results.1,
            })
            .await;
    });
}


#[derive(Debug, Clone)]
struct CueSidecarWritebackPlan {
    audio_path: std::path::PathBuf,
    required_audio_paths: Vec<std::path::PathBuf>,
    cue_path: std::path::PathBuf,
    replacement_cuesheet: String,
    require_successful_image_save: bool,
    preflight_error: Option<String>,
}

fn cue_sidecar_writeback_plan_for_state(
    state: &super::app::MetadataEditorState,
) -> Option<CueSidecarWritebackPlan> {
    let surface = state.active_surface();
    let (audio_path, required_audio_paths, cue_path, mut preflight_error) =
        if surface.paths.len() == 1 {
            let audio_path = surface.paths.first()?.clone();
            let cue_path = surface
                .cue_source
                .as_ref()?
                .sidecar_path()?
                .to_path_buf();
            let preflight_error =
                match crate::convert::split_cue_album::admit_split_cue_member(&cue_path) {
                    Ok(member)
                        if member.referenced_audio.len() == 1
                            && metadata_cue_surface_key(&member.referenced_audio[0])
                                == metadata_cue_surface_key(&audio_path) =>
                    {
                        None
                    }
                    Ok(_) => Some(format!(
                        "sidecar CUE '{}' no longer describes the open image; image tags were \
                         saved but the sidecar was left unchanged",
                        cue_path.display()
                    )),
                    Err(err) => Some(format!(
                        "sidecar CUE '{}' could not be revalidated before save: {}; image tags \
                         were saved but the sidecar was left unchanged",
                        cue_path.display(),
                        err
                    )),
                };
            (
                audio_path.clone(),
                vec![audio_path],
                cue_path,
                preflight_error,
            )
        } else {
            // A native multi-FILE CUE opens through the unified album model.
            // Persist to a sidecar only when policy resolution selected that
            // sidecar as the authoritative CUE source. Do not apply this to
            // merged N-CUE albums: one synthetic sheet cannot replace several
            // independently-authored sidecars.
            let synthetic = surface.cue_album_synthetic_sheet.as_ref()?;
            let cue_paths: std::collections::BTreeSet<std::path::PathBuf> = synthetic
                .track_sources
                .iter()
                .map(|source| metadata_cue_surface_key(&source.cue_path))
                .collect();
            if cue_paths.len() != 1 || synthetic.audio_paths.len() < 2 {
                return None;
            }
            let cue_path = surface
                .cue_source
                .as_ref()?
                .sidecar_path()?
                .to_path_buf();
            let editor_track_paths: Vec<std::path::PathBuf> = synthetic
                .track_sources
                .iter()
                .map(|source| metadata_cue_surface_key(&source.audio_path))
                .collect();
            let preflight_error =
                match super::cue_parser::multi_file_cue_layout_for_cue_with_policy(
                    &cue_path,
                    crate::convert::pipeline::CueSidecarPolicy::SidecarOnly,
                ) {
                    Ok(Some(current_layout)) => {
                        let current_track_paths: Vec<std::path::PathBuf> = current_layout
                            .track_audio_paths
                            .iter()
                            .map(|path| metadata_cue_surface_key(path))
                            .collect();
                        (current_track_paths != editor_track_paths).then(|| {
                            format!(
                                "sidecar CUE '{}' changed after the metadata editor opened; image tags \
                                 were saved but the sidecar was left unchanged",
                                cue_path.display()
                            )
                        })
                    }
                    Ok(None) => Some(format!(
                        "sidecar CUE '{}' no longer describes the open native multi-FILE album; image \
                         tags were saved but the sidecar was left unchanged",
                        cue_path.display()
                    )),
                    Err(err) => Some(format!(
                        "sidecar CUE '{}' could not be revalidated before save: {}; image tags were \
                         saved but the sidecar was left unchanged",
                        cue_path.display(),
                        err
                    )),
                };
            (
                surface.paths.first()?.clone(),
                surface.paths.clone(),
                cue_path,
                preflight_error,
            )
        };
    let replacement_values = &surface
        .entries
        .iter()
        .find(|entry| entry.display_key.eq_ignore_ascii_case("CUESHEET"))?
        .per_file_values;
    let replacement_cuesheet = replacement_values.first()?.clone();
    if replacement_cuesheet.trim().is_empty() {
        if required_audio_paths.len() == 1 {
            return None;
        }
        preflight_error.get_or_insert_with(|| {
            "native multi-FILE CUE regeneration produced an empty sidecar replacement; image \
             tags were saved but the sidecar was left unchanged"
                .to_string()
        });
    }
    if replacement_values
        .iter()
        .any(|value| value != &replacement_cuesheet)
    {
        if required_audio_paths.len() == 1 {
            return None;
        }
        preflight_error.get_or_insert_with(|| {
            "native multi-FILE CUE regeneration diverged across member images; image tags \
             were saved but the sidecar was left unchanged"
                .to_string()
        });
    }
    let require_successful_image_save =
        metadata_editor_audio_tag_changes_required_for_sidecar_writeback(state);
    Some(CueSidecarWritebackPlan {
        audio_path,
        required_audio_paths,
        cue_path,
        replacement_cuesheet,
        require_successful_image_save,
        preflight_error,
    })
}

fn cue_sidecar_writeback_result_after_successful_image_save(
    plan: CueSidecarWritebackPlan,
    audio_results: &[crate::tui::app::MetadataEditorWriteResult],
) -> Option<crate::tui::app::MetadataEditorWriteResult> {
    let CueSidecarWritebackPlan {
        audio_path,
        required_audio_paths,
        cue_path,
        replacement_cuesheet,
        require_successful_image_save,
        preflight_error,
    } = plan;
    let all_required_images_saved = required_audio_paths.iter().all(|required| {
        audio_results.iter().any(|result| {
            result.path.as_path() == required.as_path()
                && matches!(
                    &result.outcome,
                    crate::tui::app::MetadataEditorWriteOutcome::Saved
                        | crate::tui::app::MetadataEditorWriteOutcome::SavedWithWarnings { .. }
                )
        })
    });
    if require_successful_image_save && !all_required_images_saved {
        return None;
    }

    let result = if let Some(reason) = preflight_error {
        crate::tui::app::MetadataEditorWriteResult::sidecar_cue_failed(
            audio_path,
            cue_path,
            reason,
        )
    } else {
        match super::cue_parser::rewrite_cue_sidecar_metadata_from_cuesheet(
            &cue_path,
            &replacement_cuesheet,
        ) {
            Ok(outcome) => crate::tui::app::MetadataEditorWriteResult::sidecar_cue_saved(
                audio_path,
                cue_path,
                matches!(
                    &outcome,
                    super::cue_parser::CueSidecarWritebackOutcome::Unchanged
                ),
                matches!(
                    &outcome,
                    super::cue_parser::CueSidecarWritebackOutcome::RewrittenUtf8Fallback { .. }
                ),
            ),
            Err(reason) => crate::tui::app::MetadataEditorWriteResult::sidecar_cue_failed(
                audio_path,
                cue_path,
                reason,
            ),
        }
    };
    Some(result)
}

fn plural(count: usize, singular: &str, plural: &str) -> String {
    if count == 1 {
        format!("1 {singular}")
    } else {
        format!("{count} {plural}")
    }
}

fn bluray_sidecar_save_status(
    outcome: &super::command::BluRaySidecarSaveAllOutcome,
    file_name: &str,
    remaining_dirty: usize,
) -> String {
    let mut parts = Vec::new();
    if outcome.saved_presentations == 0 {
        parts.push(format!("saved {}", plural(0, "presentation", "presentations")));
    } else {
        let action = if outcome.created_file { "created" } else { "updated" };
        parts.push(format!(
            "{action} {file_name}; saved {}",
            plural(outcome.saved_presentations, "presentation", "presentations")
        ));
    }

    if outcome.added_presentations > 0 || outcome.updated_presentations > 0 {
        parts.push(format!(
            "{} added, {} updated",
            outcome.added_presentations,
            outcome.updated_presentations
        ));
    }
    if outcome.skipped_clean_presentations > 0 {
        parts.push(format!("{} skipped clean", outcome.skipped_clean_presentations));
    }
    if outcome.missing_identity_presentations > 0 {
        parts.push(format!(
            "{} lacked sufficient identity data",
            outcome.missing_identity_presentations
        ));
    }
    if remaining_dirty > 0 {
        parts.push(format!("{} still unsaved", remaining_dirty));
    }
    format!("Blu-ray sidecar save: {}", parts.join("; "))
}

pub(super) fn reopen_metadata_editor_after_musicbrainz_population(
    app: &mut AppState,
    state: Box<super::app::MetadataEditorState>,
) {
    if state.has_multiple_presentations() {
        app.pending_metadata_editor = Some(state.clone());
        app.active_overlay = ActiveOverlay::Confirmation {
            message: "Apply MusicBrainz tags to all matching presentations?".to_string(),
            action: ConfirmAction::ApplyMbToAllPresentations(state),
        };
    } else {
        app.active_overlay = ActiveOverlay::MetadataEditor(state);
    }
}

fn metadata_editor_apply(
    app: &mut AppState,
    state: &mut Box<super::app::MetadataEditorState>,
    tx: &mpsc::Sender<AppMessage>,
) {
    state.close_after_successful_save = false;
    metadata_editor_save(app, state, tx);
    if state.phase != super::app::MetadataEditorPhase::Saving {
        state.close_after_successful_save = true;
    }
}

fn metadata_editor_ok(
    app: &mut AppState,
    state: &mut Box<super::app::MetadataEditorState>,
    tx: &mpsc::Sender<AppMessage>,
) {
    state.close_after_successful_save = true;
    if state.any_presentation_dirty() {
        metadata_editor_save(app, state, tx);
        if state.phase != super::app::MetadataEditorPhase::Saving && !state.any_presentation_dirty() {
            request_metadata_editor_close(app, state, tx);
        }
    } else {
        request_metadata_editor_close(app, state, tx);
    }
}

fn metadata_editor_switch_content_tab(
    app: &mut AppState,
    state: &mut Box<super::app::MetadataEditorState>,
    forward: bool,
    tx: &mpsc::Sender<AppMessage>,
) {
    let was_details = state.content_tab == crate::tui::app::ContentTab::Details;
    let changed = if forward {
        state.next_content_tab()
    } else {
        state.previous_content_tab()
    };
    if changed {
        if state.content_tab == crate::tui::app::ContentTab::Details {
            ensure_metadata_content_tab_loaded(state, crate::tui::app::ContentTab::Details, tx);
        } else if was_details {
            metadata_editor_cancel_details_probe(state);
        }
        if state.content_tab == crate::tui::app::ContentTab::Metadata {
            ensure_cursor_visible(state);
        }
        if let Some(status) = metadata_editor_apply_content_tab_progress(state) {
            app.set_status(status);
        } else {
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
            app.set_status(metadata_editor_status_for_content_tab(&**state));
        }
    }
}

fn metadata_editor_cycle_field_in_current_tab(
    app: &mut AppState,
    state: &mut Box<super::app::MetadataEditorState>,
    total_rows: usize,
    tx: &mpsc::Sender<AppMessage>,
) {
    match state.content_tab {
        crate::tui::app::ContentTab::Metadata => {
            if total_rows > 0 {
                state.cursor = (state.cursor + 1) % total_rows;
                ensure_cursor_visible(state);
            }
        }
        crate::tui::app::ContentTab::ReplayGain => {
            handle_metadata_replaygain_key(
                app,
                KeyEvent::new(KeyCode::Down, KeyModifiers::NONE),
                state,
                tx,
            );
        }
        crate::tui::app::ContentTab::Artwork => {
            handle_metadata_artwork_key(
                app,
                KeyEvent::new(KeyCode::Down, KeyModifiers::NONE),
                state,
                tx,
            );
        }
        crate::tui::app::ContentTab::Details => {
            scroll_metadata_read_only_tab(state, 1, metadata_editor_read_only_visible_rows());
        }
    }
}

fn request_metadata_editor_close(
    app: &mut AppState,
    state: &mut Box<super::app::MetadataEditorState>,
    _tx: &mpsc::Sender<AppMessage>,
) {
    if state.phase == super::app::MetadataEditorPhase::Saving {
        let requested = state.cancel_metadata_write();
        app.active_overlay = ActiveOverlay::MetadataEditor(state.clone());
        if requested {
            app.set_status("metadata editor: cancellation requested; current file will stop at the next safe point".to_string());
        } else {
            app.set_status("metadata editor: save in progress — waiting for completion".to_string());
        }
        return;
    }
    if state.artwork_write.is_some() {
        let requested = state.cancel_artwork_write();
        app.active_overlay = ActiveOverlay::MetadataEditor(state.clone());
        if requested {
            app.set_status("metadata editor: artwork write cancellation requested; current file will stop at the next safe point".to_string());
        } else {
            app.set_status("metadata editor: artwork write in progress — waiting for completion".to_string());
        }
        return;
    }
    if state.replaygain_scan.is_some() {
        app.active_overlay = ActiveOverlay::MetadataEditor(state.clone());
        app.set_status(
            "metadata editor: metadata file write in progress — wait for completion before closing"
                .to_string(),
        );
        return;
    }
    if state.model.tags_mb_in_flight {
        // The editor is now actually leaving its interactive surface (either
        // closing or entering dirty-close confirmation). Invalidate any direct
        // single-match verification so its delayed completion cannot reopen or
        // mutate this session. Blocked close attempts above deliberately leave
        // the operation intact because the editor remains active.
        super::event_loop::finish_metadata_editor_tags_mb_operation(app);
        state.model.tags_mb_in_flight = false;
    }
    metadata_editor_cancel_details_probe(state);
    if state.any_presentation_dirty() {
        app.pending_metadata_editor = Some(state.clone());
        app.active_overlay = ActiveOverlay::Confirmation {
            message: "Discard unsaved metadata changes? Y discards them; N/Esc returns to the editor.".to_string(),
            action: ConfirmAction::DiscardMetadataEditorChanges,
        };
        app.set_status("metadata editor: unsaved changes — confirm discard or press Esc/N to return".to_string());
    } else if state.has_browse_archive_staged_changes() {
        if let Some(context) = state.archive_edit_context.clone() {
            match record_staged_archive_metadata_write(
                app,
                &context.archive_path,
                &context.staging_dir,
                archive_metadata_context_baseline(&context),
                &[],
            ) {
                Ok(()) => {
                    app.browse.refresh_with_search(Some(_tx));
                    app.active_overlay = ActiveOverlay::None;
                    app.set_status("metadata editor: staged archive changes pending; save occurs when leaving archive".to_string());
                }
                Err(err) => {
                    app.active_overlay = ActiveOverlay::MetadataEditor(state.clone());
                    app.set_status(format!("metadata editor: staged archive changes are not crash-safe yet; recovery tracking failed: {err}"));
                }
            }
        } else {
            app.active_overlay = ActiveOverlay::None;
            app.set_status("metadata editor: archive changes had no staging context".to_string());
        }
    } else {
        cleanup_metadata_editor_archive_context(app, state);
        app.active_overlay = ActiveOverlay::None;
    }
}


fn handle_metadata_replaygain_key(
    app: &mut AppState,
    key: KeyEvent,
    state: &mut Box<super::app::MetadataEditorState>,
    tx: &mpsc::Sender<AppMessage>,
) {
    match key.code {
        KeyCode::Up | KeyCode::Char('k') => {
            state.move_replaygain_cursor(-1);
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::Down | KeyCode::Char('j') => {
            state.move_replaygain_cursor(1);
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::Home => {
            state.replaygain_cursor = 0;
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::End => {
            state.replaygain_cursor = crate::tui::metadata_view_models::replaygain_action_row_count(state)
                .saturating_sub(1);
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::Enter | KeyCode::Char(' ') | KeyCode::Char('*') => {
            app.set_status(
                "metadata editor: ReplayGain selection was removed; \
                 press s to scan all tracks or a for album scan",
            );
        }
        KeyCode::Char('s') | KeyCode::Char('S') => {
            metadata_editor_start_replaygain_scan(
                app,
                state,
                crate::tui::app::MetadataReplayGainScanMode::Track,
                tx,
            );
        }
        KeyCode::Char('a') | KeyCode::Char('A') => {
            metadata_editor_start_replaygain_scan(
                app,
                state,
                crate::tui::app::MetadataReplayGainScanMode::Album,
                tx,
            );
        }
        _ => {
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
    }
}

fn metadata_editor_start_replaygain_scan(
    app: &mut AppState,
    state: &mut Box<super::app::MetadataEditorState>,
    mode: crate::tui::app::MetadataReplayGainScanMode,
    tx: &mpsc::Sender<AppMessage>,
) {
    if state.read_only {
        app.set_status("metadata editor: read-only source; ReplayGain tags cannot be written");
        return;
    }
    if state.replaygain_scan.is_some() {
        app.set_status("metadata editor: ReplayGain scan already running");
        return;
    }
    let paths = match mode {
        crate::tui::app::MetadataReplayGainScanMode::Track
        | crate::tui::app::MetadataReplayGainScanMode::Album => state.active_surface().paths.clone(),
    };
    if paths.is_empty() {
        app.set_status("metadata editor: no files available for ReplayGain scan");
        return;
    }
    let prevent_clipping = match super::convert_actions::format_state_to_pipeline_settings(
        &app.convert.format,
    ) {
        Ok(settings) => settings.replay_gain.prevent_clipping,
        Err(error) => {
            app.set_status(format!(
                "metadata editor: cannot resolve ReplayGain policy from Output Options: {error}"
            ));
            return;
        }
    };
    let (session_id, generation) = state.begin_replaygain_scan(mode, paths.len());
    let tx = tx.clone();
    let worker_paths = paths.clone();
    let tool_paths = app.manager.config.tool_paths.clone();
    tokio::spawn(async move {
        let cmd = metadata_replaygain_tool_command(mode, prevent_clipping, &worker_paths);
        let cancel = tokio_util::sync::CancellationToken::new();
        let runner = crate::convert::pipeline::tool::RealToolRunner::new(tool_paths);
        let result = match crate::convert::pipeline::tool::ToolRunner::run(&runner, cmd, &cancel).await {
            Ok(_) => tokio::task::spawn_blocking({
                let worker_paths = worker_paths.clone();
                move || {
                    if mode == crate::tui::app::MetadataReplayGainScanMode::Track {
                        crate::convert::replaygain::remove_stale_album_tags(&worker_paths)
                            .map_err(|error| format!(
                                "ReplayGain track scan succeeded, but stale album-tag cleanup failed: {error}"
                            ))?;
                    }
                    super::probe::read_all_tags_merged_with_metadata(&worker_paths)
                        .map(|read| read.metadata)
                }
            })
            .await
            .unwrap_or_else(|err| Err(format!("ReplayGain tag post-processing task failed: {err}"))),
            Err(err) => Err(format!("loudgain failed: {err}")),
        };
        let _ = tx
            .send(AppMessage::MetadataEditorReplayGainComplete {
                session_id,
                generation,
                mode,
                paths: worker_paths,
                result,
            })
            .await;
    });
    app.set_status(format!(
        "metadata editor: scanning {} ReplayGain for {} file{}",
        mode.label(),
        paths.len(),
        if paths.len() == 1 { "" } else { "s" }
    ));
}


fn metadata_replaygain_tool_args(
    mode: crate::tui::app::MetadataReplayGainScanMode,
    prevent_clipping: bool,
    paths: &[std::path::PathBuf],
) -> Vec<String> {
    let grouping = if mode == crate::tui::app::MetadataReplayGainScanMode::Album {
        crate::convert::replaygain::LoudgainGrouping::Album
    } else {
        crate::convert::replaygain::LoudgainGrouping::Track
    };
    crate::convert::replaygain::loudgain_args(grouping, prevent_clipping, paths)
}

fn metadata_replaygain_tool_command(
    mode: crate::tui::app::MetadataReplayGainScanMode,
    prevent_clipping: bool,
    paths: &[std::path::PathBuf],
) -> crate::convert::pipeline::tool::ToolCommand {
    crate::convert::pipeline::tool::ToolCommand {
        environment_policy: tonepoet_pipeline::CommandEnvironmentPolicy::InheritAndSet,
        binary: crate::convert::pipeline::tool::ToolBinary::Loudgain,
        args: metadata_replaygain_tool_args(mode, prevent_clipping, paths),
        secret_args: Vec::new(),
        cwd: None,
        env: Vec::new(),
        timeout: std::time::Duration::from_secs(600),
    }
}

fn handle_metadata_artwork_key(
    app: &mut AppState,
    key: KeyEvent,
    state: &mut Box<super::app::MetadataEditorState>,
    tx: &mpsc::Sender<AppMessage>,
) {
    match key.code {
        KeyCode::Up | KeyCode::Char('k') => {
            state.move_artwork_cursor(-1);
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::Down | KeyCode::Char('j') => {
            state.move_artwork_cursor(1);
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::Home => {
            state.set_artwork_cursor(0);
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::End => {
            let last = crate::tui::metadata_view_models::artwork_action_row_count(state)
                .saturating_sub(1);
            state.set_artwork_cursor(last);
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
        KeyCode::Enter | KeyCode::Char('+') => {
            if state.read_only {
                app.set_status("metadata editor: read-only source; artwork cannot be written");
            } else if state.artwork_write.is_some() {
                app.set_status("metadata editor: artwork write already running");
            } else {
                metadata_editor_open_artwork_picker(app, state);
                app.set_status("metadata editor: choose artwork image");
            }
        }
        KeyCode::Delete | KeyCode::Char('d') | KeyCode::Char('D') => {
            metadata_editor_dispatch_artwork_remove(app, state, tx);
        }
        _ => {
            clamp_metadata_read_only_scroll(state, metadata_editor_read_only_visible_rows());
        }
    }
}

fn metadata_editor_current_artwork_type(
    state: &super::app::MetadataEditorState,
) -> Option<lofty::picture::PictureType> {
    crate::tui::metadata_view_models::build_artwork_view_model(state)
        .rows
        .get(state.artwork_cursor)
        .map(|row| row.picture_type.clone())
}

fn metadata_editor_open_artwork_picker(app: &mut AppState, state: &mut Box<super::app::MetadataEditorState>) {
    let picture_type = metadata_editor_current_artwork_type(state)
        .unwrap_or(lofty::picture::PictureType::CoverFront);
    let dir = app
        .last_artwork_picker_dir
        .clone()
        .filter(|path| path.is_dir())
        .or_else(|| {
            state
                .active_surface()
                .paths
                .first()
                .and_then(|path| path.parent().map(|parent| parent.to_path_buf()))
        })
        .or_else(|| std::env::current_dir().ok())
        .unwrap_or_else(|| std::path::PathBuf::from("."));
    state.pending_artwork_type = None;
    let picker = tui_file_picker::FilePickerState::new(tui_file_picker::FilePickerConfig {
        start_dir: dir,
        filter: tui_file_picker::FilePickerFilter::Images,
        title: "Select artwork image".to_string(),
        theme: file_picker_theme_from_theme(&app.theme),
        selection_mode: tui_file_picker::FilePickerSelectionMode::Files,
        operation_policy: artwork_file_picker_policy(),
        ..tui_file_picker::FilePickerConfig::default()
    });
    state.file_picker = Some(crate::tui::app::MetadataFilePickerState::new(
        crate::tui::app::FilePickerPurpose::SelectArtwork { picture_type },
        picker,
    ));
}


fn artwork_file_picker_policy() -> tui_file_picker::FileOperationPolicy {
    tui_file_picker::FileOperationPolicy::default()
}

