        let (control_tx, control_rx) = std::sync::mpsc::channel();
        control_tx.send(crate::tui::app::FileTaskControl::Pause).expect("pause root scan");
        control_tx.send(crate::tui::app::FileTaskControl::Resume).expect("resume root scan");
