    fn dvd_audio_presentation(
        group_nr: u8,
        label: &str,
        codec: Option<&str>,
        sample_rate: Option<u32>,
        bit_depth: Option<u32>,
        channels: Option<u8>,
        channel_layout: Option<&str>,
    ) -> crate::disc::model::DiscPresentation {
        crate::disc::model::DiscPresentation {
            id: crate::disc::model::PresentationId::DvdAudioGroup(group_nr),
            label: label.to_string(),
            format: crate::disc::model::AudioPresentationFormat {
                codec: codec.map(str::to_string),
                sample_rate,
                bit_depth,
                channels,
                channel_layout: channel_layout.map(str::to_string),
                lossless: true,
                provenance: crate::disc::model::FormatProvenance::AobProbe,
            },
            tracks: Vec::new(),
            total_duration_secs: 0.0,
            album_title: None,
            album_artist: None,
            genre: None,
            year: None,
        }
    }

    fn bluray_presentation(
        playlist_number: u32,
        audio_pid: u16,
        audio_stream_index: u8,
        album_title: &str,
        durations: &[f64],
    ) -> crate::disc::model::DiscPresentation {
        crate::disc::model::DiscPresentation {
            id: crate::disc::model::PresentationId::try_blu_ray_title(
                playlist_number,
                audio_pid,
                audio_stream_index,
                1,
            )
            .expect("valid Blu-ray presentation identity"),
            label: format!("Playlist {playlist_number:05} stream {}", audio_stream_index + 1),
            format: crate::disc::model::AudioPresentationFormat {
                codec: Some("DTS-HD MA".to_string()),
                sample_rate: Some(48_000),
                bit_depth: Some(24),
                channels: Some(2),
                channel_layout: Some("Stereo".to_string()),
                lossless: true,
                provenance: crate::disc::model::FormatProvenance::Unknown,
            },
            tracks: durations
                .iter()
                .enumerate()
                .map(|(idx, duration)| crate::disc::model::DiscTrack {
                    number: u32::try_from(idx + 1).unwrap(),
                    title: None,
                    performer: None,
                    duration_secs: Some(*duration),
                    format_note: None,
                })
                .collect(),
            total_duration_secs: durations.iter().sum(),
            album_title: Some(album_title.to_string()),
            album_artist: Some("Mapped Artist".to_string()),
            genre: Some("Classical".to_string()),
            year: Some("1972".to_string()),
        }
    }

    #[test]
    fn dvda_tab_label_uses_disc_presentation_label_with_group_prefix() {
        let presentation = dvd_audio_presentation(
            1,
            "MLP 96kHz/24-bit 5.1",
            Some("MLP"),
            Some(96_000),
            Some(24),
            Some(6),
            Some("5.1"),
        );

        assert_eq!(
            dvda_presentation_tab_label(&presentation, 1),
            "Group 1: MLP 96kHz/24-bit 5.1"
        );
    }

    #[test]
    fn dvda_tab_label_does_not_duplicate_existing_group_prefix() {
        let presentation = dvd_audio_presentation(
            3,
            "Group 3: LPCM 96kHz/24-bit Stereo",
            Some("LPCM"),
            Some(96_000),
            Some(24),
            Some(2),
            Some("Stereo"),
        );

        assert_eq!(
            dvda_presentation_tab_label(&presentation, 3),
            "Group 3: LPCM 96kHz/24-bit Stereo"
        );
    }

    #[test]
    fn dvda_tab_label_uses_album_title_before_group_identity() {
        let mut presentation = dvd_audio_presentation(
            2,
            "MLP 96kHz/24-bit 5.1",
            Some("MLP"),
            Some(96_000),
            Some(24),
            Some(6),
            Some("5.1"),
        );
        presentation.album_title = Some("Live at the Fillmore East".to_string());

        assert_eq!(
            dvda_presentation_tab_label(&presentation, 2),
            "Live at the Fillmore East (MLP 96kHz/24-bit 5.1)"
        );
    }

    #[test]
    fn dvda_tab_label_falls_back_to_structured_format_fields() {
        let presentation = dvd_audio_presentation(
            2,
            "",
            Some("MLP"),
            Some(88_200),
            Some(24),
            Some(2),
            None,
        );

        assert_eq!(
            dvda_presentation_tab_label(&presentation, 2),
            "Group 2: MLP 88.2kHz/24-bit Stereo"
        );
    }

    #[test]
    fn bluray_editor_state_initialization_builds_one_state_per_audio_stream_without_sidecar_values() {
        let source = std::path::PathBuf::from("/fixtures/Concert.iso");
        let contents = crate::disc::model::DiscContents {
            format: crate::disc::model::DiscFormat::BluRay,
            label: "Concert".to_string(),
            source_path: source.clone(),
            presentations: vec![
                bluray_presentation(12, 0x1100, 0, "Mapped Stream 1", &[90.0, 91.0]),
                bluray_presentation(12, 0x1101, 1, "Mapped Stream 2", &[92.0, 93.0]),
            ],
            suppressed: Vec::new(),
            copy_protection: crate::disc::model::CopyProtectionSummary {
                description: "none".to_string(),
            },
            diagnostics: Vec::new(),
            album_title: None,
            album_artist: None,
            genre: None,
            year: None,
        };

        let states: Vec<_> = contents
            .presentations
            .iter()
            .enumerate()
            .filter_map(|(idx, presentation)| {
                matches!(presentation.id, crate::disc::model::PresentationId::BluRayTitle { .. })
                    .then(|| build_bluray_editor_state(&source, &contents, idx).unwrap())
            })
            .collect();

        assert_eq!(states.len(), 2);
        assert_eq!(states[0].0.active_surface().bluray_playlist_number, Some(12));
        assert_eq!(states[0].0.active_surface().bluray_audio_pid, Some(0x1100));
        assert_eq!(states[0].0.active_surface().bluray_audio_stream_index, Some(0));
        assert_eq!(states[0].0.active_surface().bluray_chapter_durations, Some(vec![90.0, 91.0]));
        assert_eq!(states[1].0.active_surface().bluray_audio_pid, Some(0x1101));
        assert_eq!(states[1].0.active_surface().bluray_audio_stream_index, Some(1));
        assert_eq!(states[1].0.active_surface().bluray_chapter_durations, Some(vec![92.0, 93.0]));
        assert_eq!(states[0].1, "Mapped Stream 1 (DTS-HD MA 48kHz/24-bit Stereo)");
        assert_eq!(states[1].1, "Mapped Stream 2 (DTS-HD MA 48kHz/24-bit Stereo)");
        assert!(states.iter().all(|(state, _, n_tracks)| {
            *n_tracks == 2
                && state.active_surface().paths == vec![source.clone(), source.clone()]
                && state.active_surface().entries.iter().any(|entry| entry.display_key == "TITLE")
                && !state.active_surface().entries.iter().any(|entry| entry.display_key == "MOOD")
        }));
    }

    fn entry(key: &str, item_key: ItemKey, vals: &[&str], origs: &[&str]) -> TagEntry {
        let v: Vec<String> = vals.iter().map(|s| s.to_string()).collect();
        let o: Vec<String> = origs.iter().map(|s| s.to_string()).collect();
        let all_same = v.windows(2).all(|w| w[0] == w[1]);
        let value = if v.len() > 1 && !all_same {
            "<multiple values>".to_string()
        } else {
            v.first().cloned().unwrap_or_default()
        };
        let original = o.first().cloned().unwrap_or_default();
        TagEntry {
            row_scope: crate::tui::probe::RowScope::File,
            display_key: key.to_string(),
            item_key,
            value,
            original,
            is_binary: key.eq_ignore_ascii_case("CUESHEET"),
            is_mixed: v.len() > 1 && !all_same,
            has_multiple_stored_values: false,
            per_file_stored_value_counts: Vec::new(),
            per_file_values: v,
            per_file_originals: o,
            mb_proposed_value: None,
            mb_proposed_per_file: None,
        }
    }

    #[test]
    fn inline_edit_warns_before_collapsing_multiple_stored_values() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut multi = entry(
            "ARTIST",
            ItemKey::TrackArtist,
            &["Alpha; Beta"],
            &["Alpha; Beta"],
        );
        multi.has_multiple_stored_values = true;
        multi.per_file_stored_value_counts = vec![2];
        let mut state = MetadataEditorState::for_files(
            vec![std::path::PathBuf::from("/tmp/a.flac")],
            vec![multi],
            vec!["a".to_string()],
            crate::tui::app::MetadataTechnicalDetails::default(),
        );
        state.cursor = 0;
        state.phase = MetadataEditorPhase::InlineEdit;
        state.edit_input = Some(crate::tui::text_input::TextInputState::new(
            "Solo Artist".to_string(),
        ));

        assert!(metadata_editor_commit_inline_edit(&mut app, &mut state));
        assert_eq!(state.active_surface().entries[0].value, "Solo Artist");
        assert_eq!(
            app.status_message.as_ref().map(|(message, _)| message.as_str()),
            Some("metadata editor: editing ARTIST collapsed multiple stored values into one value")
        );
    }

    #[test]
    fn detail_edit_warns_only_for_the_multi_value_file_slot() {
        let make_state = || {
            let mut artist = entry(
                "ARTIST",
                ItemKey::TrackArtist,
                &["Alpha; Beta", "Gamma"],
                &["Alpha; Beta", "Gamma"],
            );
            artist.has_multiple_stored_values = true;
            artist.per_file_stored_value_counts = vec![2, 1];
            artist.original = artist.value.clone();
            let mut state = MetadataEditorState::for_files(
                vec![
                    std::path::PathBuf::from("/tmp/a.flac"),
                    std::path::PathBuf::from("/tmp/b.flac"),
                ],
                vec![artist],
                vec!["a".to_string(), "b".to_string()],
                crate::tui::app::MetadataTechnicalDetails::default(),
            );
            state.phase = MetadataEditorPhase::DetailEdit;
            state.detail_field_idx = 0;
            state
        };

        let untouched = make_state();
        assert_eq!(
            untouched.active_surface().entries[0].per_file_stored_value_counts,
            vec![2, 1]
        );
        assert!(!crate::tui::probe::metadata_editor_has_changes(&untouched));
        let untouched_snapshot = metadata_editor_entries_snapshot_for_save(&untouched);
        assert_eq!(untouched_snapshot[0].2, untouched_snapshot[0].3);

        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut multi_state = make_state();
        multi_state.detail_cursor = 0;
        multi_state.detail_edit = Some(crate::tui::text_input::TextInputState::new(
            "Solo".to_string(),
        ));
        assert!(metadata_editor_commit_detail_edit(&mut app, &mut multi_state));
        assert_eq!(
            app.status_message.as_ref().map(|(message, _)| message.as_str()),
            Some(
                "metadata editor: editing ARTIST for this file collapsed multiple stored values into one value"
            )
        );
        assert_eq!(
            multi_state.active_surface().entries[0].per_file_stored_value_counts,
            vec![2, 1],
            "editing must not erase the source-cardinality provenance"
        );

        let mut scalar_app = AppState::new_for_test(TonepoetConfig::default());
        let mut scalar_state = make_state();
        scalar_state.detail_cursor = 1;
        scalar_state.detail_edit = Some(crate::tui::text_input::TextInputState::new(
            "Delta".to_string(),
        ));
        assert!(metadata_editor_commit_detail_edit(
            &mut scalar_app,
            &mut scalar_state,
        ));
        assert!(
            scalar_app
                .status_message
                .as_ref()
                .map(|(message, _)| !message.contains("collapsed multiple stored values"))
                .unwrap_or(true),
            "the scalar carrier must not receive a false collapse warning"
        );

        let mut revert_app = AppState::new_for_test(TonepoetConfig::default());
        let mut revert_state = make_state();
        revert_state.active_surface_mut().entries[0].per_file_values[0] = "Solo".to_string();
        metadata_editor_recompute_entry_display(&mut revert_state.active_surface_mut().entries[0]);
        revert_state.detail_cursor = 0;
        revert_state.detail_edit = Some(crate::tui::text_input::TextInputState::new(
            "Alpha; Beta".to_string(),
        ));
        assert!(metadata_editor_commit_detail_edit(
            &mut revert_app,
            &mut revert_state,
        ));
        assert!(
            revert_app
                .status_message
                .as_ref()
                .map(|(message, _)| !message.contains("collapsed multiple stored values"))
                .unwrap_or(true),
            "restoring the original scalar representation performs no write and must not warn"
        );
        assert!(!crate::tui::probe::metadata_editor_has_changes(&revert_state));
    }

    #[test]
    fn metadata_row_use_mb_pill_preserves_cardinality_warning() {
        let mut artist = entry(
            "ARTIST",
            ItemKey::TrackArtist,
            &["Alpha; Beta"],
            &["Alpha; Beta"],
        );
        artist.has_multiple_stored_values = true;
        artist.per_file_stored_value_counts = vec![2];
        artist.mb_proposed_value = Some("New Artist".to_string());
        artist.mb_proposed_per_file = Some(vec!["New Artist".to_string()]);

        let mut state = MetadataEditorState::for_files(
            vec![std::path::PathBuf::from("/tmp/a.flac")],
            vec![artist],
            vec!["a".to_string()],
            crate::tui::app::MetadataTechnicalDetails::default(),
        );
        state.phase = MetadataEditorPhase::Editing;

        let area = ratatui::layout::Rect::new(0, 0, 100, 40);
        let layout = crate::tui::draw_overlays::metadata_editor_layout_for_area(area);
        let button_rect = ratatui::layout::Rect::new(
            layout.content_area.x.saturating_add(2),
            layout.content_area.y,
            8,
            1,
        );
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.button_map.record_button(
            crate::tui::button_map::TuiButton::MetadataEntryRevert(0),
            button_rect,
        );
        app.active_overlay = ActiveOverlay::MetadataEditor(Box::new(state));
        let (tx, _rx) = mpsc::channel(1);

        handle_metadata_editor_mouse_in_area(
            &mut app,
            crossterm::event::MouseEvent {
                kind: crossterm::event::MouseEventKind::Down(
                    crossterm::event::MouseButton::Left,
                ),
                column: button_rect.x,
                row: button_rect.y,
                modifiers: crossterm::event::KeyModifiers::NONE,
            },
            &tx,
            area,
        );

        let status = app
            .status_message
            .as_ref()
            .map(|(message, _)| message.as_str())
            .unwrap_or("");
        assert!(status.contains("MusicBrainz values applied to ARTIST"));
        assert!(status.contains("warning: 1 carrier"));
    }

