    #[test]
    fn create_row_click_is_focus_preserving_for_the_active_create_editor() {
        // Audit MEDIUM: clicking the inline create row used to blur-commit
        // and create "New File" instantly (no Create arm in the matcher).
        use crate::tui::app::{BrowseCreateKind, BrowseInlineEditState, BrowseInlineEditTarget};
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let dir = app.browse.current_dir.clone();
        app.browse_inline_edit = Some(BrowseInlineEditState {
            target: BrowseInlineEditTarget::Create {
                dir: dir.clone(),
                kind: BrowseCreateKind::File,
            },
            input: crate::tui::text_input::TextInputState::new_selected(
                "untitled.txt".to_string(),
            ),
        });

        assert!(
            active_inline_edit_matches_button(
                &app,
                Some(&crate::tui::button_map::TuiButton::BrowseCreateRow)
            ),
            "a click on the create row must preserve the editor"
        );
        assert!(
            !active_inline_edit_matches_button(
                &app,
                Some(&crate::tui::button_map::TuiButton::BrowseEntry(0))
            ),
            "clicks elsewhere still blur-commit"
        );

        // A stale create editor for a DIFFERENT directory is not preserved.
        app.browse_inline_edit = Some(BrowseInlineEditState {
            target: BrowseInlineEditTarget::Create {
                dir: dir.join("elsewhere"),
                kind: BrowseCreateKind::File,
            },
            input: crate::tui::text_input::TextInputState::new_selected(
                "untitled.txt".to_string(),
            ),
        });
        assert!(!active_inline_edit_matches_button(
            &app,
            Some(&crate::tui::button_map::TuiButton::BrowseCreateRow)
        ));
    }

    #[test]
    fn wheel_scroll_never_retargets_an_inflight_detail_edit() {
        // Audit H3: an unguarded wheel notch moved detail_cursor under an
        // open inline edit, so Enter committed the typed text to a
        // DIFFERENT track.
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut state = MetadataEditorState::for_files(
            vec![
                std::path::PathBuf::from("/tmp/a.flac"),
                std::path::PathBuf::from("/tmp/b.flac"),
            ],
            vec![entry(
                "TITLE",
                ItemKey::TrackTitle,
                &["One", "Two"],
                &["One", "Two"],
            )],
            vec!["a".to_string(), "b".to_string()],
            crate::tui::app::MetadataTechnicalDetails::default(),
        );
        state.phase = MetadataEditorPhase::DetailEdit;
        state.detail_field_idx = 0;
        state.detail_cursor = 1;
        state.detail_edit = Some(crate::tui::text_input::TextInputState::new(
            "typed".to_string(),
        ));
        app.active_overlay = ActiveOverlay::MetadataEditor(Box::new(state));
        let (tx, _rx) = mpsc::channel(4);

        // ScrollUp specifically: with detail_cursor = 1, an UNGUARDED arm
        // moves to 0 (ScrollDown at the last entry is refused by the bounds
        // check even without the guard, so it cannot detect a regression).
        handle_metadata_editor_mouse(
            &mut app,
            crossterm::event::MouseEvent {
                kind: crossterm::event::MouseEventKind::ScrollUp,
                column: 5,
                row: 5,
                modifiers: KeyModifiers::NONE,
            },
            &tx,
        );

        let ActiveOverlay::MetadataEditor(state) = &app.active_overlay else {
            panic!("editor must remain open");
        };
        assert_eq!(
            state.detail_cursor, 1,
            "a wheel notch must not move an in-flight edit's commit target"
        );
        assert_eq!(
            state.detail_edit.as_ref().map(|input| input.text.as_str()),
            Some("typed"),
            "the in-flight edit buffer must survive"
        );
    }

