    #[test]
    fn import_cue_refuses_while_the_metadata_editor_is_open() {
        // Audit H4: ImportCue replaced the editor with a GnudbReview that
        // carries no editor session, destroying every unsaved edit.
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let state =
            single_image_state(vec![entry("TITLE", ItemKey::TrackTitle, &["One"], &["Orig"])]);
        app.active_overlay = ActiveOverlay::MetadataEditor(Box::new(state));
        let (tx, _rx) = mpsc::channel(4);

        super::super::command::execute_command(
            &mut app,
            super::super::command::Command::ImportCue,
            &tx,
        );

        let ActiveOverlay::MetadataEditor(state) = &app.active_overlay else {
            panic!("the editor session must survive an import-cue attempt");
        };
        assert!(
            state.active_surface().dirty,
            "unsaved edits must be preserved"
        );
        assert!(
            app.status_message
                .as_ref()
                .is_some_and(|(message, _)| message.starts_with("import-cue:")),
            "the refusal must be visible"
        );
    }

    #[test]
    fn import_cue_refuses_over_a_parked_editor_session() {
        // Typing `:` inside the editor PARKS the session and clears the
        // overlay before the command executes — the overlay-only guard let
        // this route install a review that orphaned the parked dirty
        // session. The guard must refuse on pending_metadata_editor too.
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let state =
            single_image_state(vec![entry("TITLE", ItemKey::TrackTitle, &["One"], &["Orig"])]);
        app.pending_metadata_editor = Some(Box::new(state));
        app.active_overlay = ActiveOverlay::None; // command-input Enter shape
        let (tx, _rx) = mpsc::channel(4);

        super::super::command::execute_command(
            &mut app,
            super::super::command::Command::ImportCue,
            &tx,
        );

        assert!(
            matches!(app.active_overlay, ActiveOverlay::None),
            "no review may be installed over a parked session"
        );
        let parked = app
            .pending_metadata_editor
            .as_ref()
            .expect("the parked session must survive");
        assert!(parked.active_surface().dirty, "unsaved edits preserved");
        assert!(
            app.status_message
                .as_ref()
                .is_some_and(|(message, _)| message.starts_with("import-cue:")),
        );
    }

    #[test]
    fn import_cue_refuses_over_a_parked_cue_preview() {
        // Same shape for the OTHER parkable session type: the editable
        // cuesheet buffer parks into pending_cue_preview when `:` opens the
        // command input; installing the review would strand it identically.
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.pending_cue_preview = Some(Box::new(crate::tui::app::CuePreviewState::new(
            "FILE \"a.flac\" WAVE\n".to_string(),
            std::path::PathBuf::from("/tmp/a.cue"),
            "edited".to_string(),
        )));
        app.active_overlay = ActiveOverlay::None;
        let (tx, _rx) = mpsc::channel(4);

        super::super::command::execute_command(
            &mut app,
            super::super::command::Command::ImportCue,
            &tx,
        );

        assert!(
            matches!(app.active_overlay, ActiveOverlay::None),
            "no review may be installed over a parked cue-preview session"
        );
        assert!(
            app.pending_cue_preview.is_some(),
            "the parked cue buffer must survive"
        );
        assert!(app
            .status_message
            .as_ref()
            .is_some_and(|(message, _)| message.starts_with("import-cue:")));
    }

    #[test]
    fn review_click_commit_lands_on_the_row_the_edit_was_opened_on() {
        // Audit E-finding: a row click moved the review cursor under an open
        // inline edit, so Enter wrote the buffer to the NEW row. The click
        // path now commits to the pre-move row via this helper.
        let entry = super::super::gnudb::GnudbEntry {
            disc_id: "x".to_string(),
            artist: "Artist".to_string(),
            album: "Old Album".to_string(),
            year: "1971".to_string(),
            genre: "Rock".to_string(),
            tracks: vec!["T1".to_string(), "T2".to_string()],
        };
        let mut state = super::super::gnudb::build_review_state(
            &entry,
            vec![
                std::path::PathBuf::from("/a.flac"),
                std::path::PathBuf::from("/b.flac"),
            ],
        );
        // Row 0 is AlbumField("Album"); row 4 is track 1's Title.
        state.cursor = 0;
        state.edit_input = Some(crate::tui::text_input::TextInputState::new(
            "New Album".to_string(),
        ));

        // Drive the real reducer against an injected terminal area. The
        // test must not depend on whether the host has a TTY or on the
        // production 80x24 fallback.
        let area: (u16, u16) = (100, 40);
        let popup_w = ((area.0 as usize) * 85 / 100)
            .max(50)
            .min(area.0 as usize - 2) as u16;
        let popup_h = ((area.1 as usize) * 85 / 100)
            .max(14)
            .min(area.1 as usize - 2) as u16;
        let popup_x = (area.0.saturating_sub(popup_w)) / 2;
        let popup_y = (area.1.saturating_sub(popup_h)) / 2;
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.active_overlay = ActiveOverlay::GnudbReview(Box::new(state));
        let (tx, _rx) = mpsc::channel(4);
        handle_generic_overlay_mouse_in_area(
            &mut app,
            crossterm::event::MouseEvent {
                kind: crossterm::event::MouseEventKind::Down(
                    crossterm::event::MouseButton::Left,
                ),
                column: popup_x + 2,
                row: popup_y + 1 + 4,
                modifiers: KeyModifiers::NONE,
            },
            &tx,
            area,
        );

        let ActiveOverlay::GnudbReview(state) = &app.active_overlay else {
            panic!("review must remain open");
        };
        assert_eq!(
            state.pages[0].album, "New Album",
            "the buffer must land on the row the edit was opened on"
        );
        assert!(state.edit_input.is_none(), "single click commits, not reseeds");
        assert_eq!(state.cursor, 4, "the cursor moves to the clicked row");
        assert_eq!(
            state.pages[0].tracks[0].title, "T1",
            "the newly clicked row must be untouched"
        );
    }

    #[test]
    fn review_disc_pill_commits_edit_before_switching_pages() {
        let entry = super::super::gnudb::GnudbEntry {
            disc_id: "x".to_string(),
            artist: "Artist".to_string(),
            album: "Old Album".to_string(),
            year: "1971".to_string(),
            genre: "Rock".to_string(),
            tracks: vec!["T1".to_string()],
        };
        let mut state = super::super::gnudb::build_review_state(
            &entry,
            vec![std::path::PathBuf::from("/disc1.flac")],
        );
        state.pages[0].label = "disc 01".to_string();
        let mut second = state.pages[0].clone();
        second.label = "disc 02".to_string();
        second.album = "Second Album".to_string();
        state.pages.push(second);
        state.cursor = 0;
        state.edit_input = Some(crate::tui::text_input::TextInputState::new(
            "Committed Album".to_string(),
        ));

        let area: (u16, u16) = (100, 40);
        let popup_w = ((area.0 as usize) * 85 / 100)
            .max(50)
            .min(area.0 as usize - 2) as u16;
        let popup_h = ((area.1 as usize) * 85 / 100)
            .max(14)
            .min(area.1 as usize - 2) as u16;
        let popup_x = (area.0.saturating_sub(popup_w)) / 2;
        let popup_y = (area.1.saturating_sub(popup_h)) / 2;
        let inner_x = popup_x + 1;
        // Leading two spaces, first nine-column pill, one-column gap,
        // then the interior of the second " disc 02 " pill.
        let second_pill_x = inner_x + 13;

        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.active_overlay = ActiveOverlay::GnudbReview(Box::new(state));
        let (tx, _rx) = mpsc::channel(4);
        handle_generic_overlay_mouse_in_area(
            &mut app,
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: second_pill_x,
                row: popup_y + 1,
                modifiers: KeyModifiers::NONE,
            },
            &tx,
            area,
        );

        let ActiveOverlay::GnudbReview(state) = &app.active_overlay else {
            panic!("review must remain open");
        };
        assert_eq!(state.pages[0].album, "Committed Album");
        assert_eq!(state.pages[1].album, "Second Album");
        assert_eq!(state.active_page, 1);
        assert_eq!(state.cursor, 0);
        assert!(state.edit_input.is_none());
    }

