    #[test]
    fn embedded_cuesheet_delete_first_invocation_opens_confirmation_without_staging() {
        let temp = tempfile::tempdir().expect("tempdir");
        let image = temp.path().join("side_a.flac");
        std::fs::write(&image, b"placeholder").expect("image");
        let stale_embedded = fixture_cue("side_a", "Album", "Embedded", 2);
        let mut state = crate::tui::app::MetadataEditorState::for_files(
            vec![image.clone()],
            vec![cuesheet_tag_entry(&stale_embedded, &stale_embedded)],
            vec!["01".to_string(), "02".to_string()],
            crate::tui::app::MetadataTechnicalDetails::default(),
        );
        state.active_surface_mut().embedded_cuesheet_present = true;

        let mut app = AppState::new_for_test(crate::config::TonepoetConfig::default());
        open_embedded_cuesheet_delete_confirmation(&mut app, Box::new(state));

        match &app.active_overlay {
            ActiveOverlay::Confirmation { message, action } => {
                assert!(
                    message.contains("Delete the embedded CUESHEET tag"),
                    "unexpected confirmation message: {message}"
                );
                assert!(
                    message.contains(&image.display().to_string()),
                    "confirmation should identify the active file: {message}"
                );
                assert!(matches!(action, ConfirmAction::DeleteEmbeddedCueSheet { path } if path == &image));
            }
            other => panic!("expected delete confirmation, got {other:?}"),
        }

        let parked = app.pending_metadata_editor.as_ref().expect("parked editor");
        assert!(!parked.active_surface().pending_embedded_cuesheet_delete);
        assert!(!parked.active_surface().dirty, "confirmation prompt must not stage writes");
    }

    #[test]
    fn embedded_cuesheet_delete_decline_restores_editor_without_staging_or_touching_sidecar() {
        let temp = tempfile::tempdir().expect("tempdir");
        let image = temp.path().join("side_a.flac");
        std::fs::write(&image, b"placeholder").expect("image");
        let stale_embedded = fixture_cue("side_a", "Album", "Embedded", 2);
        let sidecar = fixture_cue("side_a", "Album", "Sidecar", 3);
        let sidecar_path = temp.path().join("side_a.cue");
        std::fs::write(&sidecar_path, &sidecar).expect("sidecar");
        let mut state = crate::tui::app::MetadataEditorState::for_files(
            vec![image.clone()],
            vec![cuesheet_tag_entry(&stale_embedded, &stale_embedded)],
            vec!["01".to_string(), "02".to_string()],
            crate::tui::app::MetadataTechnicalDetails::default(),
        );
        state.active_surface_mut().embedded_cuesheet_present = true;

        let mut app = AppState::new_for_test(crate::config::TonepoetConfig::default());
        open_embedded_cuesheet_delete_confirmation(&mut app, Box::new(state));
        let action = match &app.active_overlay {
            ActiveOverlay::Confirmation { action, .. } => action.clone(),
            other => panic!("expected delete confirmation, got {other:?}"),
        };

        cancel_confirm_action(&mut app, Some(&action));

        let state = match &app.active_overlay {
            ActiveOverlay::MetadataEditor(state) => state,
            other => panic!("expected restored metadata editor, got {other:?}"),
        };
        let surface = state.active_surface();
        assert!(surface.embedded_cuesheet_present);
        assert!(!surface.pending_embedded_cuesheet_delete);
        assert!(!surface.dirty, "decline must not create pending writes");
        let cue = surface
            .entries
            .iter()
            .find(|entry| entry.display_key.eq_ignore_ascii_case("CUESHEET"))
            .expect("embedded CUESHEET row");
        assert_eq!(cue.per_file_values.first().map(String::as_str), Some(stale_embedded.as_str()));
        assert_eq!(std::fs::read_to_string(&sidecar_path).expect("sidecar after cancel"), sidecar);
    }

    #[test]
    fn embedded_cuesheet_delete_confirm_stages_tombstone_and_preserves_sidecar_file() {
        let temp = tempfile::tempdir().expect("tempdir");
        let image = temp.path().join("side_a.flac");
        std::fs::write(&image, b"placeholder").expect("image");
        let stale_embedded = fixture_cue("side_a", "Album", "Embedded", 2);
        let sidecar = fixture_cue("side_a", "Album", "Sidecar", 3);
        let sidecar_path = temp.path().join("side_a.cue");
        std::fs::write(&sidecar_path, &sidecar).expect("sidecar");
        let mut state = crate::tui::app::MetadataEditorState::for_files(
            vec![image.clone()],
            vec![
                cuesheet_tag_entry(&stale_embedded, &stale_embedded),
                title_tag_entry(vec!["Embedded Track 1", "Embedded Track 2"]),
            ],
            vec!["01".to_string(), "02".to_string()],
            crate::tui::app::MetadataTechnicalDetails::default(),
        );
        state.active_surface_mut().embedded_cuesheet_present = true;

        let mut app = AppState::new_for_test(crate::config::TonepoetConfig::default());
        open_embedded_cuesheet_delete_confirmation(&mut app, Box::new(state));
        let action = match &app.active_overlay {
            ActiveOverlay::Confirmation { action, .. } => action.clone(),
            other => panic!("expected delete confirmation, got {other:?}"),
        };
        let (tx, _rx) = mpsc::channel(8);
        app.active_overlay = ActiveOverlay::None;

        execute_confirm_action(&mut app, &action, &tx);

        let state = match &app.active_overlay {
            ActiveOverlay::MetadataEditor(state) => state,
            other => panic!("expected restored metadata editor, got {other:?}"),
        };
        let surface = state.active_surface();
        assert!(surface.pending_embedded_cuesheet_delete);
        assert!(!surface.embedded_cuesheet_present);
        assert!(surface.sidecar_cuesheet_shadow_present);
        assert!(surface.dirty, "confirmed deletion must stage a save-path tombstone");
        let cue = surface
            .entries
            .iter()
            .find(|entry| entry.display_key.eq_ignore_ascii_case("CUESHEET"))
            .expect("sidecar CUESHEET row after reshape");
        assert_eq!(cue.per_file_values.first().map(String::as_str), Some(sidecar.as_str()));
        let title = surface
            .entries
            .iter()
            .find(|entry| entry.display_key.eq_ignore_ascii_case("TITLE"))
            .expect("reshaped title row");
        assert_eq!(title.per_file_values.len(), 3);
        assert!(title.per_file_values.iter().any(|value| value.contains("Sidecar Track 3")));
        assert_eq!(std::fs::read_to_string(&sidecar_path).expect("sidecar after confirm"), sidecar);
    }

    #[test]
    fn embedded_cuesheet_validation_rejects_malformed_or_trackless_buffers() {
        let malformed_title = "TITLE Album\nFILE \"album.flac\" WAVE\n  TRACK 01 AUDIO\n    INDEX 01 00:00:00\n";
        assert!(validate_embedded_cuesheet_text(malformed_title).is_err());

        let missing_index = "TITLE \"Album\"\nFILE \"album.flac\" WAVE\n  TRACK 01 AUDIO\n    TITLE \"One\"\n";
        assert!(validate_embedded_cuesheet_text(missing_index).is_err());

        let no_tracks = "TITLE \"Album\"\nFILE \"album.flac\" WAVE\n";
        assert!(validate_embedded_cuesheet_text(no_tracks).is_err());
    }

    fn create_flac_fixture(path: &std::path::Path) -> bool {
        let status = std::process::Command::new("ffmpeg")
            .args([
                "-y",
                "-hide_banner",
                "-loglevel",
                "error",
                "-f",
                "lavfi",
                "-i",
                "sine=frequency=440:sample_rate=44100:duration=1",
                "-c:a",
                "flac",
            ])
            .arg(path)
            .stdin(std::process::Stdio::null())
            .status();
        matches!(status, Ok(status) if status.success())
    }

    fn read_cuesheet_tag(path: &std::path::Path) -> Option<String> {
        crate::tui::probe::read_all_tags_merged(&[path.to_path_buf()])
            .ok()?
            .into_iter()
            .find(|entry| entry.display_key.eq_ignore_ascii_case("CUESHEET"))
            .and_then(|entry| entry.per_file_values.first().map(|text| text.trim().to_string()))
    }

    fn fixture_cue_without_album_headers(stem: &str, side_prefix: &str, n_tracks: usize) -> String {
        let mut cue = format!("FILE \"{stem}.flac\" WAVE\n");
        for track in 1..=n_tracks {
            let total_seconds = (track - 1) * 30;
            let minutes = total_seconds / 60;
            let seconds = total_seconds % 60;
            cue.push_str(&format!(
                "  TRACK {track:02} AUDIO\n    TITLE \"{side_prefix} Track {track}\"\n    INDEX 01 {minutes:02}:{seconds:02}:00\n"
            ));
        }
        cue
    }

    fn create_dsotm_sidecar_fixture(
        album: &std::path::Path,
        include_album_headers: bool,
    ) -> (std::path::PathBuf, std::path::PathBuf) {
        std::fs::create_dir_all(album).expect("album dir");
        let side_a = album.join("tdsotm_a.flac");
        let side_b = album.join("tdsotm_b.flac");
        assert!(create_flac_fixture(&side_a), "side A flac fixture");
        assert!(create_flac_fixture(&side_b), "side B flac fixture");
        let side_a_cue = if include_album_headers {
            fixture_cue("tdsotm_a", "The Dark Side Of The Moon (Side A)", "A", 5)
        } else {
            fixture_cue_without_album_headers("tdsotm_a", "A", 5)
        };
        let side_b_cue = if include_album_headers {
            fixture_cue("tdsotm_b", "The Dark Side Of The Moon (Side B)", "B", 5)
        } else {
            fixture_cue_without_album_headers("tdsotm_b", "B", 5)
        };
        std::fs::write(album.join("tdsotm_a.cue"), side_a_cue).expect("side A cue");
        std::fs::write(album.join("tdsotm_b.cue"), side_b_cue).expect("side B cue");
        (side_a, side_b)
    }

    fn build_dsotm_unified_editor(
        album: &std::path::Path,
    ) -> Box<crate::tui::app::MetadataEditorState> {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut surfaces = collect_metadata_cue_surfaces(&[album.to_path_buf()]);
        let mut active_surface = 0usize;
        apply_cached_or_ladder_split_cue_grouping_to_metadata_surfaces(
            &mut app,
            &mut surfaces,
            &mut active_surface,
        );
        let (state, n_tracks) = build_metadata_editor_for_cue_surfaces(
            &mut app,
            &surfaces,
            active_surface,
        )
        .expect("production unified CUE editor builder");
        assert_eq!(n_tracks, 10, "DSOTM-shaped fixture must expose ten rows");
        assert!(state.active_surface().cue_album_synthetic_sheet.is_some());
        state
    }

    fn dsotm_authoritative_embedded_sheet(album_title: &str) -> String {
        let mut cue = format!(
            "CATALOG EOP-80778\nPERFORMER \"Pink Floyd\"\nTITLE \"{album_title}\"\nREM DATE 1973\nREM GENRE \"Rock\"\nFILE \"tdsotm_a.flac\" WAVE\n"
        );
        for track in 1..=5 {
            let total_seconds = (track - 1) * 30;
            cue.push_str(&format!(
                "  TRACK {track:02} AUDIO\n    TITLE \"A Track {track}\"\n    INDEX 01 {:02}:{:02}:00\n",
                total_seconds / 60,
                total_seconds % 60,
            ));
        }
        cue.push_str("FILE \"tdsotm_b.flac\" WAVE\n");
        for track in 6..=10 {
            let local = track - 5;
            let total_seconds = (local - 1) * 30;
            cue.push_str(&format!(
                "  TRACK {track:02} AUDIO\n    TITLE \"B Track {local}\"\n    INDEX 01 {:02}:{:02}:00\n",
                total_seconds / 60,
                total_seconds % 60,
            ));
        }
        cue
    }

    fn dsotm_unified_sheet_model(album: &std::path::Path) -> crate::tui::app::CueAlbumSyntheticSheet {
        let mut surfaces = collect_metadata_cue_surfaces(&[album.to_path_buf()]);
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut active_surface = 0usize;
        apply_cached_or_ladder_split_cue_grouping_to_metadata_surfaces(
            &mut app,
            &mut surfaces,
            &mut active_surface,
        );
        let (sheet, _track_numbers, _track_titles, _track_artists, _isrcs, _warnings) =
            build_unified_cue_album_sheet(&surfaces).expect("unified sheet model");
        sheet
    }

    #[test]
    fn planner_and_editor_embedded_authority_acceptance_stay_in_lockstep() {
        if !fixture_tool_available("ffmpeg") {
            eprintln!("skipping: ffmpeg unavailable");
            return;
        }
        let temp = tempfile::tempdir().expect("tempdir");
        let album = temp.path().join("dsotm");
        let (side_a, side_b) = create_dsotm_sidecar_fixture(&album, true);
        let sheet = dsotm_unified_sheet_model(&album);
        let member_audio = vec![side_a.clone(), side_b.clone()];

        let accepted = dsotm_authoritative_embedded_sheet(
            "The Dark Side of the Moon (Japan Toshiba Harvest-Odeon EOP-80778 LP / 24-192)",
        );
        for image in [&side_a, &side_b] {
            crate::tui::probe::write_all_tags(
                image,
                &[(lofty::tag::ItemKey::Unknown("CUESHEET".to_string()), Some(accepted.clone()))],
            )
            .expect("write accepted CUESHEET");
        }
        let editor_accepts = cue_album_authoritative_embedded_cuesheet(
            &sheet,
            &[accepted.clone(), accepted.clone()],
            member_audio.len(),
        )
        .is_some();
        let planner_accepts = crate::convert::queue_expansion::planner_authoritative_embedded_cuesheet_accepts_for_test(
            &member_audio,
            &album,
        );
        assert_eq!(planner_accepts, editor_accepts, "planner/editor authority must agree for identical regenerated multi-FILE sheets");
        assert!(planner_accepts);

        let differing = dsotm_authoritative_embedded_sheet("Different Embedded Title");
        crate::tui::probe::write_all_tags(
            &side_b,
            &[(lofty::tag::ItemKey::Unknown("CUESHEET".to_string()), Some(differing.clone()))],
        )
        .expect("write differing CUESHEET");
        let editor_accepts = cue_album_authoritative_embedded_cuesheet(
            &sheet,
            &[accepted.clone(), differing],
            member_audio.len(),
        )
        .is_some();
        let planner_accepts = crate::convert::queue_expansion::planner_authoritative_embedded_cuesheet_accepts_for_test(
            &member_audio,
            &album,
        );
        assert_eq!(planner_accepts, editor_accepts, "planner/editor authority must both reject differing member sheets");
        assert!(!planner_accepts);

        let stale_subset = fixture_cue("tdsotm_a", "Stale Side A Only", "A", 5);
        for image in [&side_a, &side_b] {
            crate::tui::probe::write_all_tags(
                image,
                &[(lofty::tag::ItemKey::Unknown("CUESHEET".to_string()), Some(stale_subset.clone()))],
            )
            .expect("write stale subset CUESHEET");
        }
        let editor_accepts = cue_album_authoritative_embedded_cuesheet(
            &sheet,
            &[stale_subset.clone(), stale_subset],
            member_audio.len(),
        )
        .is_some();
        let planner_accepts = crate::convert::queue_expansion::planner_authoritative_embedded_cuesheet_accepts_for_test(
            &member_audio,
            &album,
        );
        assert_eq!(planner_accepts, editor_accepts, "planner/editor authority must both reject stale subset sheets");
        assert!(!planner_accepts);
    }

    #[test]
    fn unified_editor_uses_plain_editor_canonical_order_and_alias_deduplication() {
        if !fixture_tool_available("ffmpeg") {
            eprintln!("skipping: ffmpeg unavailable");
            return;
        }
        let temp = tempfile::tempdir().expect("tempdir");
        let album = temp.path().join("dsotm");
        let (side_a, side_b) = create_dsotm_sidecar_fixture(&album, true);
        for image in [&side_a, &side_b] {
            crate::tui::probe::write_all_tags(
                image,
                &[
                    (lofty::tag::ItemKey::Unknown("Year".to_string()), Some("1973".to_string())),
                    (lofty::tag::ItemKey::Unknown("Album Artist".to_string()), Some("Pink Floyd".to_string())),
                    (lofty::tag::ItemKey::Unknown("Composer".to_string()), Some("Pink Floyd".to_string())),
                    (lofty::tag::ItemKey::Unknown("Performer".to_string()), Some("Pink Floyd".to_string())),
                    (lofty::tag::ItemKey::Unknown("TotalTracks".to_string()), Some("10".to_string())),
                    (lofty::tag::ItemKey::Unknown("DiscNumber".to_string()), Some("1".to_string())),
                    (lofty::tag::ItemKey::Unknown("TotalDiscs".to_string()), Some("1".to_string())),
                    (lofty::tag::ItemKey::Unknown("Comment".to_string()), Some("fixture".to_string())),
                ],
            )
            .expect("write alias tags");
        }

        let state = build_dsotm_unified_editor(&album);
        let keys: Vec<&str> = state
            .active_surface()
            .entries
            .iter()
            .map(|entry| entry.display_key.as_str())
            .collect();
        let expected_prefix = [
            "TITLE",
            "ARTIST",
            "ALBUM",
            "DATE",
            "GENRE",
            "COMPOSER",
            "PERFORMER",
            "ALBUMARTIST",
            "TRACKNUMBER",
            "TRACKTOTAL",
            "DISCNUMBER",
            "DISCTOTAL",
            "COMMENT",
        ];
        assert_eq!(&keys[..expected_prefix.len()], expected_prefix, "unified surface must share the plain editor's standard key order: {keys:?}");
        assert_eq!(keys.iter().filter(|key| key.eq_ignore_ascii_case("DATE")).count(), 1, "Year alias must collapse into DATE: {keys:?}");
        assert_eq!(keys.iter().filter(|key| key.eq_ignore_ascii_case("YEAR")).count(), 0, "raw Year row must not survive normalization: {keys:?}");
        assert_eq!(keys.iter().filter(|key| key.eq_ignore_ascii_case("ALBUMARTIST")).count(), 1, "Album Artist alias must collapse into ALBUMARTIST: {keys:?}");
        assert_eq!(keys.iter().filter(|key| key.eq_ignore_ascii_case("Album Artist")).count(), 0, "raw Album Artist row must not survive normalization: {keys:?}");
        assert!(keys.last().map(|key| key.eq_ignore_ascii_case("CUESHEET")).unwrap_or(false), "CUESHEET synthetic row stays at the tail: {keys:?}");
    }

