#[cfg(test)]
mod mb_picker_verification_lifecycle_tests {
    use super::*;
    use crate::config::TonepoetConfig;
    use crate::tui::app::{
        ActiveOverlay, ActiveTagsMbOperation, MetadataEditorState, MetadataTechnicalDetails,
        MbSelectPhase, MbSelectState,
    };
    use crate::tui::message::{AppMessage, TagsMbOperationId};
    use crate::tui::probe::{RowScope, TagEntry};
    use lofty::tag::ItemKey;
    use std::time::Duration;

    fn album_entry(value: &str) -> TagEntry {
        TagEntry {
            row_scope: RowScope::File,
            display_key: "ALBUM".to_string(),
            item_key: ItemKey::AlbumTitle,
            value: value.to_string(),
            original: value.to_string(),
            is_binary: false,
            is_mixed: false,
            has_multiple_stored_values: false,
            per_file_stored_value_counts: Vec::new(),
            per_file_values: vec![value.to_string()],
            per_file_originals: vec![value.to_string()],
            mb_proposed_value: None,
            mb_proposed_per_file: None,
        }
    }

    fn release(id: &str, title: &str) -> crate::tui::musicbrainz::MbRelease {
        crate::tui::musicbrainz::MbRelease {
            release_id: id.to_string(),
            title: title.to_string(),
            disc_count: 2,
            tracks: vec![
                crate::tui::musicbrainz::MbTrack {
                    position: 1,
                    title: "Track One".to_string(),
                    ..Default::default()
                },
                crate::tui::musicbrainz::MbTrack {
                    position: 2,
                    title: "Track Two".to_string(),
                    ..Default::default()
                },
            ],
            ..Default::default()
        }
    }

    fn app_with_parked_editor_and_picker(
        worker_tx: &mpsc::Sender<AppMessage>,
    ) -> AppState {
        let path = std::env::temp_dir().join("tonepoet-mb-verification-race.flac");
        let mut editor = Box::new(MetadataEditorState::for_files(
            vec![path.clone()],
            vec![album_entry("Original Album")],
            vec!["Single image".to_string()],
            MetadataTechnicalDetails::default(),
        ));
        editor.model.tags_mb_in_flight = true;

        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.pending_metadata_editor = Some(editor);
        app.active_overlay = ActiveOverlay::MbSelect(Box::new(MbSelectState::new(
            vec![
                release("release-a", "Replacement Album"),
                release("release-b", "Alternate Album"),
            ],
            vec![path],
        )));
        app.tui_tx = Some(worker_tx.clone());
        app
    }

    #[test]
    fn metadata_editor_close_invalidates_direct_mb_apply_operation() {
        let (worker_tx, _worker_rx) = mpsc::channel(1);
        let path = std::env::temp_dir().join("tonepoet-mb-direct-close.flac");
        let mut state = Box::new(MetadataEditorState::for_files(
            vec![path],
            vec![album_entry("Original Album")],
            vec!["Single image".to_string()],
            MetadataTechnicalDetails::default(),
        ));
        state.model.tags_mb_in_flight = true;

        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.tags_mb_operation_generation = 7;
        app.active_tags_mb_operation = Some(ActiveTagsMbOperation {
            operation_id: TagsMbOperationId(7),
            picker_owned: false,
            phase: crate::tui::app::TagsMbOperationPhase::Verifying,
        });

        request_metadata_editor_close(&mut app, &mut state, &worker_tx);

        assert!(app.active_tags_mb_operation.is_none());
        assert!(!state.model.tags_mb_in_flight);
        assert!(matches!(app.active_overlay, ActiveOverlay::None));
    }

    #[tokio::test]
    async fn enter_then_escape_rejects_delayed_mb_apply_completion() {
        let (worker_tx, mut worker_rx) = mpsc::channel(8);
        let mut app = app_with_parked_editor_and_picker(&worker_tx);

        handle_overlay_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            &worker_tx,
        );
        assert!(matches!(
            &app.active_overlay,
            ActiveOverlay::MbSelect(state)
                if matches!(state.phase, MbSelectPhase::Verifying { .. })
        ));
        assert!(app.active_tags_mb_operation.is_some());

        handle_overlay_key(
            &mut app,
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
            &worker_tx,
        );
        assert!(app.active_tags_mb_operation.is_none());

        let completion = tokio::time::timeout(Duration::from_secs(5), worker_rx.recv())
            .await
            .expect("verification worker should finish")
            .expect("verification worker should send a completion");
        crate::tui::event_loop::handle_message(&mut app, completion, &worker_tx);

        let ActiveOverlay::MetadataEditor(state) = &app.active_overlay else {
            panic!("cancelled verification must leave the parked editor restored");
        };
        let album = state
            .active_surface()
            .entries
            .iter()
            .find(|entry| entry.display_key == "ALBUM")
            .expect("ALBUM row");
        assert_eq!(album.value, "Original Album");
        assert!(album.mb_proposed_value.is_none());
        assert!(state.mb_back.is_none());
        assert!(!state.model.tags_mb_in_flight);
    }

    #[tokio::test]
    async fn repeated_enter_during_verification_cannot_start_a_second_apply() {
        let (worker_tx, mut worker_rx) = mpsc::channel(8);
        let mut app = app_with_parked_editor_and_picker(&worker_tx);

        handle_overlay_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            &worker_tx,
        );
        let first_generation = app.tags_mb_operation_generation;
        let first_operation = app
            .active_tags_mb_operation
            .expect("first Enter should own an operation")
            .operation_id;

        handle_overlay_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            &worker_tx,
        );

        assert_eq!(app.tags_mb_operation_generation, first_generation);
        assert_eq!(
            app.active_tags_mb_operation.map(|active| active.operation_id),
            Some(first_operation)
        );
        assert!(matches!(
            &app.active_overlay,
            ActiveOverlay::MbSelect(state)
                if state.phase.verifying_operation() == Some(first_operation)
        ));
        assert!(app
            .status_message
            .as_ref()
            .is_some_and(|(message, _)| message.contains("already in progress")));

        handle_overlay_key(
            &mut app,
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
            &worker_tx,
        );
        let completion = tokio::time::timeout(Duration::from_secs(5), worker_rx.recv())
            .await
            .expect("the one scheduled worker should finish")
            .expect("the one scheduled worker should send a completion");
        crate::tui::event_loop::handle_message(&mut app, completion, &worker_tx);
        assert!(
            tokio::time::timeout(Duration::from_millis(100), worker_rx.recv())
                .await
                .is_err(),
            "repeated Enter scheduled a second completion"
        );
    }
}

#[cfg(test)]
mod metadata_editor_inline_navigation_tests {
    use super::*;
    use crate::config::TonepoetConfig;
    use crate::tui::app::{
        FileReadState, FileWriteEligibility, MetadataEditorPhase, MetadataEditorState,
        MetadataTechnicalDetails,
    };
    use crate::tui::probe::{MetadataReadIssue, MetadataReadIssueKind, RowScope, TagEntry};
    use lofty::tag::ItemKey;

    fn tx() -> mpsc::Sender<AppMessage> {
        let (tx, _rx) = mpsc::channel(4);
        tx
    }

    fn entry(
        key: &str,
        item_key: ItemKey,
        values: &[&str],
        mixed: bool,
    ) -> TagEntry {
        let per_file_values: Vec<String> = values.iter().map(|value| (*value).to_string()).collect();
        let value = if mixed {
            "<multiple values>".to_string()
        } else {
            per_file_values.first().cloned().unwrap_or_default()
        };
        TagEntry {
            row_scope: RowScope::File,
            display_key: key.to_string(),
            item_key,
            value: value.clone(),
            original: value,
            is_binary: false,
            is_mixed: mixed,
            has_multiple_stored_values: false,
            per_file_stored_value_counts: Vec::new(),
            per_file_originals: per_file_values.clone(),
            per_file_values,
            mb_proposed_value: None,
            mb_proposed_per_file: None,
        }
    }

    fn editor(entries: Vec<TagEntry>, path_count: usize) -> Box<MetadataEditorState> {
        let paths: Vec<std::path::PathBuf> = (0..path_count)
            .map(|idx| std::path::PathBuf::from(format!("track-{idx}.flac")))
            .collect();
        let labels: Vec<String> = paths
            .iter()
            .map(|path| path.display().to_string())
            .collect();
        Box::new(MetadataEditorState::for_files(
            paths,
            entries,
            labels,
            MetadataTechnicalDetails::default(),
        ))
    }

    #[test]
    fn tab_commits_main_inline_edit_and_skips_mixed_row() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut state = editor(
            vec![
                entry("TITLE", ItemKey::TrackTitle, &["old", "old"], false),
                entry("ARTIST", ItemKey::TrackArtist, &["one", "two"], true),
                entry("ALBUM", ItemKey::AlbumTitle, &["album", "album"], false),
            ],
            2,
        );
        state.cursor = 0;
        state.phase = MetadataEditorPhase::InlineEdit;
        state.edit_input = Some(super::super::text_input::TextInputState::new_selected(
            "new title".to_string(),
        ));

        handle_metadata_editor_key(
            &mut app,
            KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE),
            &mut state,
            &tx(),
        );

        assert_eq!(
            state.active_surface().entries[0].per_file_values,
            vec!["new title".to_string(), "new title".to_string()]
        );
        assert_eq!(state.cursor, 2, "mixed row must be skipped by the documented policy");
        assert_eq!(state.phase, MetadataEditorPhase::InlineEdit);
        assert_eq!(
            state.edit_input.as_ref().map(|input| input.text.as_str()),
            Some("album")
        );
        assert!(state.active_surface().dirty);
    }

    #[test]
    fn detail_tab_commits_current_slot_and_enters_next_editable_slot() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut state = editor(
            vec![entry("TITLE", ItemKey::TrackTitle, &["one", "two"], true)],
            2,
        );
        state.phase = MetadataEditorPhase::DetailEdit;
        state.detail_field_idx = 0;
        state.detail_cursor = 0;
        state.detail_edit = Some(super::super::text_input::TextInputState::new_selected(
            "replacement".to_string(),
        ));

        handle_metadata_editor_key(
            &mut app,
            KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE),
            &mut state,
            &tx(),
        );

        assert_eq!(state.active_surface().entries[0].per_file_values[0], "replacement");
        assert_eq!(state.detail_cursor, 1);
        assert_eq!(
            state.detail_edit.as_ref().map(|input| input.text.as_str()),
            Some("two")
        );
        assert!(state.active_surface().dirty);
    }

    #[test]
    fn alt_apply_cancels_uncommitted_key_name_and_does_not_dispatch_save() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut state = editor(
            vec![entry("TITLE", ItemKey::TrackTitle, &["unchanged"], false)],
            1,
        );
        state.phase = MetadataEditorPhase::AddingKey;
        state.add_key_input = Some(super::super::text_input::TextInputState::new(
            "UNCOMMITTED".to_string(),
        ));

        handle_metadata_editor_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('a'), KeyModifiers::ALT),
            &mut state,
            &tx(),
        );

        assert_eq!(state.phase, MetadataEditorPhase::Editing);
        assert!(state.add_key_input.is_none());
        assert!(!state.any_presentation_dirty());
        assert_eq!(
            app.status_message.as_ref().map(|(message, _)| message.as_str()),
            Some("metadata editor: no changes to apply")
        );
    }

    #[test]
    fn detail_browse_tab_moves_without_starting_an_edit() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let mut state = editor(
            vec![entry("TITLE", ItemKey::TrackTitle, &["one", "two"], true)],
            2,
        );
        state.phase = MetadataEditorPhase::DetailEdit;
        state.detail_field_idx = 0;
        state.detail_cursor = 0;
        state.detail_edit = None;

        handle_metadata_editor_key(
            &mut app,
            KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE),
            &mut state,
            &tx(),
        );

        assert_eq!(state.phase, MetadataEditorPhase::DetailEdit);
        assert_eq!(state.detail_cursor, 1);
        assert!(state.detail_edit.is_none());

        handle_metadata_editor_key(
            &mut app,
            KeyEvent::new(KeyCode::BackTab, KeyModifiers::SHIFT),
            &mut state,
            &tx(),
        );

        assert_eq!(state.detail_cursor, 0);
        assert!(state.detail_edit.is_none());
    }

    #[test]
    fn alt_ok_commits_inline_phase_before_running_the_clean_close_flow() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.active_overlay = ActiveOverlay::MetadataEditor(editor(
            vec![entry("TITLE", ItemKey::TrackTitle, &["unchanged"], false)],
            1,
        ));
        let mut state = editor(
            vec![entry("TITLE", ItemKey::TrackTitle, &["unchanged"], false)],
            1,
        );
        state.cursor = 0;
        state.phase = MetadataEditorPhase::InlineEdit;
        state.edit_input = Some(super::super::text_input::TextInputState::new_selected(
            "unchanged".to_string(),
        ));

        handle_metadata_editor_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('o'), KeyModifiers::ALT),
            &mut state,
            &tx(),
        );

        assert_eq!(state.phase, MetadataEditorPhase::Editing);
        assert!(state.edit_input.is_none());
        assert!(!state.any_presentation_dirty());
        assert!(matches!(app.active_overlay, ActiveOverlay::None));
    }

    #[test]
    fn escape_cancels_current_inline_metadata_write_before_overlay_dispatch() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let path = std::path::PathBuf::from("album.dsf");
        let (_operation_id, cancel) = app.begin_inline_metadata_write(path);
        assert!(!cancel.is_cancelled());

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
            &tx(),
        );

        assert!(cancel.is_cancelled());
        assert_eq!(
            app.status_message.as_ref().map(|(message, _)| message.as_str()),
            Some("Cancelling metadata write...")
        );
    }

    #[test]
    fn container_quirk_is_readable_but_explicitly_write_blocked() {
        let path = std::path::Path::new("quirky.dsf");
        let issue = MetadataReadIssue {
            kind: MetadataReadIssueKind::ContainerQuirk,
            reason: "declared size mismatch; repair before editing".to_string(),
        };

        let (read_state, write_state) =
            metadata_file_states_for_open(path, None, None, Some(&issue));

        assert_eq!(read_state, FileReadState::Readable);
        assert_eq!(
            write_state,
            FileWriteEligibility::Blocked {
                reason: issue.reason,
            }
        );
    }
}
